def _cancel_repository_manuscript_turns(
    session: Session, analyses: Sequence[RepositoryAnalysisRow], *, purge_terminal: bool
) -> None:
    """Fence creator-private prose/proposal work before source erasure."""
    resource_ids = {row.public_id for row in analyses}
    if not resource_ids:
        return
    turns = list(
        session.scalars(
            select(AgentTurnRow)
            .where(
                AgentTurnRow.org_id.in_({row.org_id for row in analyses}),
                AgentTurnRow.resource_kind.in_(_CREATOR_PRIVATE_AGENT_TURN_KINDS),
                AgentTurnRow.resource_id.in_(resource_ids),
            )
            .order_by(AgentTurnRow.id)
            .with_for_update()
        ).all()
    )
    for turn in turns:
        if turn.status in {"queued", "running", "cancel_requested"}:
            _signal_agent_turn_cancel(turn.org_id, turn.turn_id)
            request_agent_turn_cancel(session, turn.id)
            finish_ai_action(
                session,
                agent_turn_action_id(turn.org_id, turn.turn_id),
                status="cancelled",
            )
    if purge_terminal and turns:
        turn_ids = [turn.id for turn in turns]
        session.execute(delete(AgentEventRow).where(AgentEventRow.turn_id.in_(turn_ids)))
        session.execute(delete(AgentTurnRow).where(AgentTurnRow.id.in_(turn_ids)))


def _detach_user_for_deletion(session: Session, user_id: int) -> set[str]:
    """Remove one member without breaking the workspace they contributed to.

    Auth credentials, personal connectors, agent timelines, reports, votes,
    collaboration grants and ephemeral presence are removed. Durable research
    contributions and workspace share links remain usable but lose their user
    reference. Commercial acceptance records remain as content-minimal
    statutory receipts with no account link.
    """
    repository_connection_statement = (
        select(RepositoryConnectionRow)
        .where(RepositoryConnectionRow.creator_user_id == user_id)
        .order_by(RepositoryConnectionRow.id)
    )
    if session.get_bind().dialect.name != "sqlite":
        repository_connection_statement = repository_connection_statement.with_for_update()
    session.scalars(repository_connection_statement).all()
    repository_statement = (
        select(RepositoryAnalysisRow)
        .where(RepositoryAnalysisRow.creator_user_id == user_id)
        .order_by(RepositoryAnalysisRow.id)
    )
    if session.get_bind().dialect.name != "sqlite":
        repository_statement = repository_statement.with_for_update()
    creator_repository_analyses = list(session.scalars(repository_statement).all())
    _cancel_repository_manuscript_turns(session, creator_repository_analyses, purge_terminal=False)
    paper_chat_run_ids = list(
        session.scalars(
            select(CompanionPaperChatReceiptRow.run_id).where(
                CompanionPaperChatReceiptRow.user_id == user_id,
                CompanionPaperChatReceiptRow.run_id.is_not(None),
            )
        ).all()
    )
    removable_checksums: set[str] = set()
    for run_id in paper_chat_run_ids:
        run = session.get(Run, run_id)
        if run is not None:
            removable_checksums.update(_delete_run_rows(session, run))
    pending_asks = list(
        session.scalars(
            select(LiveCompanionAskRow).where(
                LiveCompanionAskRow.user_id == user_id,
                LiveCompanionAskRow.status == "pending",
            )
        ).all()
    )
    cancel_live_ask_jobs(session, [row.id for row in pending_asks])
    for row in pending_asks:
        finish_ai_action(session, row.action_id, status="cancelled")
    document_statement = (
        select(BrainstormProjectDocumentRow)
        .where(BrainstormProjectDocumentRow.user_id == user_id)
        .order_by(BrainstormProjectDocumentRow.project_id, BrainstormProjectDocumentRow.id)
    )
    if session.get_bind().dialect.name != "sqlite":
        document_statement = document_statement.with_for_update()
    session.scalars(document_statement).all()
    synthesis_statement = (
        select(BrainstormProjectSynthesisRow)
        .where(
            BrainstormProjectSynthesisRow.user_id == user_id,
            BrainstormProjectSynthesisRow.status == "pending",
        )
        .order_by(BrainstormProjectSynthesisRow.id)
    )
    if session.get_bind().dialect.name != "sqlite":
        synthesis_statement = synthesis_statement.with_for_update()
    pending_project_syntheses = list(session.scalars(synthesis_statement).all())
    cancel_project_brainstorm_jobs(
        session, [synthesis.id for synthesis in pending_project_syntheses]
    )
    for project_synthesis in pending_project_syntheses:
        finish_ai_action(session, project_synthesis.action_id, status="cancelled")
    active_enrichments = list(
        session.scalars(
            select(PaperEnrichmentRow).where(
                PaperEnrichmentRow.user_id == user_id,
                PaperEnrichmentRow.status.in_(("queued", "running")),
            )
        ).all()
    )
    cancel_paper_enrichment_jobs(session, [row.id for row in active_enrichments])
    active_repository_analyses = [
        row
        for row in creator_repository_analyses
        if row.status in {"queued", "fetching", "analyzing"}
    ]
    cancel_repository_analysis_jobs(session, [row.id for row in active_repository_analyses])
    for repository_analysis in active_repository_analyses:
        finish_ai_action(session, repository_analysis.action_id, status="cancelled")
    repository_analysis_ids = [row.id for row in creator_repository_analyses]
    if repository_analysis_ids:
        pending_figure_statement = (
            select(FigureRow)
            .where(
                FigureRow.repository_analysis_id.in_(repository_analysis_ids),
                FigureRow.status == "pending",
            )
            .order_by(FigureRow.id)
        )
        if session.get_bind().dialect.name != "sqlite":
            pending_figure_statement = pending_figure_statement.with_for_update()
        pending_repository_figures = list(session.scalars(pending_figure_statement).all())
        cancel_figure_jobs(session, [figure.id for figure in pending_repository_figures])
        for figure in pending_repository_figures:
            figure.status = "error"
            figure.error = "Repository grounding was removed before rendering completed."
            _finish_resource_actions(session, "figure", figure.id, status="cancelled")
        session.execute(
            update(FigureRow)
            .where(FigureRow.repository_analysis_id.in_(repository_analysis_ids))
            .values(repository_analysis_id=None)
        )
    connector_ids = select(ReferenceConnectorRow.id).where(ReferenceConnectorRow.user_id == user_id)
    agent_turn_ids = select(AgentTurnRow.id).where(AgentTurnRow.user_id == user_id)
    session.execute(
        delete(ReferenceConnectorItemRow).where(
            ReferenceConnectorItemRow.connector_id.in_(connector_ids)
        )
    )
    session.execute(delete(AgentEventRow).where(AgentEventRow.turn_id.in_(agent_turn_ids)))
    for column in _USER_REFERENCE_NULLIFY_COLUMNS:
        model = column.class_
        session.execute(update(model).where(column == user_id).values({column.key: None}))
    for model in _USER_REFERENCE_DELETE_MODELS:
        session.execute(delete(model).where(model.user_id == user_id))
    for column in _USER_REFERENCE_DELETE_COLUMNS:
        session.execute(delete(column.class_).where(column == user_id))
    return removable_checksums


def _tenant_purge_order() -> list[type[Any]]:
    """Return every tenant model in child-before-parent FK order.

    The explicit model inventory makes code review and retention decisions
    visible. The topological sort prevents the list order itself from becoming
    another fragile, manually maintained foreign-key contract.
    """
    by_table = {model.__tablename__: model for model in _TENANT_PURGE_MODELS}
    dependencies: dict[str, set[str]] = {name: set() for name in by_table}
    indegree = {name: 0 for name in by_table}
    for child_name, model in by_table.items():
        for foreign_key in model.__table__.foreign_keys:
            parent_name = foreign_key.target_fullname.split(".", 1)[0]
            if parent_name == child_name or parent_name not in by_table:
                continue
            if parent_name not in dependencies[child_name]:
                dependencies[child_name].add(parent_name)
                indegree[parent_name] += 1
    ready = sorted((name for name, degree in indegree.items() if degree == 0))
    ordered: list[type[Any]] = []
    while ready:
        child_name = ready.pop(0)
        ordered.append(by_table[child_name])
        for parent_name in sorted(dependencies[child_name]):
            indegree[parent_name] -= 1
            if indegree[parent_name] == 0:
                ready.append(parent_name)
                ready.sort()
    if len(ordered) != len(by_table):
        blocked = sorted((name for name, degree in indegree.items() if degree > 0))
        raise RuntimeError(f"tenant purge model graph contains a cycle: {blocked}")
    return ordered


def _remove_tree_missing_ok(path: Path) -> None:
    """Remove one artifact tree while still surfacing real storage errors."""
    try:
        shutil.rmtree(path)
    except FileNotFoundError:
        return


@dataclass(frozen=True)
class _WorkspaceErasureArtifacts:
    """Identifiers needed to remove owned files after the DB commit succeeds."""

    writer_ids: tuple[int, ...]
    template_ids: tuple[int, ...]
    figure_ids: tuple[int, ...]
    datasets: tuple[tuple[int, str], ...]
    interview_ids: tuple[int, ...]
    document_checksums: frozenset[str]
    removable_checksums: tuple[str, ...] = ()


def _capture_workspace_erasure_artifacts(
    session: Session, org_id: int
) -> _WorkspaceErasureArtifacts:
    return _WorkspaceErasureArtifacts(
        writer_ids=tuple(
            session.scalars(
                select(WriterDocumentRow.id).where(WriterDocumentRow.org_id == org_id)
            ).all()
        ),
        template_ids=tuple(
            session.scalars(
                select(WriterTemplateRow.id).where(WriterTemplateRow.org_id == org_id)
            ).all()
        ),
        figure_ids=tuple(
            session.scalars(select(FigureRow.id).where(FigureRow.org_id == org_id)).all()
        ),
        datasets=tuple(
            (
                (dataset_id, filename)
                for dataset_id, filename in session.execute(
                    select(ResearchDatasetRow.id, ResearchDatasetRow.filename).where(
                        ResearchDatasetRow.org_id == org_id
                    )
                ).all()
            )
        ),
        interview_ids=tuple(
            session.scalars(select(InterviewRow.id).where(InterviewRow.org_id == org_id)).all()
        ),
        document_checksums=frozenset(
            checksum
            for checksum in session.scalars(
                select(DocumentRow.checksum).where(
                    DocumentRow.org_id == org_id, DocumentRow.checksum.is_not(None)
                )
            ).all()
            if checksum is not None
        ),
    )


def _cleanup_workspace_erasure_artifacts(
    artifacts: _WorkspaceErasureArtifacts, settings: Settings | None = None
) -> None:
    """Remove files captured before a committed workspace erasure."""
    settings = settings or get_settings()
    for writer_id in artifacts.writer_ids:
        (settings.data_dir / "writer" / f"{writer_id}.pdf").unlink(missing_ok=True)
        (settings.data_dir / "writer" / f"{writer_id}.synctex.gz").unlink(missing_ok=True)
        _remove_tree_missing_ok(settings.data_dir / "writer" / str(writer_id))
    for template_id in artifacts.template_ids:
        _remove_tree_missing_ok(settings.data_dir / "writer_templates" / str(template_id))
    for figure_id in artifacts.figure_ids:
        (settings.data_dir / "figures" / f"{figure_id}.png").unlink(missing_ok=True)
        (settings.data_dir / "figures" / f"{figure_id}-input.png").unlink(missing_ok=True)
    for dataset_id, filename in artifacts.datasets:
        (settings.data_dir / "datasets" / f"{dataset_id}-{Path(filename).name}").unlink(
            missing_ok=True
        )
        _remove_tree_missing_ok(settings.data_dir / "datasets" / "versions" / str(dataset_id))
    for interview_id in artifacts.interview_ids:
        _remove_tree_missing_ok(settings.data_dir / "interviews" / str(interview_id))
    _cleanup_document_checksums(artifacts.removable_checksums, settings)


def _cleanup_document_checksums(checksums: Iterable[str], settings: Settings | None = None) -> None:
    """Remove document derivatives only after their ledger deletion commits."""
    settings = settings or get_settings()
    for checksum in sorted(set(checksums)):
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            elif session.get_bind().dialect.name == "postgresql":
                _capture_transaction_lock(session, 0, f"checksum:{checksum}")
            if session.scalar(
                select(func.count())
                .select_from(DocumentRow)
                .where(DocumentRow.checksum == checksum)
            ):
                continue
            (settings.documents_dir / "blobs" / checksum[:2] / checksum).unlink(missing_ok=True)
            (settings.documents_dir / "text" / f"{checksum}.txt").unlink(missing_ok=True)
            _remove_tree_missing_ok(
                settings.documents_dir / "translations" / checksum[:2] / checksum
            )


_PRIVACY_EXPORT_SENSITIVE_COLUMN_FRAGMENTS = (
    "credential",
    "password",
    "recovery_hash",
    "secret",
    "storage_path",
    "token_hash",
)
_PRIVACY_EXPORT_SENSITIVE_NESTED_FRAGMENTS = (
    *_PRIVACY_EXPORT_SENSITIVE_COLUMN_FRAGMENTS,
    "access_key",
    "api_key",
    "authorization",
    "passcode",
    "token",
)
_PRIVACY_EXPORT_SENSITIVE_COLUMNS = {
    "background_jobs": {"lease_owner", "lease_token"},
    "run_shares": {"token"},
    "surveys": {"public_id"},
    "voice_invites": {"passcode", "public_id"},
    "voice_sessions": {"public_id"},
    "writer_comments": {"author_key"},
    "writer_shares": {"password_hash", "token"},
    "writer_template_shares": {"token"},
}


def _privacy_export_safe_value(value: Any) -> Any:
    """Convert one database value to JSON while removing nested secrets."""
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, bytes):
        return base64.b64encode(value).decode("ascii")
    if isinstance(value, dict):
        return {
            str(key): _privacy_export_safe_value(item)
            for key, item in value.items()
            if not any(
                fragment in str(key).lower()
                for fragment in _PRIVACY_EXPORT_SENSITIVE_NESTED_FRAGMENTS
            )
        }
    if isinstance(value, (list, tuple)):
        return [_privacy_export_safe_value(item) for item in value]
    return value


def _privacy_export_figure_config(value: Any) -> Any:
    """Remove creator-private repository bindings from workspace exports."""
    if not isinstance(value, dict):
        return value
    source = copy.deepcopy(value)
    repository = source.get("repository")
    if not isinstance(repository, dict) or repository.get("repository_access") != "private":
        return source
    source["repository"] = {
        key: repository[key]
        for key in (
            "repository_access",
            "diagram_kind",
            "verification_status",
            "spec_node_count",
            "spec_edge_count",
        )
        if key in repository
    }
    source.pop("repository_grounding", None)
    source.pop("repository_provenance", None)
    source.pop("repository_grounding_sha256", None)
    return source


def _privacy_export_row(row: Any, *, current_user_id: int) -> dict[str, Any]:
    """Serialize one ORM row without credentials or another member's identity."""
    exported: dict[str, Any] = {}
    table_name = row.__table__.name
    private_repository_figure = (
        table_name == "figures"
        and isinstance(getattr(row, "config", None), dict)
        and (
            (getattr(row, "config", {}).get("repository") or {}).get("repository_access")
            == "private"
        )
    )
    sensitive_columns = _PRIVACY_EXPORT_SENSITIVE_COLUMNS.get(table_name, set())
    for column in row.__table__.columns:
        name = column.name
        if name in sensitive_columns or any(
            fragment in name.lower() for fragment in _PRIVACY_EXPORT_SENSITIVE_COLUMN_FRAGMENTS
        ):
            continue
        value = getattr(row, name)
        if table_name == "figures" and name == "config":
            value = _privacy_export_figure_config(value)
        elif private_repository_figure and name == "repository_analysis_id":
            value = None
        elif (
            table_name == "writer_contributions"
            and name == "payload"
            and isinstance(value, dict)
            and (value.get("repository_access") == "private")
        ):
            value = {
                "repository_access": "private",
                "verification_status": str(value.get("verification_status") or "passed"),
            }
        points_to_user = any(
            foreign_key.target_fullname == "users.id" for foreign_key in column.foreign_keys
        )
        if points_to_user and value not in (None, current_user_id):
            value = None
        exported[name] = _privacy_export_safe_value(value)
    return exported


def _privacy_export_tables(
    session: Session, *, user: User
) -> tuple[dict[str, list[dict[str, Any]]], dict[str, Any]]:
    """Build the machine-readable, secret-free account/workspace snapshot."""
    tables: dict[str, list[dict[str, Any]]] = {
        "account": [_privacy_export_row(user, current_user_id=user.id)]
    }
    org = session.get(Org, user.org_id)
    if org is None:
        raise HTTPException(404, "workspace not found")
    private_runs = [
        run
        for run in session.scalars(select(Run).where(Run.org_id == user.org_id)).all()
        if _companion_paper_run_owner(run) is not None
    ]
    own_private_run_ids = {
        run.id for run in private_runs if _companion_paper_run_owner(run) == user.id
    }
    other_private_run_ids = {run.id for run in private_runs} - own_private_run_ids
    private_documents = session.scalars(
        select(DocumentRow).where(
            DocumentRow.org_id == user.org_id,
            DocumentRow.run_id.in_({run.id for run in private_runs}),
        )
    ).all()
    own_private_document_ids = {
        document.id for document in private_documents if document.run_id in own_private_run_ids
    }
    other_private_document_ids = {
        document.id for document in private_documents if document.run_id in other_private_run_ids
    }
    private_repository_turns = session.scalars(
        select(AgentTurnRow).where(
            AgentTurnRow.org_id == user.org_id,
            AgentTurnRow.resource_kind.in_(_CREATOR_PRIVATE_AGENT_TURN_KINDS),
        )
    ).all()
    other_private_repository_turn_ids = {
        turn.id for turn in private_repository_turns if turn.user_id != user.id
    }
    repository_analyses = session.scalars(
        select(RepositoryAnalysisRow).where(RepositoryAnalysisRow.org_id == user.org_id)
    ).all()
    own_repository_analyses = [row for row in repository_analyses if row.creator_user_id == user.id]
    other_repository_analyses = [
        row for row in repository_analyses if row.creator_user_id != user.id
    ]
    own_repository_analysis_id_strings = {str(row.id) for row in own_repository_analyses}
    own_repository_action_ids = {row.action_id for row in own_repository_analyses}
    other_repository_action_ids = {row.action_id for row in other_repository_analyses}
    if user.role == "owner":
        tables["workspace"] = [_privacy_export_row(org, current_user_id=user.id)]
    else:
        tables["workspace"] = [
            {
                "id": org.id,
                "name": org.name,
                "plan": org.plan,
                "created_at": org.created_at.isoformat(),
            }
        ]
    excluded_models = {AuthToken, User}
    for model in _TENANT_PURGE_MODELS:
        if model in excluded_models:
            continue
        if model in _PERSONAL_EXPORT_MODELS:
            owner_column = (
                KnowledgePageRow.creator_user_id
                if model is KnowledgePageRow
                else RepositoryConnectionRow.creator_user_id
                if model is RepositoryConnectionRow
                else RepositoryAnalysisRow.creator_user_id
                if model is RepositoryAnalysisRow
                else cast(Any, model).user_id
            )
            rows = session.scalars(select(model).where(owner_column == user.id)).all()
        elif user.role == "owner":
            rows = session.scalars(select(model).where(model.org_id == user.org_id)).all()
        else:
            user_columns = [
                column
                for column in model.__table__.columns
                if any(
                    foreign_key.target_fullname == "users.id" for foreign_key in column.foreign_keys
                )
            ]
            personal_conditions: list[Any] = [
                getattr(model, column.name) == user.id for column in user_columns
            ]
            run_columns = [
                column
                for column in model.__table__.columns
                if any(
                    foreign_key.target_fullname == "runs.id" for foreign_key in column.foreign_keys
                )
            ]
            document_columns = [
                column
                for column in model.__table__.columns
                if any(
                    foreign_key.target_fullname == "documents.id"
                    for foreign_key in column.foreign_keys
                )
            ]
            if model is Run and own_private_run_ids:
                personal_conditions.append(Run.id.in_(own_private_run_ids))
            for column in run_columns:
                if own_private_run_ids:
                    personal_conditions.append(getattr(model, column.name).in_(own_private_run_ids))
            for column in document_columns:
                if own_private_document_ids:
                    personal_conditions.append(
                        getattr(model, column.name).in_(own_private_document_ids)
                    )
            if not personal_conditions:
                continue
            rows = session.scalars(
                select(model).where(model.org_id == user.org_id, or_(*personal_conditions))
            ).all()
        if model is AgentTurnRow:
            rows = [
                row
                for row in rows
                if getattr(row, "resource_kind", "") not in _CREATOR_PRIVATE_AGENT_TURN_KINDS
                or getattr(row, "user_id", None) == user.id
            ]
        elif model is AgentEventRow and other_private_repository_turn_ids:
            rows = [
                row
                for row in rows
                if getattr(row, "turn_id", None) not in other_private_repository_turn_ids
            ]
        elif model is BackgroundJobRow:
            rows = [
                row
                for row in rows
                if not (
                    getattr(row, "task", "") == "_execute_repository_analysis"
                    and (
                        not any(
                            str(argument) in own_repository_analysis_id_strings
                            for argument in list(getattr(row, "args", None) or [])[:1]
                        )
                    )
                )
            ]
        elif model in {CapacityReservationRow, LLMCallRow, ProviderCostRow}:
            rows = [
                row
                for row in rows
                if not (
                    getattr(row, "action_id", "") in other_repository_action_ids
                    or (
                        getattr(row, "resource_type", "") == "repository_analysis"
                        and (
                            str(getattr(row, "resource_id", ""))
                            not in own_repository_analysis_id_strings
                            or getattr(row, "action_id", "") not in own_repository_action_ids
                        )
                    )
                )
            ]
        if other_private_run_ids:
            if model is Run:
                rows = [
                    row for row in rows if getattr(row, "id", None) not in other_private_run_ids
                ]
            else:
                run_reference_names = {
                    column.name
                    for column in model.__table__.columns
                    if any(
                        foreign_key.target_fullname == "runs.id"
                        for foreign_key in column.foreign_keys
                    )
                }
                rows = [
                    row
                    for row in rows
                    if all(
                        getattr(row, name, None) not in other_private_run_ids
                        for name in run_reference_names
                    )
                ]
        if other_private_document_ids:
            document_reference_names = {
                column.name
                for column in model.__table__.columns
                if any(
                    foreign_key.target_fullname == "documents.id"
                    for foreign_key in column.foreign_keys
                )
            }
            rows = [
                row
                for row in rows
                if all(
                    getattr(row, name, None) not in other_private_document_ids
                    for name in document_reference_names
                )
            ]
        if rows:
            tables[model.__tablename__] = [
                _privacy_export_row(row, current_user_id=user.id) for row in rows
            ]
    received_library_grants = session.scalars(
        select(LibraryAccessGrantRow).where(LibraryAccessGrantRow.grantee_user_id == user.id)
    ).all()
    if received_library_grants:
        table_name = LibraryAccessGrantRow.__tablename__
        exported_ids = {row.get("id") for row in tables.get(table_name, [])}
        tables.setdefault(table_name, []).extend(
            _privacy_export_row(row, current_user_id=user.id)
            for row in received_library_grants
            if row.id not in exported_ids
        )
    work_ids: set[str] = set()
    for model in (SourceRecordRow, DocumentRow, ScreeningDecisionRow, ExtractionRow):
        if model.__tablename__ not in tables:
            continue
        work_ids.update(
            str(row["work_id"]) for row in tables[model.__tablename__] if row.get("work_id")
        )
    if work_ids:
        works = session.scalars(select(WorkRow).where(WorkRow.id.in_(work_ids))).all()
        tables[WorkRow.__tablename__] = [
            _privacy_export_row(row, current_user_id=user.id) for row in works
        ]
    inventory = {
        "scope": "workspace" if user.role == "owner" else "personal",
        "tables": {name: len(rows) for name, rows in sorted(tables.items())},
        "excluded": [
            "password hashes",
            "session and API-key hashes",
            "MFA secrets and recovery hashes",
            "connector and webhook credentials",
            "share and invitation capabilities",
            "internal storage paths",
            "other workspace members' account profiles",
        ],
    }
    return (tables, inventory)


def _privacy_export_artifacts(
    session: Session,
    *,
    org_id: int,
    user_id: int,
    settings: Settings,
    unavailable: list[dict[str, str]] | None = None,
) -> list[tuple[Path, str]]:
    """Return owner-controlled files using stable, non-host archive names."""
    artifacts: list[tuple[Path, str]] = []
    allowed_roots = (settings.data_dir.resolve(), settings.documents_dir.resolve())

    def add_file(path: Path, archive_name: str) -> None:
        if not path.is_file():
            if unavailable is not None:
                unavailable.append({"archive_path": archive_name, "reason": "not present"})
            return
        resolved = path.resolve()
        if not any(resolved.is_relative_to(root) for root in allowed_roots):
            if unavailable is not None:
                unavailable.append(
                    {"archive_path": archive_name, "reason": "outside managed storage"}
                )
            logging.getLogger(__name__).warning(
                "privacy export skipped artifact outside managed storage: %s", path
            )
            return
        artifacts.append((resolved, archive_name))

    def add_tree(path: Path, archive_root: str) -> None:
        if not path.is_dir():
            if unavailable is not None:
                unavailable.append(
                    {"archive_path": archive_root, "reason": "directory not present"}
                )
            return
        for candidate in sorted(item for item in path.rglob("*") if item.is_file()):
            add_file(candidate, f"{archive_root}/{candidate.relative_to(path)}")

    writer_ids = session.scalars(
        select(WriterDocumentRow.id).where(WriterDocumentRow.org_id == org_id)
    ).all()
    for writer_id in writer_ids:
        add_file(
            settings.data_dir / "writer" / f"{writer_id}.pdf",
            f"files/manuscripts/{writer_id}/compiled.pdf",
        )
        add_file(
            settings.data_dir / "writer" / f"{writer_id}.synctex.gz",
            f"files/manuscripts/{writer_id}/compiled.synctex.gz",
        )
        add_tree(
            settings.data_dir / "writer" / str(writer_id),
            f"files/manuscripts/{writer_id}/project",
        )
    template_ids = session.scalars(
        select(WriterTemplateRow.id).where(WriterTemplateRow.org_id == org_id)
    ).all()
    for template_id in template_ids:
        add_tree(
            settings.data_dir / "writer_templates" / str(template_id),
            f"files/templates/{template_id}",
        )
    figure_ids = session.scalars(select(FigureRow.id).where(FigureRow.org_id == org_id)).all()
    for figure_id in figure_ids:
        add_file(
            settings.data_dir / "figures" / f"{figure_id}.png",
            f"files/figures/{figure_id}.png",
        )
        add_file(
            settings.data_dir / "figures" / f"{figure_id}-input.png",
            f"files/figures/{figure_id}-input.png",
        )
    datasets = session.execute(
        select(ResearchDatasetRow.id, ResearchDatasetRow.filename).where(
            ResearchDatasetRow.org_id == org_id
        )
    ).all()
    for dataset_id, filename in datasets:
        add_file(
            settings.data_dir / "datasets" / f"{dataset_id}-{Path(filename).name}",
            f"files/datasets/{dataset_id}/{Path(filename).name}",
        )
        add_tree(
            settings.data_dir / "datasets" / "versions" / str(dataset_id),
            f"files/datasets/{dataset_id}/versions",
        )
    interview_ids = session.scalars(
        select(InterviewRow.id).where(InterviewRow.org_id == org_id)
    ).all()
    for interview_id in interview_ids:
        add_tree(
            settings.data_dir / "interviews" / str(interview_id),
            f"files/interviews/{interview_id}",
        )
    documents = session.scalars(select(DocumentRow).where(DocumentRow.org_id == org_id)).all()
    for document in documents:
        if document.run_id is not None:
            run = session.get(Run, document.run_id)
            if run is None or not _run_visible_to_user(run, user_id):
                continue
        document_id = document.id
        checksum = document.checksum
        storage_path = document.storage_path
        if storage_path:
            add_file(Path(storage_path), f"files/library/{document_id}/document.pdf")
        if checksum:
            add_file(
                settings.documents_dir / "text" / f"{checksum}.txt",
                f"files/library/{document_id}/extracted.txt",
            )
            add_tree(
                settings.documents_dir / "translations" / checksum[:2] / checksum,
                f"files/library/{document_id}/translations",
            )
    return artifacts


def _privacy_export_stream(file: Any) -> Iterator[bytes]:
    """Stream and close a spooled archive even when the client disconnects."""
    try:
        while chunk := file.read(1024 * 1024):
            yield chunk
    finally:
        file.close()


def _purge_org(session: Session, org_id: int) -> None:
    """Delete a workspace and EVERY tenant-scoped row it owns, in FK-safe
    order (rows referencing runs first, then runs, then the rest). Shared
    works stay — they are global records, not tenant data. Unlike a single
    run deletion, this drops the org's LLM-call and credit rows too: the
    workspace is gone, so there is no local usage history to keep. Used by owner
    self-deletion and operator-initiated account removal."""
    org_user_ids = select(User.id).where(User.org_id == org_id)
    session.execute(
        delete(LibraryAccessGrantRow).where(LibraryAccessGrantRow.grantee_user_id.in_(org_user_ids))
    )
    org_run_ids = select(Run.id).where(Run.org_id == org_id)
    session.execute(delete(CreditEventRow).where(CreditEventRow.run_id.in_(org_run_ids)))
    for model in _tenant_purge_order():
        session.execute(delete(model).where(model.org_id == org_id))
    org = session.get(Org, org_id)
    if org is not None:
        session.delete(org)


def _record_and_purge_workspace(
    session: Session, org_id: int, *, reason: str
) -> _WorkspaceErasureArtifacts:
    """Journal an erasure durably, then purge its active database records."""
    user = session.scalar(
        select(User).where(User.org_id == org_id).order_by((User.role == "owner").desc(), User.id)
    )
    if user is None:
        raise ErasureLedgerError(f"workspace {org_id} has no identity anchor")
    append_event(
        get_settings(),
        subject="workspace",
        reason=reason,
        email=user.email,
        org_id=org_id,
        user_id=user.id,
    )
    return _purge_workspace_database(session, org_id)


def _purge_workspace_database(session: Session, org_id: int) -> _WorkspaceErasureArtifacts:
    """Purge one workspace after its journal entry has already been verified."""
    artifacts = _capture_workspace_erasure_artifacts(session, org_id)
    _purge_org(session, org_id)
    session.flush()
    removable = tuple(
        checksum
        for checksum in artifacts.document_checksums
        if not session.scalar(
            select(func.count()).select_from(DocumentRow).where(DocumentRow.checksum == checksum)
        )
    )
    return _WorkspaceErasureArtifacts(
        writer_ids=artifacts.writer_ids,
        template_ids=artifacts.template_ids,
        figure_ids=artifacts.figure_ids,
        datasets=artifacts.datasets,
        interview_ids=artifacts.interview_ids,
        document_checksums=artifacts.document_checksums,
        removable_checksums=removable,
    )


def _record_and_detach_member(session: Session, user: User, *, reason: str) -> set[str]:
    """Journal and remove one member while preserving workspace research."""
    append_event(
        get_settings(),
        subject="member",
        reason=reason,
        email=user.email,
        org_id=user.org_id,
        user_id=user.id,
    )
    removable_checksums = _detach_user_for_deletion(session, user.id)
    session.delete(user)
    session.flush()
    return removable_checksums


def _email_token_hash(raw: str) -> str:
    return hashlib.sha256(raw.encode()).hexdigest()


def _send_email_best_effort(recipient: str, rendered: RenderedEmail, settings: Settings) -> None:
    """Deliver an account email after the HTTP response without leaking state."""
    try:
        send_email(recipient, rendered, settings=settings)
    except MailDeliveryError:
        logging.getLogger(__name__).exception("account email delivery failed")


def _cleanup_expired_unverified_accounts(
    session: Session, artifact_cleanup: list[_WorkspaceErasureArtifacts] | None = None
) -> int:
    """Remove abandoned public signups after the stated seven-day window."""
    cutoff = datetime.now(UTC) - timedelta(days=7)
    rows = session.scalars(
        select(User).where(
            User.email_verified_at.is_(None),
            User.created_at <= cutoff,
            User.role == "owner",
        )
    ).all()
    removed = 0
    for row in rows:
        verified_users = int(
            session.scalar(
                select(func.count(User.id)).where(
                    User.org_id == row.org_id, User.email_verified_at.is_not(None)
                )
            )
            or 0
        )
        if verified_users == 0:
            artifacts = _record_and_purge_workspace(
                session, row.org_id, reason="unverified_signup_expired"
            )
            if artifact_cleanup is not None:
                artifact_cleanup.append(artifacts)
            removed += 1
    return removed


def _delete_run_rows(session: Session, run: Run) -> set[str]:
    """Delete a run and its tenant-scoped rows. Shared works stay (they are
    global records), and LLM spend is kept for local usage auditing with the run reference
    detached."""
    session.execute(update(LLMCallRow).where(LLMCallRow.run_id == run.id).values(run_id=None))
    session.execute(
        update(ProviderCostRow).where(ProviderCostRow.run_id == run.id).values(run_id=None)
    )
    session.execute(
        update(CreditEventRow).where(CreditEventRow.run_id == run.id).values(run_id=None)
    )
    session.execute(
        update(FigureRow).where(FigureRow.context_run_id == run.id).values(context_run_id=None)
    )
    reservations = session.scalars(
        select(CapacityReservationRow).where(CapacityReservationRow.run_id == run.id)
    ).all()
    for reservation in reservations:
        if reservation.status == "active":
            finish_ai_action(session, reservation.action_id, status="deleted")
        reservation.run_id = None
    session.execute(
        delete(CompanionPaperChatReceiptRow).where(CompanionPaperChatReceiptRow.run_id == run.id)
    )
    run_documents = list(
        session.scalars(select(DocumentRow).where(DocumentRow.run_id == run.id)).all()
    )
    document_ids = [document.id for document in run_documents]
    candidate_checksums = {document.checksum for document in run_documents if document.checksum}
    if document_ids:
        session.execute(
            update(WriterSourceRow)
            .where(WriterSourceRow.source_document_id.in_(document_ids))
            .values(source_document_id=None)
        )
        session.execute(
            delete(DocumentAnnotationRow).where(DocumentAnnotationRow.document_id.in_(document_ids))
        )
        session.execute(
            delete(BrowserCaptureReceiptRow).where(
                BrowserCaptureReceiptRow.org_id == run.org_id,
                BrowserCaptureReceiptRow.document_id.in_(document_ids),
            )
        )
        session.execute(
            delete(BrowserCapturedPaperMetadataRow).where(
                BrowserCapturedPaperMetadataRow.org_id == run.org_id,
                BrowserCapturedPaperMetadataRow.document_id.in_(document_ids),
            )
        )
    for model in (
        RunEvent,
        ScreeningDecisionRow,
        SourceRecordRow,
        DocumentRow,
        WebSourceRow,
        ConversationReviewRow,
        ChatTurnEventRow,
        ChatTurnRow,
        ChatMessageRow,
        ReportRow,
        ExtractionRow,
        RiskOfBiasRow,
        RunShareRow,
    ):
        session.execute(delete(model).where(model.run_id == run.id))
    session.delete(run)
    session.flush()
    return {
        checksum
        for checksum in candidate_checksums
        if not session.scalar(
            select(func.count()).select_from(DocumentRow).where(DocumentRow.checksum == checksum)
        )
    }


def _finish_resource_actions(
    session: Session,
    resource_type: str,
    resource_id: str | int,
    *,
    status: str = "deleted",
) -> None:
    rows = session.scalars(
        select(CapacityReservationRow).where(
            CapacityReservationRow.resource_type == resource_type,
            CapacityReservationRow.resource_id == str(resource_id),
            CapacityReservationRow.status == "active",
        )
    ).all()
    for row in rows:
        finish_ai_action(session, row.action_id, status=status)


def _http_402(exc: EntitlementError) -> HTTPException:
    status = 429 if "capacity" in exc.code or "limit" in exc.code else 403
    return HTTPException(status, {"error": str(exc), "code": exc.code})


def _require_web_search_runtime(requested: bool) -> None:
    """Reject unavailable web-search work before any capacity is reserved.

    The public capability contract exposes only this boolean result; API keys
    and the separate processor-terms confirmation remain server-side.
    """
    if requested and (not get_settings().websearch_enabled):
        raise HTTPException(
            409,
            {
                "code": "web_search_unavailable",
                "message": "Web source search is not available on this deployment.",
            },
        )


def _require_pubmed_runtime(requested: bool) -> None:
    """Reject PubMed retrieval unless the deployment explicitly enables it."""

    if requested and not get_settings().pubmed_ready:
        raise HTTPException(
            409,
            {
                "code": "pubmed_unavailable",
                "message": "PubMed discovery is not available on this deployment.",
            },
        )


def _require_public_web_search_scope(requested: bool, confirmed: bool) -> None:
    """Require an explicit per-run acknowledgement before web-search egress."""
    if requested and (not confirmed):
        raise HTTPException(
            422,
            {
                "code": "web_search_public_scope_confirmation_required",
                "message": "Confirm that the web search uses only public, non-confidential search terms and contains no personal or sensitive data.",
            },
        )


def _require_public_chat_web_search_scope(
    question: str,
    confirmed: bool,
    query: str | None = None,
    *,
    require_topic: bool = True,
) -> None:
    """Fail before charging when this chat turn could expose Sonar.

    The intent helper excludes exact URLs, which stay on the separately
    constrained webpage-reader path. Runtime availability is included so a
    disabled provider does not ask users to attest to processing that cannot
    occur.
    """
    explicit = explicit_web_research_request(question)
    if query is not None and (not explicit or not confirmed):
        raise HTTPException(
            422,
            {
                "code": "web_search_public_scope_confirmation_required",
                "message": "Confirm the public search terms for this web-search request.",
            },
        )
    if get_settings().websearch_enabled and explicit:
        _require_public_web_search_scope(True, confirmed)
        if require_topic and query is None and web_search_topic_required(question):
            raise HTTPException(
                422,
                {
                    "code": "web_search_topic_required",
                    "message": "Name the public topic you want to search for.",
                },
            )


def _confirmed_persisted_web_search(config: dict[str, Any] | None) -> bool:
    """Return the only persisted state that may authorize Sonar execution."""
    value = config or {}
    return bool(value.get("web_search") and value.get("web_search_public_data_confirmed"))


def _protocol_web_search_scope_sha256(question: str, protocol: ReviewProtocol) -> str:
    """Bind a protocol-gate acknowledgement to the exact visible scope."""
    canonical = json.dumps(
        {
            "question": question,
            "protocol": protocol.model_dump(mode="json", exclude={"synthesized_by"}),
        },
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _confirmed_protocol_web_search(
    config: dict[str, Any] | None, *, question: str, protocol: ReviewProtocol
) -> bool:
    """Require a fresh acknowledgement bound to this approved protocol."""
    value = config or {}
    recorded = str(value.get("web_search_protocol_scope_sha256") or "")
    expected = _protocol_web_search_scope_sha256(question, protocol)
    return bool(
        _confirmed_persisted_web_search(value)
        and recorded
        and secrets.compare_digest(recorded, expected)
    )


def _resume_config_without_unconfirmed_web_search(session: Session, run: Run) -> dict[str, Any]:
    """Migrate legacy resumptions to scholarly-only retrieval, fail closed."""
    config = dict(run.config or {})
    if not config.get("web_search") or _confirmed_persisted_web_search(config):
        return config
    config["web_search"] = False
    run.config = config
    session.add(
        RunEvent(
            org_id=run.org_id,
            run_id=run.id,
            stage="web_search",
            event="web_search_skipped",
            payload={
                "reason": "A fresh public-data confirmation was not recorded for this run.",
                "resume_scope": "scholarly_sources_only",
            },
        )
    )
    return config


def _require_capability(session: Session, ctx: AuthContext, capability: Capability) -> Plan:
    """Enforce a product bundle without duplicating 402 response plumbing."""
    org = session.get(Org, ctx.org_id)
    assert org is not None
    try:
        return check_capability(org, capability)
    except EntitlementError as exc:
        raise _http_402(exc) from exc


def _require_storage(
    session: Session,
    ctx: AuthContext,
    incoming_bytes: int,
    *,
    document_checksum: str | None = None,
) -> Plan:
    """Enforce workspace storage before a persistent file is written."""
    org = session.get(Org, ctx.org_id)
    assert org is not None
    try:
        return check_storage_available(
            session, org, incoming_bytes, document_checksum=document_checksum
        )
    except StorageCapacityError as exc:
        raise HTTPException(503, str(exc)) from exc
    except EntitlementError as exc:
        raise _http_402(exc) from exc


def _uses_expert_query(query: str | None) -> bool:
    """Detect explicit Boolean/field syntax while keeping plain keyword searches free."""
    if not query:
        return False
    return bool(re.search("\\b(?:AND|OR|NOT)\\b|(?:title|abstract|author|doi):|[()*]", query))


def _attach_documents(
    session: Session, ctx: AuthContext, run_id: int, document_ids: list[int]
) -> None:
    """Attach Library documents without transferring their ownership.

    A Library row is durable workspace data and can feed several chats. Each
    run therefore receives its own acquisition-ledger clone; deleting or
    reusing one chat can never move or destroy the original Library item.
    """
    for document_id in dict.fromkeys(document_ids):
        library_doc = session.get(DocumentRow, document_id)
        if library_doc is None or library_doc.org_id != ctx.org_id:
            raise HTTPException(404, f"document {document_id} not found")
        if library_doc.run_id is not None:
            raise HTTPException(404, f"document {document_id} not found")
        run = session.get(Run, run_id)
        if run is None or run.org_id != ctx.org_id:
            raise HTTPException(404, "run not found")
        captured = session.scalar(
            select(BrowserCapturedPaperMetadataRow).where(
                BrowserCapturedPaperMetadataRow.org_id == ctx.org_id,
                BrowserCapturedPaperMetadataRow.document_id == library_doc.id,
            )
        )
        doc = DocumentRow(
            org_id=library_doc.org_id,
            run_id=None,
            project_id=run.project_id,
            folder=library_doc.folder,
            work_id=library_doc.work_id,
            status=library_doc.status,
            source=library_doc.source,
            legal_basis=library_doc.legal_basis,
            license=library_doc.license,
            version=library_doc.version,
            url=library_doc.url,
            content_type=library_doc.content_type,
            checksum=library_doc.checksum,
            byte_size=library_doc.byte_size,
            storage_path=library_doc.storage_path,
            text_status=library_doc.text_status,
            reason=library_doc.reason,
            retrieved_at=library_doc.retrieved_at,
        )
        session.add(doc)
        session.flush()
        if captured is not None and doc is not library_doc:
            session.add(
                BrowserCapturedPaperMetadataRow(
                    org_id=captured.org_id,
                    user_id=captured.user_id,
                    document_id=doc.id,
                    title=captured.title,
                    authors=list(captured.authors or []),
                    doi=captured.doi,
                    published_at=captured.published_at,
                    description=captured.description,
                    source_url=captured.source_url,
                    canonical_url=captured.canonical_url,
                    canonical_url_hash=hashlib.sha256(
                        f"run:{run_id}:{captured.canonical_url}".encode()
                    ).hexdigest(),
                    provenance={
                        **dict(captured.provenance or {}),
                        "library_document_id": library_doc.id,
                    },
                )
            )
        attach_document_to_run(session, doc, run_id)
        work = session.get(WorkRow, doc.work_id)
        title = (
            captured.title
            if captured and captured.title
            else work.title
            if work
            else "Uploaded document"
        )
        session.add(
            ChatMessageRow(
                org_id=ctx.org_id,
                run_id=run_id,
                role="tool",
                content=f"Attached {title[:70]}",
                payload={
                    "tool": "add_document",
                    "query": title,
                    "reason": "the user attached a document",
                    "results": [
                        {
                            "id": doc.work_id,
                            "title": title,
                            "verified": is_verified_work_id(doc.work_id),
                        }
                    ],
                    "document_id": doc.id,
                },
            )
        )


_SSE_MAX_SECONDS = 3600
_GENERIC_RUN_FAILURE = "Something went wrong while running this search. Please try again; if it keeps failing, contact support."
_CORPUS_UNAVAILABLE_MESSAGE = (
    "Scholarly search is still being prepared on this server. Please try again in a few minutes."
)
_PUBMED_RUNTIME_UNAVAILABLE_MESSAGE = (
    "PubMed discovery became unavailable before this search could run. "
    "Please retry after it is enabled again."
)


class _PubMedRuntimeUnavailableError(RuntimeError):
    """Internal fail-closed signal for a requested PubMed search arm."""


def _public_run_error(value: object) -> str | None:
    """Expose only fixed product copy from a durable worker error field."""
    raw = str(value or "").strip()
    if not raw:
        return None
    if raw in {
        _GENERIC_RUN_FAILURE,
        _CORPUS_UNAVAILABLE_MESSAGE,
        _PUBMED_RUNTIME_UNAVAILABLE_MESSAGE,
    }:
        return raw
    return _GENERIC_RUN_FAILURE


def _public_synthesis_method(value: object) -> str:
    """Reduce internal routing metadata to a user-safe provenance label."""
    raw = str(value or "").strip().lower()
    if raw == "user":
        return "user"
    if raw == "heuristic":
        return "heuristic"
    return "automated"


def _public_protocol_payload(payload: dict[str, Any] | None) -> dict[str, Any]:
    public = dict(payload or {})
    public["synthesized_by"] = _public_synthesis_method(public.get("synthesized_by"))
    return public


def _public_report_payload(payload: dict[str, Any] | None) -> dict[str, Any]:
    """Remove the private synthesis route from a report returned to clients."""
    public = dict(payload or {})
    if "model" in public:
        public["ai_generated_sections"] = bool(public.pop("model"))
    return public


def _public_reviewer(value: object) -> str:
    """Expose the review role without leaking the internal provider route."""
    reviewer = str(value or "")
    if reviewer.startswith("human:"):
        return reviewer
    if reviewer.startswith("fulltext:"):
        return "full-text-review"
    if reviewer.startswith("adjudicator:"):
        return "independent-adjudication"
    if reviewer.startswith("ensemble"):
        return reviewer
    return "automated-review"


def _public_review_reason(value: object) -> str:
    """Expose a concise rationale without provider names or leaked prompt text."""
    reason = str(value or "").strip()
    if reason.startswith("{"):
        partial_reason = re.search('"reason"\\s*:\\s*"((?:\\\\.|[^"\\\\])*)"', reason)
        if partial_reason is not None:
            with contextlib.suppress(json.JSONDecodeError):
                reason = json.loads(f'"{partial_reason.group(1)}"')
        try:
            decoded, _ = json.JSONDecoder().raw_decode(reason)
            if isinstance(decoded, dict) and decoded.get("reason"):
                reason = str(decoded["reason"]).strip()
        except (json.JSONDecodeError, TypeError, ValueError):
            pass
    reason = re.sub(
        "\\b(?:openrouter|deepseek(?:[-/][\\w.-]+)?|gemini(?:[-/][\\w.-]+)?)(?=\\s+(?:reviewer|model)\\b)",
        "automated",
        reason,
        flags=re.IGNORECASE,
    )
    return reason


def _public_usage_payload(payload: dict[str, Any]) -> dict[str, Any]:
    """Keep task-level usage while hiding the private provider topology."""
    public = dict(payload)
    public.pop("by_provider", None)
    return public


def _public_event_payload(payload: object) -> object:
    """Keep provider/model routing in the private ledger, never in client events."""
    if isinstance(payload, list):
        return [_public_event_payload(item) for item in payload]
    if not isinstance(payload, dict):
        return payload
    public: dict[str, Any] = {}
    for key, value in payload.items():
        if key in {
            "provider",
            "model",
            "corpus_size",
            "corpus_version",
            "catalog_size",
        }:
            continue
        if key == "synthesized_by":
            public[key] = _public_synthesis_method(value)
        else:
            public[key] = _public_event_payload(value)
    return public


def _event_stream(run_id: int, org_id: int) -> Iterator[str]:
    """Server-sent events over the append-only run_events log until the run is
    terminal. Independent of the executor: the durable arq worker (H1) changes
    how a run is driven, not how its progress is streamed."""
    poll_seconds = max(0.1, min(1.0, get_settings().run_events_poll_seconds))
    last_id = 0
    waited = 0.0
    while waited <= _SSE_MAX_SECONDS:
        status: str | None = None
        batch: list[tuple[int, str, str, dict[str, Any]]] = []
        with db_session() as session:
            run = session.get(Run, run_id)
            if run is None or run.org_id != org_id:
                return
            status = run.status
            events = session.scalars(
                select(RunEvent)
                .where(RunEvent.run_id == run_id, RunEvent.id > last_id)
                .order_by(RunEvent.id)
            ).all()
            batch = [
                (
                    e.id,
                    e.stage,
                    e.event,
                    cast(dict[str, Any], _public_event_payload(e.payload)),
                )
                for e in events
            ]
        for eid, stage, event, payload in batch:
            last_id = eid
            data = json.dumps({"id": eid, "stage": stage, "event": event, "payload": payload})
            yield f"event: {event}\ndata: {data}\n\n"
        if status in ("completed", "failed", "cancelled"):
            yield f"event: done\ndata: {json.dumps({'status': status})}\n\n"
            return
        time.sleep(poll_seconds)
        waited += poll_seconds


