_BERLIN_TIME_ZONE = ZoneInfo("Europe/Berlin")


def _berlin_calendar_date(instant: datetime | None = None) -> date:
    """Return the German calendar date for an aware instant."""
    observed_at = instant or datetime.now(UTC)
    if observed_at.utcoffset() is None:
        raise ValueError("The calendar-date instant must include a timezone.")
    return observed_at.astimezone(_BERLIN_TIME_ZONE).date()


