class WriterPdfSelectionSegment(BaseModel):
    """One browser selection range and the PDF pages it crosses."""

    model_config = ConfigDict(extra="forbid")
    quote: str = Field(min_length=1, max_length=WRITER_SELECTION_MAX_CHARACTERS)
    page: int = Field(ge=1, le=WRITER_SELECTION_MAX_PAGE)
    page_end: int | None = Field(default=None, ge=1, le=WRITER_SELECTION_MAX_PAGE)

    @field_validator("quote")
    @classmethod
    def _nonblank_quote(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("selection segment quote must not be blank")
        return value

    @model_validator(mode="after")
    def _ordered_pages(self) -> "WriterPdfSelectionSegment":
        if self.page_end is not None and self.page_end < self.page:
            raise ValueError("selection segment page_end must not precede page")
        if (self.page_end or self.page) - self.page + 1 > WRITER_SELECTION_MAX_PAGE_SPAN:
            raise ValueError("selection segment crosses too many pages")
        return self


class WriterChatSelection(BaseModel):
    """Complete, bounded provenance for source and compiled-PDF selections."""

    model_config = ConfigDict(extra="forbid")
    kind: Literal["pdf", "source"]
    quote: str = Field(
        min_length=WRITER_SELECTION_MIN_CHARACTERS,
        max_length=WRITER_SELECTION_MAX_CHARACTERS,
    )
    page: int | None = Field(default=None, ge=1, le=WRITER_SELECTION_MAX_PAGE)
    page_end: int | None = Field(default=None, ge=1, le=WRITER_SELECTION_MAX_PAGE)
    segments: list[WriterPdfSelectionSegment] = Field(
        default_factory=list, max_length=WRITER_SELECTION_MAX_SEGMENTS
    )
    line: int | None = Field(default=None, ge=1, le=10000000)
    line_end: int | None = Field(default=None, ge=1, le=10000000)
    path: str | None = Field(default=None, min_length=1, max_length=300)
    pdf_x: float | None = Field(default=None, ge=0, le=100000)
    pdf_y: float | None = Field(default=None, ge=0, le=100000)

    @field_validator("quote")
    @classmethod
    def _nonblank_selection(cls, value: str) -> str:
        if len(value.strip()) < WRITER_SELECTION_MIN_CHARACTERS:
            raise ValueError("selection quote is too short")
        return value

    @field_validator("path")
    @classmethod
    def _safe_selection_path(cls, value: str | None) -> str | None:
        if value is None:
            return None
        try:
            return safe_project_path(value)
        except LatexProjectImportError as exc:
            raise ValueError(str(exc)) from exc

    @model_validator(mode="after")
    def _consistent_provenance(self) -> "WriterChatSelection":
        if self.kind == "source":
            if self.line is None or self.path is None:
                raise ValueError("source selections require path and line")
            if self.line_end is not None and self.line_end < self.line:
                raise ValueError("selection line_end must not precede line")
            if (
                any(
                    value is not None
                    for value in (self.page, self.page_end, self.pdf_x, self.pdf_y)
                )
                or self.segments
            ):
                raise ValueError("source selections cannot contain PDF provenance")
            return self
        if self.page is None:
            raise ValueError("PDF selections require a page")
        if self.page_end is not None and self.page_end < self.page:
            raise ValueError("selection page_end must not precede page")
        if (self.page_end or self.page) - self.page + 1 > WRITER_SELECTION_MAX_PAGE_SPAN:
            raise ValueError("selection crosses too many pages")
        if any(value is not None for value in (self.line, self.line_end, self.path)):
            raise ValueError("PDF selections cannot contain source-selection fields")
        if (self.pdf_x is None) != (self.pdf_y is None):
            raise ValueError("PDF position provenance requires both pdf_x and pdf_y")
        if self.segments:
            combined = "\n\n".join(segment.quote for segment in self.segments)
            if combined != self.quote:
                raise ValueError("PDF selection segments must concatenate exactly to quote")
            if any(
                (
                    current.page < previous.page
                    for previous, current in zip(self.segments, self.segments[1:], strict=False)
                )
            ):
                raise ValueError("PDF selection segments must follow document page order")
            first_page = min(segment.page for segment in self.segments)
            last_page = max(segment.page_end or segment.page for segment in self.segments)
            if first_page != self.page or last_page != (self.page_end or self.page):
                raise ValueError("PDF selection segment pages must match the outer page range")
        return self


class WriterChatRequest(SpecialistTurnRequest):
    message: str = Field(min_length=1, max_length=4000)
    selection: WriterChatSelection | None = None
    model: str = Field(default="auto", max_length=60)
    active_path: str = Field(default="main.tex", min_length=1, max_length=300)


def _verified_writer_chat_selection(
    selection: WriterChatSelection | None,
    *,
    project_files: Mapping[str, str],
    pdf_path: Path,
    synctex_path: Path,
    compiled_pdf_current: bool,
) -> dict[str, Any] | None:
    """Bind a typed selection to the current manuscript artifacts."""
    if selection is None:
        return None
    payload = selection.model_dump(mode="json", exclude_none=True, exclude_defaults=True)
    if selection.kind == "source":
        assert selection.path is not None and selection.line is not None
        source = project_files.get(selection.path)
        if source is None:
            raise HTTPException(422, "selected Writer source file no longer exists")
        line_start = 0
        for _ in range(selection.line - 1):
            newline = source.find("\n", line_start)
            if newline < 0:
                line_start = -1
                break
            line_start = newline + 1
        next_newline = source.find("\n", line_start) if line_start >= 0 else -1
        line_stop = len(source) if next_newline < 0 else next_newline
        quote_search_stop = min(len(source), line_stop + len(selection.quote))
        quote_start = (
            source.find(selection.quote, line_start, quote_search_stop) if line_start >= 0 else -1
        )
        if line_start < 0 or quote_start < line_start or quote_start > line_stop:
            raise HTTPException(
                422, "selected source text no longer matches the reported file and line"
            )
        expected_line_end = selection.line + selection.quote.count("\n")
        if selection.line_end is not None and selection.line_end != expected_line_end:
            raise HTTPException(422, "selected source line range does not match its text")
        payload["line_end"] = expected_line_end
        return payload
    assert selection.page is not None
    if not compiled_pdf_current:
        raise HTTPException(409, "compile the current manuscript before discussing its PDF")
    if not pdf_path.exists():
        raise HTTPException(409, "compile the manuscript before discussing a PDF passage")
    pdf = pdf_path.read_bytes()
    end_page = selection.page_end or selection.page
    page_texts = extract_page_text_range(
        pdf, selection.page, end_page, max_span=WRITER_SELECTION_MAX_PAGE_SPAN
    )
    if page_texts is None:
        raise HTTPException(422, "selected PDF page range is outside the compiled manuscript")
    if selection.segments:
        for segment in selection.segments:
            segment_end = segment.page_end or segment.page
            relative_start = segment.page - selection.page
            relative_end = segment_end - selection.page + 1
            segment_text = "\n".join(page_texts[relative_start:relative_end])
            if not pdf_selection_matches_text(segment.quote, segment_text):
                raise HTTPException(
                    422, "selected PDF text could not be verified on its reported pages"
                )
    elif not pdf_selection_matches_text(selection.quote, "\n".join(page_texts)):
        raise HTTPException(422, "selected PDF text could not be verified on its reported pages")
    if selection.pdf_x is not None and selection.pdf_y is not None and synctex_path.exists():
        try:
            mapped = synctex_inverse(
                pdf=pdf,
                synctex=synctex_path.read_bytes(),
                page=selection.page,
                x=selection.pdf_x,
                y=selection.pdf_y,
            )
        except SynctexUnavailableError:
            mapped = None
        if mapped:
            raw_path = str(mapped.get("path") or "").replace("\\", "/")
            source_path = next(
                (
                    path
                    for path in sorted(project_files, key=len, reverse=True)
                    if raw_path == path or raw_path.endswith(f"/{path}")
                ),
                None,
            )
            source_line = int(mapped.get("line") or 0)
            if (
                source_path is not None
                and 1 <= source_line <= max(1, len(project_files[source_path].splitlines()))
                and source_region_matches_pdf_quote(
                    project_files[source_path], source_line, selection.quote
                )
            ):
                payload["source_path"] = source_path
                payload["source_line"] = source_line
    return payload


