_WRITER_APPLY_RECEIPT_KIND = "ai_edit_application"


def _writer_edit_set_fingerprint(edits: Sequence[tuple[str, str, str]]) -> str:
    """Bind an apply receipt to one ordered, path-normalized edit set."""
    canonical = json.dumps(
        [{"path": path, "find": find, "replace": replace} for path, find, replace in edits],
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )
    return hashlib.sha256(canonical.encode()).hexdigest()


def _writer_events_contain_completed_edit_set(
    events: Sequence[Mapping[str, Any]], edits: Sequence[tuple[str, str, str]]
) -> bool:
    """Recognize receipts written by releases predating explicit apply rows."""
    expected_total = len(edits)
    matched_indexes: set[int] = set()
    for event in events:
        if not (
            event.get("event") == "change.completed"
            and event.get("tool") == "manuscript.apply_change"
        ):
            continue
        try:
            index = int(event.get("index") or 0)
            total = int(event.get("total") or 0)
        except (TypeError, ValueError):
            continue
        if total != expected_total or not 1 <= index <= expected_total:
            continue
        event_input = event.get("input")
        if not isinstance(event_input, Mapping):
            continue
        signature = (
            str(event_input.get("path") or ""),
            str(event.get("before") or ""),
            str(event.get("after") or ""),
        )
        if signature == edits[index - 1]:
            matched_indexes.add(index)
    return matched_indexes == set(range(1, expected_total + 1))


