def _capture_redirect_allowed(value: str) -> bool:
    configured = {
        item.strip()
        for item in get_settings().browser_capture_redirect_uris.split(",")
        if item.strip()
    }
    return value in configured


def _capture_device_name(value: str) -> str:
    normalized = unicodedata.normalize("NFKC", value)
    visible = "".join(
        " " if character.isspace() or unicodedata.category(character).startswith("C") else character
        for character in normalized
    )
    return " ".join(visible.split()).strip()[:120] or "Chrome"


def _capture_text(value: str, limit: int) -> str:
    normalized = unicodedata.normalize("NFKC", value)
    visible = "".join(
        " " if character.isspace() or unicodedata.category(character).startswith("C") else character
        for character in normalized
    )
    return " ".join(visible.split()).strip()[:limit]


def _capture_filename_identity(value: str) -> str:
    """Normalize a filename or URL path for conservative title comparison."""
    decoded = unquote(value).rsplit("/", 1)[-1]
    without_suffix = re.sub("\\.pdf[.]*$", "", decoded, flags=re.IGNORECASE)
    return "".join(character for character in without_suffix.casefold() if character.isalnum())


def _capture_title_is_filename(title: str | None, *, filename: str, source_url: str) -> bool:
    """Identify only obvious generic or filename-derived fallback titles."""
    identity = _capture_filename_identity(title or "")
    if not identity:
        return True
    if identity in {
        "paper",
        "document",
        "content",
        "capturedpaper",
        "uploadeddocument",
    }:
        return True
    candidates = {
        _capture_filename_identity(filename),
        _capture_filename_identity(urlsplit(source_url).path),
    }
    return identity in candidates - {""}


