def _capture_arxiv_id(value: str | None) -> str:
    normalized = _capture_text(value or "", 80)
    normalized = re.sub(
        "^(?:arxiv\\s*:\\s*|https?://arxiv\\.org/(?:abs|pdf)/)",
        "",
        normalized,
        flags=re.I,
    )
    normalized = re.sub("\\.pdf$", "", normalized, flags=re.I)
    normalized = re.sub("v\\d+$", "", normalized, flags=re.I)
    if not normalized:
        return ""
    if (
        re.fullmatch("(?:\\d{4}\\.\\d{4,5}|[a-z-]+(?:\\.[A-Z]{2})?/\\d{7})", normalized, re.I)
        is None
    ):
        raise HTTPException(422, "arxiv_id is not valid")
    return normalized


def _capture_bibliographic_metadata(
    value: BrowserCaptureBibliographicMetadata | None,
) -> dict[str, Any]:
    """Normalize optional reviewed citation details without inventing values."""
    if value is None:
        return {}
    limits = {
        "container_title": 500,
        "volume": 100,
        "issue": 100,
        "pages": 100,
        "publisher": 300,
        "language": 80,
        "license": 200,
        "isbn": 100,
        "issn": 100,
        "item_type": 80,
        "subtitle": 500,
        "short_title": 500,
        "series_title": 500,
        "series_number": 100,
        "edition": 100,
        "publisher_place": 300,
        "accessed_at": 40,
        "archive": 300,
        "archive_location": 500,
        "citation_key": 200,
        "format": 200,
        "call_number": 200,
        "pmid": 80,
        "pmcid": 80,
        "extra": 2000,
    }
    normalized: dict[str, Any] = {}
    for field, limit in limits.items():
        cleaned = _capture_text(getattr(value, field) or "", limit)
        if cleaned:
            normalized[field] = cleaned
    arxiv_id = _capture_arxiv_id(value.arxiv_id)
    if arxiv_id:
        normalized["arxiv_id"] = arxiv_id
    if value.keywords:
        keywords: list[str] = []
        seen: set[str] = set()
        for raw_keyword in value.keywords:
            keyword = _capture_text(raw_keyword, 100)
            identity = keyword.casefold()
            if keyword and identity not in seen:
                keywords.append(keyword)
                seen.add(identity)
        if keywords:
            normalized["keywords"] = keywords
    return normalized


def _capture_year(published_at: str | None, fallback: int | None = None) -> int | None:
    """Parse a capture publication year without exposing malformed metadata."""
    prefix = published_at[:4] if published_at else ""
    return int(prefix) if prefix.isdigit() else fallback


def _capture_doi_identity(value: str | None) -> str:
    """Normalize a DOI only when it is suitable as a scholarly identity key."""
    normalized = unicodedata.normalize("NFKC", value or "").strip().lower()
    normalized = re.sub("^doi\\s*:\\s*", "", normalized)
    normalized = re.sub("^https?://(?:dx\\.)?doi\\.org/", "", normalized)
    normalized = normalized.strip().rstrip(".,;:")
    if re.fullmatch("10\\.\\d{4,9}/\\S+", normalized) is None:
        return ""
    arxiv = re.fullmatch("10\\.48550/arxiv\\.([^\\s]+)", normalized, re.I)
    if arxiv:
        arxiv_id = re.sub("v\\d+$", "", arxiv.group(1), flags=re.I)
        return f"10.48550/arxiv.{arxiv_id.lower()}"
    return normalized


def _capture_canonical_hash(value: str) -> str:
    return hashlib.sha256(value.encode()).hexdigest()


_LIBRARY_PAPER_METADATA_LOCK = "0:library-paper-metadata"
_LIBRARY_WEB_METADATA_LOCK = "0:library-web-metadata"
_LIBRARY_SHARE_RIGHTS_STATEMENT_VERSION = "library-share-v1"
_LIBRARY_SHARE_WRITE_LOCK = threading.RLock()
_MAX_CAPTURE_AUTHORS = 100


def _capture_metadata_identity_keys(
    *, doi_identity: str, canonical_url: str, checksum: str | None = None
) -> tuple[str, ...]:
    keys = [
        _LIBRARY_PAPER_METADATA_LOCK,
        f"canonical:{_capture_canonical_hash(canonical_url)}",
    ]
    if doi_identity:
        keys.append(f"doi:{doi_identity}")
    if checksum:
        keys.append(f"checksum:{checksum}")
    return tuple(keys)


def _merge_capture_authors(
    existing: list[str], incoming: list[str], *, max_authors: int | None = None
) -> tuple[list[str], bool]:
    """Keep reviewed order and append case-insensitively unique authors."""
    merged = list(existing)
    seen = {unicodedata.normalize("NFKC", author).casefold().strip() for author in merged}
    changed = False
    for author in incoming:
        if max_authors is not None and len(merged) >= max_authors:
            break
        identity = unicodedata.normalize("NFKC", author).casefold().strip()
        if identity and identity not in seen:
            merged.append(author)
            seen.add(identity)
            changed = True
    return (merged, changed)


def _fill_capture_metadata(
    row: BrowserCapturedPaperMetadataRow,
    *,
    title: str,
    authors: list[str],
    doi: str,
    published_at: str | None,
    description: str,
    source_url: str,
    canonical_url: str,
    provenance: Mapping[str, Any],
    pdf_checksum: str | None = None,
    author_limit: int | None = None,
) -> list[str]:
    """Fill missing org-private fields without replacing reviewed values."""
    added: list[str] = []
    existing_provenance = dict(row.provenance or {})
    manual_fields = set(existing_provenance.get("manual_fields") or [])
    scalar_values: tuple[tuple[str, Any], ...] = (
        ("title", title),
        ("doi", doi),
        ("published_at", published_at),
        ("description", description),
        ("source_url", source_url),
        ("canonical_url", canonical_url),
    )
    for field, incoming in scalar_values:
        manual_field = "abstract" if field == "description" else field
        if manual_field not in manual_fields and (not getattr(row, field)) and incoming:
            setattr(row, field, incoming)
            added.append(field)
    if "authors" not in manual_fields:
        merged_authors, authors_changed = _merge_capture_authors(
            list(row.authors or []), authors, max_authors=author_limit
        )
        if authors_changed:
            row.authors = merged_authors
            added.append("authors")
    doi_identity = _capture_doi_identity(row.doi if "doi" in manual_fields else row.doi or doi)
    if row.doi_identity is None and doi_identity:
        row.doi_identity = doi_identity
    if row.pdf_checksum is None and pdf_checksum:
        row.pdf_checksum = pdf_checksum
    merged_provenance = existing_provenance
    for key, value in provenance.items():
        if key == "bibliographic" and isinstance(value, Mapping):
            existing_bibliographic = dict(merged_provenance.get(key) or {})
            for bibliographic_key, bibliographic_value in value.items():
                if (
                    bibliographic_key not in manual_fields
                    and bibliographic_key not in existing_bibliographic
                    and (bibliographic_value not in (None, "", [], {}))
                ):
                    existing_bibliographic[bibliographic_key] = bibliographic_value
                    added.append(f"bibliographic.{bibliographic_key}")
            if existing_bibliographic:
                merged_provenance[key] = existing_bibliographic
            continue
        if key not in merged_provenance and value not in (None, "", [], {}):
            merged_provenance[key] = value
            added.append(f"provenance.{key}")
    if merged_provenance != (row.provenance or {}):
        row.provenance = merged_provenance
    return added


_LIBRARY_MISSING = object()


def _library_metadata_revision(
    metadata: Mapping[str, Any], field_provenance: Mapping[str, Any]
) -> str:
    payload = json.dumps(
        {"metadata": metadata, "field_provenance": field_provenance},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode()
    return f"sha256:{hashlib.sha256(payload).hexdigest()}"


def _library_document_components(
    rows: Sequence[DocumentRow],
    metadata_by_document: Mapping[int, BrowserCapturedPaperMetadataRow],
    works: Mapping[str, WorkRow],
) -> tuple[dict[int, DocumentRow], dict[int, list[DocumentRow]]]:
    """Group transitive checksum/DOI/canonical aliases and choose stable winners."""
    identities_by_id: dict[int, set[str]] = {}
    for document in rows:
        captured = metadata_by_document.get(document.id)
        work = works.get(document.work_id)
        doi_identity = _capture_doi_identity(
            captured.doi if captured and captured.doi else work.doi if work else None
        )
        identities = {
            identity
            for identity in (
                f"checksum:{document.checksum}" if document.checksum else "",
                f"doi:{doi_identity}" if doi_identity else "",
                f"canonical:{captured.canonical_url_hash}" if captured else "",
            )
            if identity
        }
        identities_by_id[document.id] = identities or {f"work:{document.work_id}"}
    parent = {document.id: document.id for document in rows}

    def find(document_id: int) -> int:
        while parent[document_id] != document_id:
            parent[document_id] = parent[parent[document_id]]
            document_id = parent[document_id]
        return document_id

    def union(left: int, right: int) -> None:
        left_root, right_root = (find(left), find(right))
        if left_root != right_root:
            parent[right_root] = left_root

    first_by_identity: dict[str, int] = {}
    for document_id, identities in identities_by_id.items():
        for identity in identities:
            previous = first_by_identity.setdefault(identity, document_id)
            union(document_id, previous)
    winners: dict[int, DocumentRow] = {}
    members: dict[int, list[DocumentRow]] = {}
    for document in rows:
        root = find(document.id)
        members.setdefault(root, []).append(document)
        current = winners.get(root)
        rank = (
            not bool(document.checksum and document.storage_path),
            document.run_id is not None,
            document.id,
        )
        if current is None or rank < (
            not bool(current.checksum and current.storage_path),
            current.run_id is not None,
            current.id,
        ):
            winners[root] = document
    return (winners, members)


def _library_component_metadata(
    winner: DocumentRow,
    member_documents: Sequence[DocumentRow],
    metadata_by_document: Mapping[int, BrowserCapturedPaperMetadataRow],
    works: Mapping[str, WorkRow],
) -> dict[str, Any]:
    """Resolve one deduplicated paper's reviewed, captured and corpus metadata."""
    ordered_documents = sorted(
        member_documents,
        key=lambda document: (
            document.id != winner.id,
            document.run_id is not None,
            document.id,
        ),
    )
    metadata_rows = [
        metadata_by_document[document.id]
        for document in ordered_documents
        if document.id in metadata_by_document
    ]
    capture_provenance: dict[str, Any] = {}
    for row in metadata_rows:
        for key, provenance_value in dict(row.provenance or {}).items():
            if key not in capture_provenance and provenance_value not in (
                None,
                "",
                [],
                {},
            ):
                capture_provenance[key] = provenance_value
    component_works: list[WorkRow] = []
    seen_work_ids: set[str] = set()
    for document in ordered_documents:
        work = works.get(document.work_id)
        if work is not None and work.id not in seen_work_ids:
            component_works.append(work)
            seen_work_ids.add(work.id)

    def core_row_value(row: BrowserCapturedPaperMetadataRow, field: str) -> Any:
        if field == "authors":
            return list(row.authors or [])
        if field == "abstract":
            return row.description or None
        value = getattr(row, field)
        if field == "canonical_url" and str(value or "").startswith("library:document:"):
            return None
        return value or None

    def bibliographic_row_value(row: BrowserCapturedPaperMetadataRow, field: str) -> Any:
        provenance = dict(row.provenance or {})
        if field == "selected_excerpt":
            return provenance.get(field, _LIBRARY_MISSING)
        bibliographic = dict(provenance.get("bibliographic") or {})
        return bibliographic.get(field, _LIBRARY_MISSING)

    def row_provenance(
        row: BrowserCapturedPaperMetadataRow, field: str, *, manual: bool
    ) -> dict[str, Any]:
        provenance = dict(row.provenance or {})
        recorded = dict((provenance.get("field_provenance") or {}).get(field) or {})
        return {
            "source": recorded.get("source") or ("user" if manual else "browser_capture"),
            "updated_at": recorded.get("updated_at")
            or provenance.get("captured_at")
            or row.created_at.isoformat(),
        }

    metadata: dict[str, Any] = {}
    field_provenance: dict[str, dict[str, Any] | None] = {}

    def assign(field: str, value: Any, provenance: dict[str, Any] | None) -> None:
        metadata[field] = value
        field_provenance[field] = provenance if value not in (None, "", []) else provenance

    core_fields = (
        "title",
        "authors",
        "abstract",
        "published_at",
        "doi",
        "source_url",
        "canonical_url",
    )
    manually_resolved: set[str] = set()
    for field in core_fields:
        for row in metadata_rows:
            if field in set((row.provenance or {}).get("manual_fields") or []):
                assign(
                    field,
                    core_row_value(row, field),
                    row_provenance(row, field, manual=True),
                )
                manually_resolved.add(field)
                break
    if "title" not in manually_resolved:
        source_row = next((row for row in metadata_rows if row.title), None)
        if source_row is not None:
            assign(
                "title",
                source_row.title,
                row_provenance(source_row, "title", manual=False),
            )
        else:
            useful = next(
                (
                    work.title
                    for work in component_works
                    if work.title.strip()
                    and work.title.strip().casefold()
                    not in {
                        "uploaded document",
                        "untitled",
                        "untitled paper",
                        "untitled source",
                        work.id.casefold(),
                    }
                ),
                None,
            )
            fallback = useful or next(
                (work.title for work in component_works if work.title.strip()), None
            )
            assign(
                "title",
                fallback,
                {"source": "work", "updated_at": None} if fallback else None,
            )
    if "authors" not in manually_resolved:
        authors: list[str] = []
        metadata_authors = False
        for row in metadata_rows:
            authors, changed = _merge_capture_authors(authors, list(row.authors or []))
            metadata_authors = metadata_authors or changed
        work_authors = False
        for work in component_works:
            authors, changed = _merge_capture_authors(
                authors, list((work.payload or {}).get("authors") or [])
            )
            work_authors = work_authors or changed
        provenance = None
        if metadata_authors:
            source_row = next(row for row in metadata_rows if row.authors)
            provenance = row_provenance(source_row, "authors", manual=False)
        elif work_authors:
            provenance = {"source": "work", "updated_at": None}
        assign("authors", authors, provenance)
    simple_metadata_fields = {
        "abstract": "description",
        "published_at": "published_at",
        "doi": "doi",
        "source_url": "source_url",
        "canonical_url": "canonical_url",
    }
    work_fallbacks = {
        "abstract": ("abstract",),
        "published_at": ("year",),
        "doi": ("doi",),
        "source_url": ("oa_landing_url", "oa_url"),
        "canonical_url": ("oa_landing_url", "oa_url"),
    }
    for field, row_field in simple_metadata_fields.items():
        if field in manually_resolved:
            continue
        source_row = next((row for row in metadata_rows if getattr(row, row_field)), None)
        if source_row is not None:
            value = getattr(source_row, row_field)
            assign(field, value, row_provenance(source_row, field, manual=False))
            continue
        work_value: Any = None
        for work in component_works:
            payload = dict(work.payload or {})
            for key in work_fallbacks[field]:
                candidate = getattr(work, key) if key in {"doi", "year"} else payload.get(key)
                if candidate not in (None, ""):
                    work_value = str(candidate) if field == "published_at" else candidate
                    break
            if work_value not in (None, ""):
                break
        if work_value not in (None, ""):
            assign(field, work_value, {"source": "work", "updated_at": None})
            continue
        document_value = None
        if field in {"source_url", "canonical_url"}:
            document_value = next(
                (document.url for document in ordered_documents if document.url), None
            )
        assign(
            field,
            document_value,
            {"source": "document", "updated_at": None} if document_value else None,
        )
    for field in _LIBRARY_EXTRA_METADATA_FIELDS:
        manual_row = next(
            (
                row
                for row in metadata_rows
                if field in set((row.provenance or {}).get("manual_fields") or [])
            ),
            None,
        )
        if manual_row is not None:
            value = bibliographic_row_value(manual_row, field)
            if value is _LIBRARY_MISSING:
                value = None
            assign(field, value, row_provenance(manual_row, field, manual=True))
            continue
        source_row = None
        value = None
        for row in metadata_rows:
            candidate = bibliographic_row_value(row, field)
            if candidate not in (_LIBRARY_MISSING, None, "", []):
                source_row = row
                value = candidate
                break
        if source_row is not None:
            assign(field, value, row_provenance(source_row, field, manual=False))
            continue
        work_keys = {
            "pdf_url": ("pdf_url",),
            "container_title": ("venue", "container_title"),
            "license": ("oa_license", "license"),
            "arxiv_id": ("arxiv_id",),
        }.get(field, (field,))
        for work in component_works:
            payload = dict(work.payload or {})
            value = next(
                (payload.get(key) for key in work_keys if payload.get(key) not in (None, "", [])),
                None,
            )
            if value not in (None, "", []):
                break
        if value not in (None, "", []):
            assign(field, value, {"source": "work", "updated_at": None})
            continue
        document_value = None
        if field == "license":
            document_value = next(
                (document.license for document in ordered_documents if document.license),
                None,
            )
        elif field == "pdf_url":
            document_value = next(
                (
                    document.url
                    for document in ordered_documents
                    if document.url
                    and (
                        (document.content_type or "").casefold() == "application/pdf"
                        or urlsplit(document.url).path.casefold().endswith(".pdf")
                    )
                ),
                None,
            )
        assign(
            field,
            document_value,
            {"source": "document", "updated_at": None} if document_value else None,
        )
    doi = metadata.get("doi")
    if doi:
        metadata["doi"] = _capture_doi_identity(str(doi)) or _capture_text(str(doi), 300)
    arxiv_id = metadata.get("arxiv_id")
    if arxiv_id:
        try:
            metadata["arxiv_id"] = _capture_arxiv_id(str(arxiv_id))
        except HTTPException:
            metadata["arxiv_id"] = _capture_text(str(arxiv_id), 80)
    metadata["year"] = _capture_year(
        str(metadata.get("published_at") or ""),
        next((work.year for work in component_works if work.year), None),
    )
    field_provenance["year"] = field_provenance.get("published_at")
    revision = _library_metadata_revision(metadata, field_provenance)
    search_values = [winner.work_id, *metadata.values()]
    return {
        "metadata": metadata,
        "field_provenance": field_provenance,
        "revision": revision,
        "capture_provenance": capture_provenance,
        "search_text": " ".join(
            str(value) for value in search_values if value not in (None, "", [], {})
        ).lower(),
        "run_ids": {
            document.run_id for document in ordered_documents if document.run_id is not None
        },
        "project_ids": {
            document.project_id for document in ordered_documents if document.project_id is not None
        },
    }


def _paper_enrichment_library_snapshot(
    session: Session, *, org_id: int, document_id: int
) -> tuple[
    DocumentRow,
    list[DocumentRow],
    dict[int, BrowserCapturedPaperMetadataRow],
    dict[str, WorkRow],
    dict[str, Any],
]:
    """Resolve an id to its current org-local deduplicated Library component."""
    rows = list(
        session.scalars(
            select(DocumentRow).where(
                DocumentRow.org_id == org_id,
                DocumentRow.library_suppressed.is_(False),
                or_(
                    and_(
                        DocumentRow.checksum.is_not(None),
                        DocumentRow.storage_path.is_not(None),
                    ),
                    and_(
                        DocumentRow.source == "browser_capture",
                        DocumentRow.status == "not_retrieved",
                        DocumentRow.url.is_not(None),
                    ),
                ),
            )
        ).all()
    )
    if document_id not in {row.id for row in rows}:
        raise HTTPException(404, "Library paper not found")
    metadata_by_document = {
        row.document_id: row
        for row in session.scalars(
            select(BrowserCapturedPaperMetadataRow).where(
                BrowserCapturedPaperMetadataRow.org_id == org_id,
                BrowserCapturedPaperMetadataRow.document_id.in_([row.id for row in rows]),
            )
        ).all()
    }
    works = {
        row.id: row
        for row in session.scalars(
            select(WorkRow).where(WorkRow.id.in_([item.work_id for item in rows]))
        ).all()
    }
    winners, components = _library_document_components(rows, metadata_by_document, works)
    component_id = next(
        (
            key
            for key, members in components.items()
            if any(member.id == document_id for member in members)
        ),
        None,
    )
    if component_id is None:
        raise HTTPException(404, "Library paper not found")
    winner = winners[component_id]
    members = components[component_id]
    snapshot = _library_component_metadata(winner, members, metadata_by_document, works)
    return (winner, members, metadata_by_document, works, snapshot)


def _paper_enrichment_protected_fields(
    members: Sequence[DocumentRow],
    metadata_by_document: Mapping[int, BrowserCapturedPaperMetadataRow],
) -> set[str]:
    """Manual fields include explicit clears, which act as tombstones."""
    protected: set[str] = set()
    for member in members:
        row = metadata_by_document.get(member.id)
        if row is not None:
            protected.update((row.provenance or {}).get("manual_fields") or [])
    return protected


def _paper_enrichment_identity(row: PaperEnrichmentRow) -> StrongPaperIdentity:
    provider_id = {
        "doi": f"doi:{row.identity_value}",
        "arxiv": f"doi:10.48550/arXiv.{row.identity_value}",
        "pmid": f"pmid:{row.identity_value}",
        "pmcid": f"pmcid:{row.identity_value}",
    }.get(row.identity_kind, row.identity_value)
    return StrongPaperIdentity(row.identity_kind, row.identity_value, provider_id)


def _paper_enrichment_json(row: PaperEnrichmentRow) -> dict[str, Any]:
    return {
        "id": row.public_id,
        "document_id": row.document_id,
        "status": row.status,
        "identity": {"kind": row.identity_kind, "value": row.identity_value},
        "source_revision": row.source_revision,
        "attempt_count": row.attempt_count,
        "retry_count": row.retry_count,
        "suggestions": list(row.suggestions or []),
        "sources": list(row.provider_receipts or []),
        "applied_fields": list(row.applied_fields or []),
        "error": {"code": row.error_code, "message": row.error_message} if row.error_code else None,
        "created_at": row.created_at.isoformat(),
        "started_at": row.started_at.isoformat() if row.started_at else None,
        "finished_at": row.finished_at.isoformat() if row.finished_at else None,
        "applied_at": row.applied_at.isoformat() if row.applied_at else None,
    }


def _library_web_source_metadata(row: LibraryWebSourceRow) -> dict[str, Any]:
    """Return one versioned web-source snapshot from its bounded ledger fields."""
    provenance = dict(row.provenance or {})
    bibliographic = dict(provenance.get("bibliographic") or {})
    recorded_provenance = dict(provenance.get("field_provenance") or {})
    manual_fields = set(provenance.get("manual_fields") or [])
    metadata: dict[str, Any] = {
        "title": row.title or None,
        "authors": list(row.authors or []),
        "abstract": row.description or None,
        "published_at": row.published_at,
        "year": _capture_year(row.published_at),
        "doi": _capture_doi_identity(row.doi) or row.doi or None,
        "source_url": row.original_url or None,
        "canonical_url": None
        if row.canonical_url.startswith("library:web-source:")
        else row.canonical_url or None,
        "site_name": row.site_name or None,
        "selected_excerpt": row.selected_excerpt or None,
        "source_kind": row.source_kind,
    }
    for field in _LIBRARY_EXTRA_METADATA_FIELDS:
        if field != "selected_excerpt":
            metadata[field] = bibliographic.get(field)
    field_provenance: dict[str, dict[str, Any] | None] = {}
    for field, value in metadata.items():
        source = dict(recorded_provenance.get(field) or {})
        field_provenance[field] = (
            {
                "source": source.get("source")
                or ("user" if field in manual_fields else "browser_capture"),
                "updated_at": source.get("updated_at")
                or provenance.get("captured_at")
                or row.created_at.isoformat(),
            }
            if value not in (None, "", []) or field in manual_fields
            else None
        )
    return {
        "metadata": metadata,
        "field_provenance": field_provenance,
        "revision": _library_metadata_revision(metadata, field_provenance),
    }


def _fill_library_web_source_metadata(
    row: LibraryWebSourceRow,
    *,
    title: str,
    site_name: str,
    authors: list[str],
    published_at: str | None,
    description: str,
    selected_excerpt: str,
    doi: str,
    bibliographic: Mapping[str, Any],
) -> list[str]:
    """Fill only absent web-source details; explicit user decisions always win."""
    provenance = dict(row.provenance or {})
    manual_fields = set(provenance.get("manual_fields") or [])
    changed: list[str] = []
    scalar_values: tuple[tuple[str, Any], ...] = (
        ("title", title),
        ("site_name", site_name),
        ("published_at", published_at),
        ("description", description),
        ("selected_excerpt", selected_excerpt),
        ("doi", doi),
    )
    for field, value in scalar_values:
        manual_field = "abstract" if field == "description" else field
        if manual_field not in manual_fields and (not getattr(row, field)) and value:
            setattr(row, field, value)
            changed.append(field)
    if "authors" not in manual_fields:
        merged_authors, authors_changed = _merge_capture_authors(list(row.authors or []), authors)
        if authors_changed:
            row.authors = merged_authors
            changed.append("authors")
    stored_bibliographic = dict(provenance.get("bibliographic") or {})
    for field, value in bibliographic.items():
        if (
            field not in manual_fields
            and field not in stored_bibliographic
            and (value not in (None, "", [], {}))
        ):
            stored_bibliographic[field] = value
            changed.append(f"bibliographic.{field}")
    if stored_bibliographic:
        provenance["bibliographic"] = stored_bibliographic
    if changed:
        row.provenance = provenance
    return changed


def _capture_identity_document(
    session: Session,
    *,
    org_id: int,
    doi_identity: str,
    canonical_url_hash: str,
    checksum: str | None = None,
    library_only: bool = True,
) -> DocumentRow | None:
    """Return one deterministic org-local Library original for a strong identity."""
    matches: list[dict[int, DocumentRow]] = []

    def metadata_matches(predicate: Any) -> dict[int, DocumentRow]:
        conditions: list[Any] = [
            DocumentRow.org_id == org_id,
            BrowserCapturedPaperMetadataRow.org_id == org_id,
            predicate,
        ]
        if library_only:
            conditions.append(DocumentRow.run_id.is_(None))
        return {
            document.id: document
            for document in session.scalars(
                select(DocumentRow)
                .join(
                    BrowserCapturedPaperMetadataRow,
                    BrowserCapturedPaperMetadataRow.document_id == DocumentRow.id,
                )
                .where(*conditions)
            ).all()
        }

    if canonical_url_hash:
        canonical_matches = metadata_matches(
            BrowserCapturedPaperMetadataRow.canonical_url_hash == canonical_url_hash
        )
        if canonical_matches:
            matches.append(canonical_matches)
    if checksum:
        checksum_conditions: list[Any] = [
            DocumentRow.org_id == org_id,
            DocumentRow.checksum == checksum,
        ]
        if library_only:
            checksum_conditions.append(DocumentRow.run_id.is_(None))
        checksum_matches = {
            document.id: document
            for document in session.scalars(select(DocumentRow).where(*checksum_conditions)).all()
        }
        if checksum_matches:
            matches.append(checksum_matches)
    if doi_identity:
        doi_matches = metadata_matches(BrowserCapturedPaperMetadataRow.doi_identity == doi_identity)
        work_conditions: list[Any] = [DocumentRow.org_id == org_id]
        if library_only:
            work_conditions.append(DocumentRow.run_id.is_(None))
        for document, work_doi in session.execute(
            select(DocumentRow, WorkRow.doi)
            .join(WorkRow, WorkRow.id == DocumentRow.work_id)
            .where(*work_conditions)
        ).all():
            if _capture_doi_identity(work_doi) == doi_identity:
                doi_matches[document.id] = document
        if doi_matches:
            matches.append(doi_matches)
    if not matches:
        return None
    candidate_ids = set(matches[0])
    for identity_matches in matches[1:]:
        candidate_ids &= set(identity_matches)
    if not candidate_ids:
        raise HTTPException(409, "captured paper identities point to different Library papers")
    candidates = {
        document_id: next(group[document_id] for group in matches if document_id in group)
        for document_id in candidate_ids
    }
    return min(candidates.values(), key=lambda row: (not bool(row.storage_path), row.id))


def _capture_checksum_document(
    session: Session, *, org_id: int, checksum: str
) -> DocumentRow | None:
    return session.scalar(
        select(DocumentRow)
        .where(
            DocumentRow.org_id == org_id,
            DocumentRow.checksum == checksum,
            DocumentRow.storage_path.is_not(None),
        )
        .order_by(DocumentRow.run_id.is_(None).desc(), DocumentRow.id)
    )


def _capture_effective_document_title(
    session: Session, document: DocumentRow, *, fallback: str
) -> str:
    """Return the org-private reviewed title used by the Library."""
    private_metadata = session.scalar(
        select(BrowserCapturedPaperMetadataRow).where(
            BrowserCapturedPaperMetadataRow.org_id == document.org_id,
            BrowserCapturedPaperMetadataRow.document_id == document.id,
        )
    )
    if private_metadata is not None:
        manual_fields = set((private_metadata.provenance or {}).get("manual_fields") or [])
        if private_metadata.title or "title" in manual_fields:
            return private_metadata.title
    work = session.get(WorkRow, document.work_id)
    return work.title if work is not None and work.title else fallback


def _effective_document_doi(session: Session, document: DocumentRow) -> str:
    metadata = session.scalar(
        select(BrowserCapturedPaperMetadataRow).where(
            BrowserCapturedPaperMetadataRow.org_id == document.org_id,
            BrowserCapturedPaperMetadataRow.document_id == document.id,
        )
    )
    if metadata is not None and metadata.doi:
        return _capture_doi_identity(metadata.doi)
    work = session.get(WorkRow, document.work_id)
    return _capture_doi_identity(work.doi if work is not None else "")


def _capture_merge_metadata(
    session: Session, document: DocumentRow
) -> BrowserCapturedPaperMetadataRow:
    """Return a private overlay suitable for retaining merge audit details."""
    existing = session.scalar(
        select(BrowserCapturedPaperMetadataRow).where(
            BrowserCapturedPaperMetadataRow.org_id == document.org_id,
            BrowserCapturedPaperMetadataRow.document_id == document.id,
        )
    )
    if existing is not None:
        return existing
    work = session.get(WorkRow, document.work_id)
    payload = dict(work.payload or {}) if work is not None else {}
    canonical_url = document.url or f"library:document:{document.id}"
    row = BrowserCapturedPaperMetadataRow(
        org_id=document.org_id,
        user_id=None,
        document_id=document.id,
        title=work.title if work is not None else "",
        authors=list(payload.get("authors") or []),
        doi=_capture_doi_identity(work.doi if work is not None else ""),
        doi_identity=None,
        published_at=str(work.year) if work is not None and work.year else None,
        description=str(payload.get("abstract") or ""),
        source_url=document.url or "",
        canonical_url=canonical_url,
        canonical_url_hash=hashlib.sha256(
            f"merge:{document.org_id}:{document.id}:{canonical_url}".encode()
        ).hexdigest(),
        pdf_checksum=None,
        provenance={},
    )
    session.add(row)
    session.flush()
    return row


def _copy_document_attachment(
    target: DocumentRow, source: DocumentRow, *, source_url: str | None = None
) -> None:
    """Upgrade a metadata-only row with one already-persisted attachment."""
    target.status = source.status
    target.source = source.source
    target.legal_basis = source.legal_basis
    target.license = source.license
    target.version = source.version
    target.url = source_url or target.url or source.url
    target.content_type = source.content_type
    target.checksum = source.checksum
    target.byte_size = source.byte_size
    target.storage_path = source.storage_path
    target.text_status = source.text_status
    target.reason = source.reason
    target.retrieved_at = source.retrieved_at
    if is_verified_work_id(source.work_id):
        target.work_id = source.work_id
    if target.project_id is None:
        target.project_id = source.project_id
    if not target.folder:
        target.folder = source.folder


def _ensure_capture_library_original(session: Session, document: DocumentRow) -> DocumentRow:
    """Clone a run ledger row before Browser Capture claims durable ownership."""
    if document.run_id is None:
        return document
    captured = session.scalar(
        select(BrowserCapturedPaperMetadataRow).where(
            BrowserCapturedPaperMetadataRow.org_id == document.org_id,
            BrowserCapturedPaperMetadataRow.document_id == document.id,
        )
    )
    existing: DocumentRow | None = None
    if document.checksum:
        existing = session.scalar(
            select(DocumentRow)
            .where(
                DocumentRow.org_id == document.org_id,
                DocumentRow.run_id.is_(None),
                DocumentRow.checksum == document.checksum,
                DocumentRow.storage_path.is_not(None),
            )
            .order_by(DocumentRow.id)
        )
    if existing is None and captured is not None:
        existing = _capture_identity_document(
            session,
            org_id=document.org_id,
            doi_identity=_capture_doi_identity(captured.doi),
            canonical_url_hash=captured.canonical_url_hash,
        )
    if existing is None:
        existing = DocumentRow(
            org_id=document.org_id,
            run_id=None,
            project_id=document.project_id,
            folder=document.folder,
            work_id=document.work_id,
            status=document.status,
            source=document.source,
            legal_basis=document.legal_basis,
            license=document.license,
            version=document.version,
            url=document.url,
            content_type=document.content_type,
            checksum=document.checksum,
            byte_size=document.byte_size,
            storage_path=document.storage_path,
            text_status=document.text_status,
            reason=document.reason,
            retrieved_at=document.retrieved_at,
        )
        session.add(existing)
        session.flush()
    session.execute(
        update(BrowserCaptureReceiptRow)
        .where(
            BrowserCaptureReceiptRow.org_id == document.org_id,
            BrowserCaptureReceiptRow.document_id == document.id,
        )
        .values(document_id=existing.id)
    )
    if captured is not None:
        source_title = captured.title
        source_authors = list(captured.authors or [])
        source_doi = captured.doi
        source_published_at = captured.published_at
        source_description = captured.description
        source_url = captured.source_url
        source_canonical_url = captured.canonical_url
        source_canonical_hash = captured.canonical_url_hash
        source_provenance = dict(captured.provenance or {})
        captured.canonical_url_hash = hashlib.sha256(
            f"run:{document.run_id}:{document.id}:{captured.canonical_url}".encode()
        ).hexdigest()
        captured.doi_identity = None
        captured.pdf_checksum = None
        captured.provenance = {
            **dict(captured.provenance or {}),
            "library_document_id": existing.id,
        }
        session.flush()
        target_metadata = _capture_merge_metadata(session, existing)
        if target_metadata.canonical_url.startswith("library:document:"):
            target_metadata.canonical_url = source_canonical_url
            target_metadata.canonical_url_hash = source_canonical_hash
        _fill_capture_metadata(
            target_metadata,
            title=source_title,
            authors=source_authors,
            doi=source_doi,
            published_at=source_published_at,
            description=source_description,
            source_url=source_url,
            canonical_url=source_canonical_url,
            provenance=source_provenance,
            pdf_checksum=existing.checksum,
        )
        session.flush()
    return existing


def _merge_capture_library_documents(
    session: Session, *, winner: DocumentRow, loser: DocumentRow, org_id: int
) -> None:
    """Retarget document references before removing one redundant Library row."""
    if winner.id == loser.id:
        return
    if winner.storage_path and loser.storage_path and (winner.checksum != loser.checksum):
        raise HTTPException(409, "captured paper identity conflicts with two different stored PDFs")
    if winner.project_id is None and loser.project_id is not None:
        winner.project_id = loser.project_id
    if not winner.folder and loser.folder:
        winner.folder = loser.folder
    session.execute(
        update(BrowserCaptureReceiptRow)
        .where(
            BrowserCaptureReceiptRow.org_id == org_id,
            BrowserCaptureReceiptRow.document_id == loser.id,
        )
        .values(document_id=winner.id)
    )
    writer_conflicts = select(WriterSourceRow.document_id).where(
        WriterSourceRow.org_id == org_id,
        WriterSourceRow.source_document_id == winner.id,
    )
    session.execute(
        update(WriterSourceRow)
        .where(
            WriterSourceRow.org_id == org_id,
            WriterSourceRow.source_document_id == loser.id,
            WriterSourceRow.document_id.in_(writer_conflicts),
        )
        .values(source_document_id=None)
    )
    session.execute(
        update(WriterSourceRow)
        .where(
            WriterSourceRow.org_id == org_id,
            WriterSourceRow.source_document_id == loser.id,
        )
        .values(source_document_id=winner.id)
    )
    session.execute(
        update(DocumentAnnotationRow)
        .where(
            DocumentAnnotationRow.org_id == org_id,
            DocumentAnnotationRow.document_id == loser.id,
        )
        .values(document_id=winner.id)
    )
    loser_metadata = session.scalar(
        select(BrowserCapturedPaperMetadataRow).where(
            BrowserCapturedPaperMetadataRow.org_id == org_id,
            BrowserCapturedPaperMetadataRow.document_id == loser.id,
        )
    )
    winner_metadata = session.scalar(
        select(BrowserCapturedPaperMetadataRow).where(
            BrowserCapturedPaperMetadataRow.org_id == org_id,
            BrowserCapturedPaperMetadataRow.document_id == winner.id,
        )
    )
    loser_provenance = dict(loser_metadata.provenance or {}) if loser_metadata else {}
    if loser.project_id is not None and loser.project_id != winner.project_id:
        loser_provenance.setdefault("merged_project_id", loser.project_id)
    if loser.folder and loser.folder != winner.folder:
        loser_provenance.setdefault("merged_folder", loser.folder)
    if loser_provenance and winner_metadata is None and (loser_metadata is None):
        winner_metadata = _capture_merge_metadata(session, winner)
    if loser_metadata is not None:
        if winner_metadata is None:
            loser_metadata.document_id = winner.id
            loser_metadata.provenance = loser_provenance
        else:
            _fill_capture_metadata(
                winner_metadata,
                title=loser_metadata.title,
                authors=list(loser_metadata.authors or []),
                doi=loser_metadata.doi,
                published_at=loser_metadata.published_at,
                description=loser_metadata.description,
                source_url=loser_metadata.source_url,
                canonical_url=loser_metadata.canonical_url,
                provenance=loser_provenance,
                pdf_checksum=winner.checksum,
            )
            session.delete(loser_metadata)
    elif winner_metadata is not None and loser_provenance:
        winner_metadata.provenance = {
            **dict(winner_metadata.provenance or {}),
            **{
                key: value
                for key, value in loser_provenance.items()
                if key not in (winner_metadata.provenance or {})
            },
        }
    session.delete(loser)
    session.flush()


def _canonical_capture_receipt_document(
    session: Session,
    *,
    receipt: BrowserCaptureReceiptRow,
    org_id: int,
    doi_identity: str,
    canonical_url_hash: str,
    checksum: str,
) -> tuple[DocumentRow, list[str]]:
    """Retarget a legacy receipt to its durable, strong-identity winner."""
    receipt_document = (
        session.get(DocumentRow, receipt.document_id) if receipt.document_id is not None else None
    )
    if receipt_document is None or receipt_document.org_id != org_id:
        raise HTTPException(409, "the original captured paper no longer exists")
    warning_codes: list[str] = []
    checksum_document = _capture_checksum_document(session, org_id=org_id, checksum=checksum)
    if checksum_document is not None and checksum_document.run_id is not None:
        checksum_document = _ensure_capture_library_original(session, checksum_document)
    identity_document = _capture_identity_document(
        session,
        org_id=org_id,
        doi_identity=doi_identity,
        canonical_url_hash=canonical_url_hash,
    )
    if checksum_document is not None:
        winner = checksum_document
        winner_doi = _effective_document_doi(session, winner)
        if winner_doi and doi_identity and (winner_doi != doi_identity):
            warning_codes.append("conflicting_doi_for_identical_pdf")
        elif identity_document is not None and identity_document.id != winner.id:
            if (
                identity_document.storage_path is None
                or identity_document.checksum == winner.checksum
            ):
                _merge_capture_library_documents(
                    session, winner=winner, loser=identity_document, org_id=org_id
                )
            else:
                warning_codes.append("conflicting_doi_for_identical_pdf")
    elif identity_document is not None:
        winner = identity_document
    else:
        winner = _ensure_capture_library_original(session, receipt_document)
    if (
        receipt_document.id != winner.id
        and receipt_document.run_id is None
        and (receipt_document.storage_path is None or receipt_document.checksum == winner.checksum)
    ):
        _merge_capture_library_documents(
            session, winner=winner, loser=receipt_document, org_id=org_id
        )
    receipt.document_id = winner.id
    return (winner, warning_codes)


def _capture_transaction_lock(session: Session, org_id: int, *keys: str) -> None:
    """Serialize capture dedupe keys in the database, never in one process.

    PDF blobs are content-addressed in one shared store, so checksum locks are
    global. DOI, URL and receipt identities remain tenant-namespaced.
    """
    dialect = session.get_bind().dialect.name
    if dialect == "sqlite":
        connection = session.connection()
        raw_connection = connection.connection.driver_connection
        if not bool(getattr(raw_connection, "in_transaction", False)):
            connection.exec_driver_sql("BEGIN IMMEDIATE")
        return
    if dialect != "postgresql":
        return
    for key in sorted(set(keys)):
        lock_org_id = 0 if key.startswith("checksum:") else org_id
        value = int(hashlib.sha256(f"{lock_org_id}:{key}".encode()).hexdigest()[:16], 16)
        if value >= 2**63:
            value -= 2**64
        session.execute(
            sql_text("SELECT pg_advisory_xact_lock(:capture_lock)"),
            {"capture_lock": value},
        )


def _canonical_capture_url(value: str) -> str:
    """Canonicalize one public URL without resolving or fetching its host."""
    decoded = unquote(value)
    if "\\" in decoded or any(
        unicodedata.category(character).startswith("C") for character in decoded
    ):
        raise HTTPException(422, "capture URL contains unsafe encoded characters")
    try:
        parsed = urlsplit(value.strip())
        raw_host = (parsed.hostname or "").rstrip(".")
        if "%" in raw_host or any(character.isspace() for character in raw_host):
            raise ValueError("unsafe host")
        host = raw_host.encode("idna").decode("ascii").lower()
        port = parsed.port
    except (UnicodeError, ValueError) as exc:
        raise HTTPException(422, "capture URL is invalid") from exc
    if host == "localhost" or host.endswith(".localhost"):
        raise HTTPException(422, "capture URL must use a public host")
    try:
        literal = ipaddress.ip_address(host)
    except ValueError:
        labels = host.split(".")
        if any(
            not label
            or len(label) > 63
            or label.startswith("-")
            or label.endswith("-")
            or (re.fullmatch("[a-z0-9-]+", label) is None)
            for label in labels
        ):
            raise HTTPException(422, "capture URL host is invalid") from None
        if len(labels) == 1 and labels[0].lower().startswith(("0x", "0")):
            raise HTTPException(422, "capture URL host is invalid") from None
        if len(labels) == 1 and labels[0].isdigit():
            raise HTTPException(422, "capture URL host is invalid") from None
        if any(
            re.fullmatch("0x[0-9a-f]+", label.lower()) or re.fullmatch("0[0-7]+", label)
            for label in labels
        ):
            raise HTTPException(422, "capture URL host is invalid") from None
        if all(label.isdigit() for label in labels):
            raise HTTPException(422, "capture URL host is invalid") from None
        literal = None
    if literal is not None and (not literal.is_global):
        raise HTTPException(422, "capture URL must use a public host")
    if (
        parsed.scheme.lower() not in {"http", "https"}
        or not host
        or parsed.username is not None
        or (parsed.password is not None)
        or ("\\" in value)
    ):
        raise HTTPException(422, "capture URL must be a public http(s) URL without credentials")
    candidate = urlunsplit((parsed.scheme.lower(), host, parsed.path or "/", "", ""))
    if not is_public_http_url(candidate, resolve=False):
        raise HTTPException(422, "capture URL must use a public host")
    if (parsed.scheme.lower(), port) in {("http", 80), ("https", 443)}:
        port = None
    display_host = f"[{host}]" if ":" in host else host
    netloc = f"{display_host}:{port}" if port is not None else display_host
    path = re.sub("/{2,}", "/", parsed.path or "/")
    query_items = [
        (key, item)
        for key, item in parse_qsl(parsed.query, keep_blank_values=True)
        if not key.lower().startswith("utm_") and key.lower() not in _CAPTURE_TRACKING_PARAMS
    ]
    query = urlencode(sorted(query_items), doseq=True)
    canonical = urlunsplit((parsed.scheme.lower(), netloc, path, query, ""))
    if len(canonical) > 4000:
        raise HTTPException(422, "capture URL is too long")
    return canonical


def _original_capture_url(value: str) -> str:
    """Validate a public source URL while preserving its navigable provenance.

    Canonical URLs intentionally normalize query parameters for deduplication.
    The original source must keep parameter order and fragments because signed
    links and in-page anchors can be semantically meaningful to the user.
    """
    canonical = _canonical_capture_url(value)
    parsed = urlsplit(value.strip())
    canonical_parts = urlsplit(canonical)
    original = urlunsplit(
        (
            canonical_parts.scheme,
            canonical_parts.netloc,
            parsed.path or "/",
            parsed.query,
            parsed.fragment,
        )
    )
    if len(original) > 4000:
        raise HTTPException(422, "capture URL is too long")
    return original


def _browser_capture_web_url(value: str) -> str:
    """Return a public HTTPS web URL with tracking and credential hints removed."""
    canonical = _canonical_capture_url(value)
    parsed = urlsplit(canonical)
    if parsed.scheme != "https":
        raise HTTPException(422, "Browser Capture accepts public HTTPS web pages only")
    safe_items: list[tuple[str, str]] = []
    for key, item in parse_qsl(parsed.query, keep_blank_values=True):
        normalized_key = key.casefold()
        high_entropy_secret = (
            normalized_key in _CAPTURE_AMBIGUOUS_SECRET_PARAMS
            and len(item) >= 24
            and (re.fullmatch("[A-Za-z0-9+/._~=-]+", item) is not None)
        )
        if (
            normalized_key in _CAPTURE_SECRET_PARAMS
            or normalized_key.endswith(_CAPTURE_SECRET_SUFFIXES)
            or normalized_key.startswith(("x-amz-", "x-goog-"))
            or high_entropy_secret
        ):
            continue
        safe_items.append((key, item))
    return urlunsplit(
        (
            parsed.scheme,
            parsed.netloc,
            parsed.path,
            urlencode(safe_items, doseq=True),
            "",
        )
    )


def _capture_paper_identity_url(value: str) -> str:
    """Normalize only stable scholarly-provider identity for org-local dedupe."""
    canonical = _canonical_capture_url(value)
    parsed = urlsplit(canonical)
    if parsed.hostname == "arxiv.org":
        match = re.fullmatch("/(?:abs|pdf)/([^/]+?)(?:\\.pdf)?/?", parsed.path, re.I)
        if match:
            arxiv_id = re.sub("v\\d+$", "", match.group(1), flags=re.I)
            return f"https://arxiv.org/abs/{arxiv_id}"
    return canonical


