_SUPPORT_PAYLOAD_HIDDEN_KEYS = frozenset(
    {
        "api_key",
        "authorization",
        "billed_cost",
        "content",
        "content_base64",
        "cookie",
        "cost",
        "cost_source",
        "credential",
        "headers",
        "input_tokens",
        "instructions",
        "messages",
        "model",
        "model_id",
        "output_tokens",
        "password",
        "planner",
        "prompt",
        "provider",
        "raw_response",
        "secret",
        "source_image_base64",
        "system",
        "ticket",
        "token",
    }
)


def _support_payload(value: Any, *, depth: int = 0) -> Any:
    """Return bounded tool activity without infrastructure or credentials."""
    if depth >= 6:
        return "[nested data omitted]"
    if isinstance(value, dict):
        cleaned: dict[str, Any] = {}
        for raw_key, item in list(value.items())[:50]:
            key = str(raw_key)[:80]
            normalized = key.lower().replace("-", "_")
            if (
                normalized in _SUPPORT_PAYLOAD_HIDDEN_KEYS
                or normalized.endswith("_token")
                or normalized.endswith("_secret")
                or normalized.endswith("_password")
                or ("provider" in normalized)
                or normalized.startswith("model_")
                or normalized.endswith("_cost")
            ):
                continue
            cleaned[key] = _support_payload(item, depth=depth + 1)
        return cleaned
    if isinstance(value, (list, tuple)):
        return [_support_payload(item, depth=depth + 1) for item in list(value)[:50]]
    if isinstance(value, str):
        clipped = value[:8000]
        if len(value) > len(clipped):
            clipped += "…"
        return redact_log_value(clipped)
    if value is None or isinstance(value, (bool, int, float)):
        return value
    return "[unsupported data omitted]"


