def _translation_manifest_payload(
    manifest: dict[str, Any] | None, *, page_count: int, ready: bool
) -> dict[str, Any]:
    """Expose stable translation progress without leaking queue internals."""
    if manifest is None:
        return {
            "status": "not_started",
            "language": None,
            "page_count": page_count,
            "completed_pages": 0,
            "percent": 0,
            "ready": False,
            "pages_without_text": [],
            "error": None,
            "updated_at": None,
        }
    total = max(int(manifest.get("page_count") or page_count), 0)
    completed = min(max(int(manifest.get("completed_pages") or 0), 0), total or 0)
    return {
        "status": str(manifest.get("status") or "not_started"),
        "language": manifest.get("language"),
        "page_count": total,
        "completed_pages": completed,
        "percent": round(completed / total * 100) if total else 0,
        "ready": ready,
        "pages_without_text": list(manifest.get("pages_without_text") or []),
        "error": manifest.get("error"),
        "updated_at": manifest.get("updated_at"),
    }


def _translation_manifest_is_stale(manifest: dict[str, Any]) -> bool:
    """Detect an orphaned inline-development job after an API restart."""
    value = manifest.get("updated_at")
    if not isinstance(value, str):
        return True
    try:
        updated = datetime.fromisoformat(value)
    except ValueError:
        return True
    if updated.tzinfo is None:
        updated = updated.replace(tzinfo=UTC)
    return datetime.now(UTC) - updated > timedelta(minutes=15)


def _collect_openapi_schema_refs(value: Any) -> set[str]:
    """Collect schema component names referenced by an OpenAPI fragment."""
    refs: set[str] = set()
    if isinstance(value, dict):
        ref = value.get("$ref")
        prefix = "#/components/schemas/"
        if isinstance(ref, str) and ref.startswith(prefix):
            refs.add(ref.removeprefix(prefix))
        for child in value.values():
            refs.update(_collect_openapi_schema_refs(child))
    elif isinstance(value, list):
        for child in value:
            refs.update(_collect_openapi_schema_refs(child))
    return refs


def _public_api_openapi(app: FastAPI) -> dict[str, Any]:
    """Build a least-privilege OpenAPI document from the API-key allowlist."""
    full = app.openapi()
    allowed = public_api_route_scopes()
    paths: dict[str, Any] = {}
    for (method, path), scope in allowed.items():
        source_path = full.get("paths", {}).get(path, {})
        source_operation = source_path.get(method.lower())
        if not isinstance(source_operation, dict):
            raise RuntimeError(f"public API route is missing from OpenAPI: {method} {path}")
        operation = copy.deepcopy(source_operation)
        operation["security"] = [{"ScopedApiKey": []}]
        operation["x-required-scope"] = scope
        common_errors = {
            "401": {
                "description": "The bearer token is missing, invalid or expired.",
                "content": {
                    "application/json": {
                        "schema": {"$ref": "#/components/schemas/PublicApiError"},
                        "example": {"detail": "invalid or expired token"},
                    }
                },
            },
            "403": {
                "description": "The API key does not grant the required operation scope.",
                "content": {
                    "application/json": {
                        "schema": {"$ref": "#/components/schemas/PublicApiError"},
                        "example": {
                            "detail": {
                                "code": "insufficient_scope",
                                "message": f"This endpoint requires the {scope} scope.",
                                "required_scope": scope,
                                "granted_scopes": ["research:read"],
                            }
                        },
                    }
                },
            },
            "429": {
                "description": "The API key exceeded its request rate. Honor Retry-After.",
                "headers": {
                    "Retry-After": {
                        "description": "Seconds before retrying.",
                        "schema": {"type": "integer", "example": 60},
                    }
                },
                "content": {
                    "application/json": {
                        "schema": {"$ref": "#/components/schemas/PublicApiError"},
                        "example": {
                            "detail": {
                                "code": "api_key_rate_limited",
                                "message": "This API key exceeded 120 requests per minute.",
                            }
                        },
                    }
                },
            },
        }
        operation.setdefault("responses", {}).update(common_errors)
        if path == "/runs/{run_id}/events/stream":
            operation["parameters"] = [
                parameter
                for parameter in operation.get("parameters", [])
                if parameter.get("name") != "ticket"
            ]
            operation["responses"]["200"]["content"] = {
                "text/event-stream": {
                    "schema": {"type": "string"},
                    "example": 'event: progress\ndata: {"stage":"screening","percent":42}\n\n',
                }
            }
        elif path == "/documents/{document_id}/file":
            operation["responses"]["200"]["content"] = {
                "application/pdf": {"schema": {"type": "string", "format": "binary"}}
            }
        paths.setdefault(path, {})[method.lower()] = operation
    all_schemas = full.get("components", {}).get("schemas", {})
    needed = _collect_openapi_schema_refs(paths)
    pending = list(needed)
    while pending:
        name = pending.pop()
        schema = all_schemas.get(name)
        if not isinstance(schema, dict):
            continue
        for dependency in _collect_openapi_schema_refs(schema) - needed:
            needed.add(dependency)
            pending.append(dependency)
    return {
        "openapi": full.get("openapi", "3.1.0"),
        "info": {
            "title": "SixSentences_ Public API",
            "version": str(sixsentences_server.__version__),
            "description": "The scoped, tenant-bound automation API. Only operations listed in this document accept API keys; delete and account-management operations remain interactive-session only.",
        },
        "externalDocs": {
            "description": "Human-readable guides, curl examples and response contracts",
            "url": get_settings().docs_url,
        },
        "servers": [{"url": "/", "description": "Current API host"}],
        "paths": paths,
        "components": {
            "securitySchemes": {
                "ScopedApiKey": {
                    "type": "http",
                    "scheme": "bearer",
                    "bearerFormat": "six_sk_…",
                    "description": "A scoped API key created under Settings → API keys.",
                }
            },
            "schemas": {
                **{
                    name: copy.deepcopy(all_schemas[name])
                    for name in sorted(needed)
                    if name in all_schemas
                },
                "PublicApiError": {
                    "type": "object",
                    "required": ["detail"],
                    "properties": {
                        "detail": {
                            "oneOf": [
                                {"type": "string"},
                                {
                                    "type": "object",
                                    "additionalProperties": True,
                                    "properties": {
                                        "code": {"type": "string"},
                                        "message": {"type": "string"},
                                    },
                                },
                            ]
                        }
                    },
                },
            },
        },
    }


