        if body.privacy_version != CURRENT_PRIVACY_VERSION:
            raise HTTPException(400, "Open the current Privacy Notice.")
        with db_session() as session:
            user = session.scalar(select(User).where(User.id == ctx.user_id).with_for_update())
            if user is None:
                raise HTTPException(404, "user not found")
            record_privacy_notice(user)
        return {"privacy_version": CURRENT_PRIVACY_VERSION}

