    @app.post("/browser-capture/pair")
    def pair_browser_capture(
        body: BrowserCapturePairCreate,
        response: Response,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        """Approve one exact chrome.identity callback with PKCE and state."""
        if not _capture_redirect_allowed(body.redirect_uri):
            raise HTTPException(422, "this Browser Capture redirect URI is not allowed")
        response.headers["Cache-Control"] = "no-store"
        with db_session() as session:
            code = create_capture_code(
                session,
                ctx.user_id,
                body.code_challenge,
                body.state,
                _capture_device_name(body.device_name),
            )
        separator = "&" if "?" in body.redirect_uri else "?"
        callback_url = (
            f"{body.redirect_uri}{separator}{urlencode({'code': code, 'state': body.state})}"
        )
        return {
            "callback_url": callback_url,
            "state": body.state,
            "expires_in_seconds": 300,
        }

    @app.post("/browser-capture/pair/exchange")
    def exchange_browser_capture(
        body: BrowserCapturePairExchange, response: Response
    ) -> dict[str, Any]:
        response.headers["Cache-Control"] = "no-store"
        try:
            with db_session() as session:
                api_key = exchange_capture_code(session, body.code, body.code_verifier, body.state)
        except AuthError as exc:
            raise HTTPException(409, str(exc)) from exc
        if api_key is None:
            raise HTTPException(401, "pairing code is invalid, expired or already used")
        return {"api_key": api_key, "scopes": ["capture:write"], "expires_in_days": 90}

    @app.post("/browser-capture/device/revoke", status_code=204)
    def revoke_current_browser_capture(
        ctx: AuthContext = Depends(require_auth),
    ) -> Response:
        if ctx.token_kind != "api_key" or not set(ctx.api_scopes) <= PRODUCT_ONLY_API_KEY_SCOPES:
            raise HTTPException(403, "this endpoint is for a paired product device")
        with db_session() as session:
            token = session.get(AuthToken, ctx.token_id)
            if token is None or token.user_id != ctx.user_id or token.org_id != ctx.org_id:
                raise HTTPException(404, "device credential not found")
            token.revoked_at = datetime.now(UTC)
        return Response(status_code=204)

