    @app.post("/auth/api-keys", status_code=201)
    def new_api_key(
        body: ApiKeyCreate,
        response: Response,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        response.headers["Cache-Control"] = "no-store"
        if set(body.scopes or ()) & PRODUCT_ONLY_API_KEY_SCOPES:
            raise HTTPException(422, "product device scopes are issued only by pairing")
        with db_session() as session:
            org = session.get(Org, ctx.org_id)
            assert org is not None
            try:
                check_feature(org, "api_access")
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            user = session.get(User, ctx.user_id)
            if user is None:
                raise HTTPException(404, "user not found")
            if body.expires_in_days not in API_KEY_EXPIRY_DAYS:
                raise HTTPException(422, "expires_in_days must be 30, 90, 180 or 365")
            try:
                scopes = normalize_api_scopes(body.scopes)
                raw = create_api_key(
                    session,
                    user,
                    body.name,
                    scopes=scopes,
                    expires_in_days=body.expires_in_days,
                )
            except AuthError as exc:
                raise HTTPException(422, str(exc)) from exc
        return {
            "api_key": raw,
            "scopes": list(scopes),
            "expires_in_days": body.expires_in_days,
            "note": "store this now; it is not retrievable later",
        }

