    @app.post("/auth/account/export")
    def export_account_data(
        body: AccountDelete, ctx: AuthContext = Depends(require_session)
    ) -> StreamingResponse:
        """Download a secret-free JSON and file archive after reauthentication.

        Owners receive the workspace they control. Members receive only rows
        directly linked to their user identity. Authentication artifacts,
        credentials, capability hashes, internal paths and another member's
        account profile are excluded by construction.
        """
        settings = get_settings()
        with db_session() as session:
            user = session.get(User, ctx.user_id)
            if user is None or not verify_password(body.password, user.password_hash):
                raise HTTPException(403, "That password is not correct.")
            tables, inventory = _privacy_export_tables(session, user=user)
            unavailable: list[dict[str, str]] = []
            artifacts = (
                _privacy_export_artifacts(
                    session,
                    org_id=user.org_id,
                    user_id=user.id,
                    settings=settings,
                    unavailable=unavailable,
                )
                if user.role == "owner"
                else []
            )
        # The streaming response owns this handle beyond the current stack frame.
        archive = tempfile.SpooledTemporaryFile(  # noqa: SIM115
            max_size=16 * 1024 * 1024, mode="w+b"
        )
        with zipfile.ZipFile(archive, mode="w", compression=zipfile.ZIP_DEFLATED) as bundle:
            manifest = {
                "format": "sixsentences-account-export-v1",
                "generated_at": datetime.now(UTC).isoformat(),
                "scope": inventory["scope"],
                "inventory": inventory,
                "file_count": len(artifacts),
                "unavailable_artifacts": unavailable,
                "unavailable_artifacts_note": "Not every optional or derived artifact is expected to exist. This inventory lists absent candidates rather than silently implying completeness.",
                "schema_file": "schema.json",
            }
            bundle.writestr(
                "manifest.json",
                json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True),
            )
            bundle.writestr(
                "schema.json",
                json.dumps(export_schema(tables), ensure_ascii=False, indent=2),
            )
            bundle.writestr(
                "README.txt",
                "SixSentences workspace export\n\nRead manifest.json for scope, generation time and unavailable artifacts.\nschema.json describes UTF-8 JSON tables, fields and retained relationship IDs.\nfiles/ holds available originals and generated artifacts, grouped by record ID.\nSecrets, restricted third-party data and members' private data are excluded.\nExport is not cancellation or erasure. Contact your workspace operator for import assistance.\n",
            )
            for table_name, rows in sorted(tables.items()):
                bundle.writestr(
                    f"data/{table_name}.json",
                    json.dumps(rows, ensure_ascii=False, indent=2, sort_keys=True),
                )
            written_names: set[str] = set()
            for source, archive_name in artifacts:
                if archive_name in written_names:
                    continue
                bundle.write(source, archive_name)
                written_names.add(archive_name)
        archive.seek(0)
        filename = f"sixsentences-export-{datetime.now(UTC).date().isoformat()}.zip"
        return StreamingResponse(
            _privacy_export_stream(archive),
            media_type="application/zip",
            headers={
                "Cache-Control": "no-store",
                "Content-Disposition": f'attachment; filename="{filename}"',
                "X-Content-Type-Options": "nosniff",
            },
        )

    @app.delete("/auth/account")
    def delete_account(
        body: AccountDelete, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        """Delete the caller or, for an owner, their complete workspace."""
        member_removable_checksums: set[str] | None = None
        artifacts: _WorkspaceErasureArtifacts | None = None
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            org = (
                session.scalar(select(Org).where(Org.id == ctx.org_id).with_for_update())
                if ctx.role == "owner"
                else None
            )
            user = session.get(User, ctx.user_id)
            if user is None or not verify_password(body.password, user.password_hash):
                raise HTTPException(403, "That password is not correct.")
            try:
                if ctx.role == "owner":
                    if org is None:
                        raise HTTPException(404, "workspace not found")
                    artifacts = _record_and_purge_workspace(
                        session, ctx.org_id, reason="account_request"
                    )
                else:
                    member_removable_checksums = _record_and_detach_member(
                        session, user, reason="account_request"
                    )
            except ErasureLedgerError as exc:
                logging.getLogger(__name__).exception("account erasure journal failed")
                raise HTTPException(
                    503,
                    "Account deletion is temporarily unavailable. No data was removed.",
                ) from exc
        if member_removable_checksums is not None:
            _cleanup_document_checksums(member_removable_checksums)
            return {"deleted": "account"}
        assert artifacts is not None
        try:
            _cleanup_workspace_erasure_artifacts(artifacts)
        except OSError as exc:
            logging.getLogger(__name__).exception(
                "workspace %s database erasure completed but file cleanup failed",
                ctx.org_id,
            )
            raise HTTPException(
                500,
                "The account was removed, but storage cleanup needs operator attention.",
            ) from exc
        return {"deleted": "workspace", "storage_cleanup": "complete"}

