    @app.post("/writer/templates/shared/{token}/import", status_code=201)
    def import_shared_writer_template(
        token: str, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        """Copy a shared template and its verified project package into this workspace."""
        package: bytes | None = None
        package_filename = ""
        with db_session() as session:
            _require_capability(session, ctx, Capability.STUDIO_BASIC)
            share = session.scalar(
                select(WriterTemplateShareRow).where(WriterTemplateShareRow.token == token)
            )
            if share is None:
                raise HTTPException(404, "shared template not found")
            source = session.get(WriterTemplateRow, share.template_id)
            if source is None:
                raise HTTPException(404, "shared template not found")
            source_origin = session.scalar(
                select(WriterTemplateOriginRow).where(
                    WriterTemplateOriginRow.template_id == source.id
                )
            )
            if source_origin is not None:
                source_path = _writer_template_package_path(
                    source.id, source_origin.package_filename
                )
                try:
                    package = source_path.read_bytes()
                except OSError as exc:
                    raise HTTPException(409, "the shared template package is unavailable") from exc
                if hashlib.sha256(package).hexdigest() != source_origin.package_sha256:
                    raise HTTPException(
                        409, "the shared template package failed its integrity check"
                    )
                _require_storage(session, ctx, len(package))
                package_filename = source_origin.package_filename
            row = WriterTemplateRow(org_id=ctx.org_id, name=source.name, content=source.content)
            session.add(row)
            session.flush()
            if source_origin is not None:
                session.add(
                    WriterTemplateOriginRow(
                        org_id=ctx.org_id,
                        template_id=row.id,
                        provider=source_origin.provider,
                        source_url=source_origin.source_url,
                        upstream_url=source_origin.upstream_url,
                        author=source_origin.author,
                        license_name=source_origin.license_name,
                        license_url=source_origin.license_url,
                        license_status=source_origin.license_status,
                        rights_confirmed=source_origin.rights_confirmed,
                        package_filename=source_origin.package_filename,
                        package_sha256=source_origin.package_sha256,
                        byte_size=source_origin.byte_size,
                        file_count=source_origin.file_count,
                    )
                )
            if package is not None:
                target = _writer_template_package_path(row.id, package_filename, create=True)
                try:
                    target.write_bytes(package)
                except OSError as exc:
                    raise HTTPException(
                        503, "the shared template package could not be stored"
                    ) from exc
            return {
                "id": row.id,
                "name": row.name,
                "chars": len(row.content),
                "updated_at": row.updated_at.isoformat(),
                "origin": _template_origin_json(source_origin),
            }

