    @app.delete("/writer/templates/{template_id}")
    def delete_writer_template(
        template_id: int, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            row = session.get(WriterTemplateRow, template_id)
            if row is None or row.org_id != ctx.org_id:
                raise HTTPException(404, "template not found")
            share = session.scalar(
                select(WriterTemplateShareRow).where(
                    WriterTemplateShareRow.template_id == template_id
                )
            )
            if share is not None:
                session.delete(share)
            origin = session.scalar(
                select(WriterTemplateOriginRow).where(
                    WriterTemplateOriginRow.template_id == template_id
                )
            )
            if origin is not None:
                session.delete(origin)
            session.delete(row)
        directory = _writer_template_dir(template_id)
        if directory.exists():
            shutil.rmtree(directory)
        return {"ok": True}

    @app.post("/writer/import", status_code=201)
    def import_writer_project(
        body: WriterImportRequest, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        """Import Word, one LaTeX file, or a complete zipped LaTeX project."""
        with db_session() as session:
            _require_capability(session, ctx, Capability.STUDIO_BASIC)
        safe = Path(body.filename).name
        try:
            blob = base64.b64decode(body.content_base64, validate=True)
        except (binascii.Error, ValueError) as exc:
            raise HTTPException(422, "invalid base64 payload") from exc
        if len(blob) > 25000000:
            raise HTTPException(422, "imports are limited to 25 MB")
        files: list[tuple[str, str]] = []
        if safe.lower().endswith(".docx"):
            title = safe[: -len(".docx")].replace("-", " ").replace("_", " ").strip()
            try:
                latex, images = docx_to_latex(blob, title or "Imported document")
            except DocxImportError as exc:
                raise HTTPException(422, str(exc)) from exc
        else:
            try:
                title, latex, files, images = import_latex_project(blob, safe)
            except LatexProjectImportError as exc:
                raise HTTPException(422, str(exc)) from exc
        with db_session() as session:
            _require_storage(session, ctx, sum((len(image) for _name, image in images)))
            if body.project_id is not None:
                project = _owned_project(session, body.project_id, ctx)
            doc = WriterDocumentRow(
                org_id=ctx.org_id,
                created_by=ctx.user_id,
                updated_by=ctx.user_id,
                project_id=body.project_id,
                title=title or "Imported document",
                content=latex,
                run_ids=[],
                dataset_ids=[],
            )
            session.add(doc)
            session.flush()
            for path, source in files:
                session.add(
                    WriterFileRow(org_id=ctx.org_id, document_id=doc.id, path=path, content=source)
                )
            for filename, image in images:
                session.add(
                    WriterAssetRow(
                        org_id=ctx.org_id,
                        document_id=doc.id,
                        filename=filename,
                        byte_size=len(image),
                    )
                )
            payload = _writer_json(doc, full=True, access_role="owner")
            if body.project_id is not None:
                _project_event(session, project, ctx, "manuscript_added", {"document_id": doc.id})
            resolved_id = doc.id
        for filename, image in images:
            target = _writer_assets_dir(resolved_id) / filename
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(image)
        return payload

    @app.get("/writer/{doc_id}")
    def get_writer_document(
        doc_id: str, ctx: AuthContext = Depends(require_auth)
    ) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx)
            access_role = _writer_role(session, doc, ctx)
            assert access_role is not None
            return _writer_json(doc, full=True, access_role=access_role)

    def _retarget_template(
        session: Session, ctx: AuthContext, body: WriterRetargetRequest
    ) -> tuple[str, str, list[tuple[str, str]], list[tuple[str, bytes]]]:
        if body.template_id is None:
            return (body.template, TEMPLATES[body.template], [], [])
        custom = session.get(WriterTemplateRow, body.template_id)
        if custom is None or custom.org_id != ctx.org_id:
            raise HTTPException(404, "template not found")
        origin = session.scalar(
            select(WriterTemplateOriginRow).where(WriterTemplateOriginRow.template_id == custom.id)
        )
        if origin is None:
            return (custom.name, custom.content, [], [])
        main, files, assets = _load_template_project(origin)
        return (custom.name, main, files, assets)

    def _retarget_preview_payload(
        doc: WriterDocumentRow,
        template_name: str,
        transfer: RetargetResult,
        *,
        extra_files: int,
        assets: int,
        sources: int,
        collaborators: int,
        template_files: int = 0,
        template_assets: int = 0,
    ) -> dict[str, Any]:
        warnings = list(transfer.warnings)
        mapped = list(transfer.mapped)
        if extra_files:
            warnings.append(
                "Companion source files are copied unchanged; verify class-specific commands in those files."
            )
        if template_files or template_assets:
            mapped.append(
                f"Target package ({template_files} companion files, {template_assets} assets)"
            )
        if collaborators:
            mapped.append(f"{collaborators} collaborator role{('' if collaborators == 1 else 's')}")
        return {
            "source": {
                "id": doc.public_id,
                "title": doc.title,
                "revision": doc.revision,
            },
            "target_template": template_name,
            "suggested_title": f"{doc.title} · {template_name}",
            "content": transfer.content,
            "report": {
                "mapped": mapped,
                "warnings": warnings,
                "section_count": transfer.section_count,
                "citation_count": transfer.citation_count,
                "extra_files": extra_files,
                "assets": assets,
                "template_files": template_files,
                "template_assets": template_assets,
                "owned_sources": sources,
                "collaborators": collaborators,
                "original_preserved": True,
            },
        }

    @app.post("/writer/{doc_id}/retarget/preview")
    def preview_writer_retarget(
        doc_id: str,
        body: WriterRetargetRequest,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        """Prepare a non-destructive submission-template transfer."""
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            if body.expected_revision is not None and body.expected_revision != doc.revision:
                raise _writer_conflict(
                    path="main.tex",
                    revision=doc.revision,
                    content=doc.content,
                    updated_by=doc.updated_by,
                )
            template_name, template_content, template_files, template_assets = _retarget_template(
                session, ctx, body
            )
            try:
                transfer = retarget_latex(doc.content, template_content)
            except ValueError as exc:
                raise HTTPException(422, str(exc)) from exc
            extra_files = session.scalar(
                select(func.count(WriterFileRow.id)).where(WriterFileRow.document_id == doc.id)
            )
            assets = session.scalar(
                select(func.count(WriterAssetRow.id)).where(WriterAssetRow.document_id == doc.id)
            )
            sources = session.scalar(
                select(func.count(WriterSourceRow.id)).where(WriterSourceRow.document_id == doc.id)
            )
            collaborators = session.scalar(
                select(func.count(WriterCollaboratorRow.id)).where(
                    WriterCollaboratorRow.document_id == doc.id
                )
            )
            return _retarget_preview_payload(
                doc,
                template_name,
                transfer,
                extra_files=int(extra_files or 0),
                assets=int(assets or 0),
                sources=int(sources or 0),
                collaborators=int(collaborators or 0),
                template_files=len(template_files),
                template_assets=len(template_assets),
            )

    @app.post("/writer/{doc_id}/retarget", status_code=201)
    def create_writer_retarget(
        doc_id: str,
        body: WriterRetargetRequest,
        background: BackgroundTasks,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        """Create and compile a derived manuscript for a new venue.

        The source document, its versions and its compiled PDF are untouched.
        Research links, citations, assets and companion files are cloned into
        the new submission project.
        """
        with db_session() as session:
            source = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            if body.expected_revision is not None and body.expected_revision != source.revision:
                raise _writer_conflict(
                    path="main.tex",
                    revision=source.revision,
                    content=source.content,
                    updated_by=source.updated_by,
                )
            template_name, template_content, template_files, template_assets = _retarget_template(
                session, ctx, body
            )
            try:
                transfer = retarget_latex(source.content, template_content)
            except ValueError as exc:
                raise HTTPException(422, str(exc)) from exc
            extra_files = session.scalars(
                select(WriterFileRow).where(WriterFileRow.document_id == source.id)
            ).all()
            assets = session.scalars(
                select(WriterAssetRow).where(WriterAssetRow.document_id == source.id)
            ).all()
            sources = session.scalars(
                select(WriterSourceRow).where(WriterSourceRow.document_id == source.id)
            ).all()
            collaborators = session.scalars(
                select(WriterCollaboratorRow).where(WriterCollaboratorRow.document_id == source.id)
            ).all()
            preview = _retarget_preview_payload(
                source,
                template_name,
                transfer,
                extra_files=len(extra_files),
                assets=len(assets),
                sources=len(sources),
                collaborators=len(collaborators),
                template_files=len(template_files),
                template_assets=len(template_assets),
            )
            target = WriterDocumentRow(
                org_id=source.org_id,
                created_by=source.created_by or ctx.user_id,
                updated_by=ctx.user_id,
                project_id=source.project_id,
                title=body.title.strip() or preview["suggested_title"],
                content=transfer.content,
                run_ids=list(source.run_ids or []),
                dataset_ids=list(source.dataset_ids or []),
                derived_from_document_id=source.id,
                target_template=template_name,
                retarget_report=preview["report"],
                compile_status="running",
            )
            session.add(target)
            session.flush()
            merged_files = {
                file_row.path: (file_row.content, file_row.updated_by) for file_row in extra_files
            }
            style_suffixes = {
                ".sty",
                ".cls",
                ".bst",
                ".bbx",
                ".cbx",
                ".lbx",
                ".def",
                ".cfg",
                ".clo",
                ".dtx",
                ".ins",
                ".ist",
            }
            for path, content in template_files:
                if path not in merged_files or PurePosixPath(path).suffix.lower() in style_suffixes:
                    merged_files[path] = (content, ctx.user_id)
            for path, (content, updated_by) in merged_files.items():
                session.add(
                    WriterFileRow(
                        org_id=target.org_id,
                        document_id=target.id,
                        path=path,
                        content=content,
                        updated_by=updated_by or ctx.user_id,
                    )
                )
            source_asset_names = {asset_row.filename for asset_row in assets}
            template_assets_to_write = [
                (filename, asset_content)
                for filename, asset_content in template_assets
                if filename not in source_asset_names
            ]
            _require_storage(
                session,
                ctx,
                sum(int(asset.byte_size or 0) for asset in assets)
                + sum(
                    (len(asset_content) for _filename, asset_content in template_assets_to_write)
                ),
            )
            for asset_row in assets:
                session.add(
                    WriterAssetRow(
                        org_id=target.org_id,
                        document_id=target.id,
                        filename=asset_row.filename,
                        byte_size=asset_row.byte_size,
                        text_content=asset_row.text_content,
                    )
                )
            for filename, asset_content in template_assets_to_write:
                session.add(
                    WriterAssetRow(
                        org_id=target.org_id,
                        document_id=target.id,
                        filename=filename,
                        byte_size=len(asset_content),
                    )
                )
            for source_row in sources:
                session.add(
                    WriterSourceRow(
                        org_id=target.org_id,
                        document_id=target.id,
                        filename=source_row.filename,
                        title=source_row.title,
                        authors=list(source_row.authors or []),
                        year=source_row.year,
                        doi=source_row.doi,
                        cite_key=source_row.cite_key,
                        bibtex=source_row.bibtex,
                        text_content=source_row.text_content,
                        byte_size=source_row.byte_size,
                    )
                )
            for collaborator_row in collaborators:
                if collaborator_row.user_id == target.created_by:
                    continue
                session.add(
                    WriterCollaboratorRow(
                        org_id=target.org_id,
                        document_id=target.id,
                        user_id=collaborator_row.user_id,
                        role=collaborator_row.role,
                        added_by=ctx.user_id,
                    )
                )
            for interview_context in session.scalars(
                select(WriterInterviewContextRow).where(
                    WriterInterviewContextRow.document_id == source.id
                )
            ).all():
                session.add(
                    WriterInterviewContextRow(
                        org_id=target.org_id,
                        document_id=target.id,
                        interview_id=interview_context.interview_id,
                        mode=interview_context.mode,
                        include_methodology=interview_context.include_methodology,
                    )
                )
            for survey_context in session.scalars(
                select(WriterSurveyContextRow).where(
                    WriterSurveyContextRow.document_id == source.id
                )
            ).all():
                session.add(
                    WriterSurveyContextRow(
                        org_id=target.org_id,
                        document_id=target.id,
                        survey_id=survey_context.survey_id,
                        mode=survey_context.mode,
                    )
                )
            _create_project_snapshot(
                session,
                target,
                f"retargeted from {source.title}",
                created_by=ctx.user_id,
            )
            target_id = target.id
            source_id = source.id
            target_access_role = _writer_role(session, target, ctx)
            assert target_access_role is not None
            payload = _writer_json(target, full=True, access_role=target_access_role)
        source_assets = _writer_assets_dir(source_id)
        target_assets = _writer_assets_dir(target_id)
        if source_assets.exists():
            for file_path in source_assets.rglob("*"):
                if not file_path.is_file():
                    continue
                destination = target_assets / file_path.relative_to(source_assets)
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(file_path, destination)
        for filename, asset_content in template_assets_to_write:
            destination = target_assets / filename
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_bytes(asset_content)
        source_files = _writer_sources_dir(source_id)
        target_files = _writer_sources_dir(target_id)
        if source_files.exists():
            for file_path in source_files.rglob("*"):
                if not file_path.is_file():
                    continue
                destination = target_files / file_path.relative_to(source_files)
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(file_path, destination)
        enqueue_job(background, _execute_writer_compile, target_id, queue_org_id=ctx.org_id)
        return payload

    @app.get("/writer/{doc_id}/collaborators")
    def writer_collaborators(
        doc_id: str, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx)
            users = session.scalars(
                select(User).where(User.org_id == ctx.org_id).order_by(User.id)
            ).all()
            overrides = {
                row.user_id: row.role
                for row in session.scalars(
                    select(WriterCollaboratorRow).where(WriterCollaboratorRow.document_id == doc.id)
                ).all()
            }
            members = []
            for user in users:
                if user.role == "owner" or user.id == doc.created_by:
                    role = "owner"
                else:
                    role = overrides.get(user.id, "none")
                members.append(
                    {
                        "user_id": user.id,
                        "email": user.email,
                        "name": user.first_name,
                        "role": role,
                        "is_active": user.is_active,
                        "fixed": role == "owner",
                    }
                )
            return {
                "my_role": _writer_role(session, doc, ctx),
                "can_manage": _writer_role(session, doc, ctx) == "owner",
                "members": members,
            }

    @app.put("/writer/{doc_id}/collaborators")
    def set_writer_collaborator(
        doc_id: str,
        body: WriterCollaboratorSet,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="owner")
            user = session.get(User, body.user_id)
            if user is None or user.org_id != ctx.org_id:
                raise HTTPException(404, "workspace member not found")
            if user.role == "owner" or user.id == doc.created_by:
                raise HTTPException(409, "manuscript owners cannot be downgraded")
            row = session.scalar(
                select(WriterCollaboratorRow).where(
                    WriterCollaboratorRow.document_id == doc.id,
                    WriterCollaboratorRow.user_id == user.id,
                )
            )
            if body.role == "none":
                if row is not None:
                    session.delete(row)
                return {
                    "user_id": user.id,
                    "email": user.email,
                    "name": user.first_name,
                    "role": "none",
                    "is_active": user.is_active,
                    "fixed": False,
                }
            if row is None:
                row = WriterCollaboratorRow(
                    org_id=ctx.org_id,
                    document_id=doc.id,
                    user_id=user.id,
                    role=body.role,
                    added_by=ctx.user_id,
                )
                session.add(row)
            else:
                row.role = body.role
                row.added_by = ctx.user_id
            return {
                "user_id": user.id,
                "email": user.email,
                "name": user.first_name,
                "role": row.role,
                "is_active": user.is_active,
                "fixed": False,
            }

    @app.get("/writer/{doc_id}/presence")
    def writer_presence(
        doc_id: str, ctx: AuthContext = Depends(require_session)
    ) -> list[dict[str, Any]]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx)
            active_since = datetime.now(UTC) - timedelta(seconds=35)
            rows = session.execute(
                select(WriterPresenceRow, User)
                .join(User, User.id == WriterPresenceRow.user_id)
                .where(
                    WriterPresenceRow.document_id == doc.id,
                    WriterPresenceRow.last_seen_at >= active_since,
                )
                .order_by(WriterPresenceRow.last_seen_at.desc())
            ).all()
            return [
                {
                    "user_id": presence.user_id,
                    "email": user.email,
                    "name": user.first_name,
                    "path": presence.path,
                    "line": presence.line,
                    "mode": presence.mode,
                    "role": _writer_role(
                        session,
                        doc,
                        AuthContext(
                            user_id=user.id,
                            org_id=user.org_id,
                            token_id=ctx.token_id,
                            role=user.role,
                            email=user.email,
                        ),
                    ),
                    "self": presence.user_id == ctx.user_id,
                    "last_seen_at": presence.last_seen_at.isoformat(),
                }
                for presence, user in rows
            ]

