    @app.patch("/writer/{doc_id}")
    def patch_writer_document(
        doc_id: str, body: WriterPatch, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            locked_doc = session.scalar(
                select(WriterDocumentRow)
                .where(WriterDocumentRow.id == doc.id)
                .with_for_update()
                .execution_options(populate_existing=True)
            )
            assert locked_doc is not None
            doc = locked_doc
            merged = False
            if body.title is not None:
                doc.title = body.title.strip() or "Untitled"
            if body.content is not None:
                doc.content, merged = _merge_revisioned_content(
                    path="main.tex",
                    current=doc.content,
                    current_revision=doc.revision,
                    current_updated_by=doc.updated_by,
                    incoming=body.content,
                    expected_revision=body.expected_revision,
                    base_content=body.base_content,
                )
                doc.revision += 1
                doc.updated_by = ctx.user_id
                doc.compile_status = "none"
                doc.compile_log = ""
            if body.run_ids is not None:
                doc.run_ids = _validated_run_ids(session, ctx, body.run_ids)
            if body.dataset_ids is not None:
                doc.dataset_ids = _validated_dataset_ids(session, ctx, body.dataset_ids)
            if "project_id" in body.model_fields_set:
                if body.project_id is not None:
                    project = _owned_project(session, body.project_id, ctx)
                    _project_event(
                        session,
                        project,
                        ctx,
                        "manuscript_added",
                        {"document_id": doc.id},
                    )
                doc.project_id = body.project_id
            session.flush()
            access_role = _writer_role(session, doc, ctx)
            assert access_role is not None
            payload = _writer_json(doc, full=body.content is not None, access_role=access_role)
            payload["merged"] = merged
            return payload

    @app.delete("/writer/{doc_id}")
    def delete_writer_document(
        doc_id: str, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="owner")
            resolved_id = doc.id
            session.execute(
                delete(WriterSnapshotRow).where(WriterSnapshotRow.document_id == doc.id)
            )
            session.execute(delete(WriterMessageRow).where(WriterMessageRow.document_id == doc.id))
            session.execute(delete(WriterAssetRow).where(WriterAssetRow.document_id == doc.id))
            session.execute(
                delete(WriterContributionRow).where(WriterContributionRow.document_id == doc.id)
            )
            session.execute(delete(WriterSourceRow).where(WriterSourceRow.document_id == doc.id))
            session.execute(
                delete(WriterInterviewContextRow).where(
                    WriterInterviewContextRow.document_id == doc.id
                )
            )
            session.execute(
                delete(WriterSurveyContextRow).where(WriterSurveyContextRow.document_id == doc.id)
            )
            session.execute(delete(WriterFileRow).where(WriterFileRow.document_id == doc.id))
            session.execute(delete(WriterCommentRow).where(WriterCommentRow.document_id == doc.id))
            session.execute(delete(WriterShareRow).where(WriterShareRow.document_id == doc.id))
            session.execute(
                delete(WriterPresenceRow).where(WriterPresenceRow.document_id == doc.id)
            )
            session.execute(
                delete(WriterCollaboratorRow).where(WriterCollaboratorRow.document_id == doc.id)
            )
            session.execute(
                update(EvidenceClaimRow)
                .where(EvidenceClaimRow.writer_document_id == doc.id)
                .values(writer_document_id=None)
            )
            session.execute(
                update(SubmissionRow)
                .where(SubmissionRow.writer_document_id == doc.id)
                .values(writer_document_id=None)
            )
            session.execute(
                update(WriterDocumentRow)
                .where(WriterDocumentRow.derived_from_document_id == doc.id)
                .values(derived_from_document_id=None)
            )
            session.delete(doc)
        _writer_pdf_path(resolved_id).unlink(missing_ok=True)
        shutil.rmtree(_writer_assets_dir(resolved_id), ignore_errors=True)
        shutil.rmtree(_writer_sources_dir(resolved_id), ignore_errors=True)
        return {"ok": True}

