    @app.put("/writer/{doc_id}/interview-contexts")
    def set_writer_interview_contexts(
        doc_id: str,
        body: WriterInterviewContextsSet,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        """Atomically replace a manuscript's interview evidence selection."""
        requested: dict[int, tuple[str, bool]] = {}
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            _lock_specialist_chat_resource(session, doc)
            seen_public_ids: set[str] = set()
            requested_rows: list[tuple[InterviewRow, WriterInterviewContextItem]] = []
            for source in body.sources:
                if source.interview_id in seen_public_ids:
                    raise HTTPException(422, "each interview can only be linked once")
                seen_public_ids.add(source.interview_id)
                interview = _owned_interview(session, source.interview_id, ctx)
                requested_rows.append((interview, source))
            existing = {
                row.interview_id: row
                for row in session.scalars(
                    select(WriterInterviewContextRow)
                    .where(
                        WriterInterviewContextRow.document_id == doc.id,
                        WriterInterviewContextRow.org_id == ctx.org_id,
                    )
                    .order_by(WriterInterviewContextRow.id)
                    .with_for_update()
                    .execution_options(populate_existing=True)
                ).all()
            }
            interviews_by_id = _lock_writer_interview_rows(
                session,
                org_id=ctx.org_id,
                interview_ids=[interview.id for interview, _source in requested_rows],
            )
            _lock_and_validate_writer_voice_scopes(
                session, org_id=ctx.org_id, interviews=list(interviews_by_id.values())
            )
            for original_interview, source in requested_rows:
                interview = interviews_by_id[original_interview.id]
                if interview.id in requested:
                    raise HTTPException(422, "each interview can only be linked once")
                if interview.status != "ready":
                    raise HTTPException(
                        409, f"{interview.title} is not ready to use in a manuscript"
                    )
                if not interview.analysis:
                    raise HTTPException(
                        409, f"{interview.title} does not have a completed analysis"
                    )
                requested[interview.id] = (source.mode, source.include_methodology)
            for interview_id, row in existing.items():
                if interview_id not in requested:
                    session.delete(row)
            for interview_id, (mode, include_methodology) in requested.items():
                if interview_id in existing:
                    existing[interview_id].mode = mode
                    existing[interview_id].include_methodology = include_methodology
                else:
                    session.add(
                        WriterInterviewContextRow(
                            org_id=ctx.org_id,
                            document_id=doc.id,
                            interview_id=interview_id,
                            mode=mode,
                            include_methodology=include_methodology,
                        )
                    )
            session.flush()
            return _writer_interview_catalog(session, doc, ctx)

