    @app.post("/writer/{doc_id}/files", status_code=201)
    def create_writer_file(
        doc_id: str, body: WriterFileCreate, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        try:
            path = safe_project_path(body.path)
        except LatexProjectImportError as exc:
            raise HTTPException(422, str(exc)) from exc
        if path == "main.tex":
            raise HTTPException(409, "main.tex already exists")
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            locked_doc = session.scalar(
                select(WriterDocumentRow)
                .where(WriterDocumentRow.id == doc.id)
                .with_for_update()
                .execution_options(populate_existing=True)
            )
            assert locked_doc is not None
            doc = locked_doc
            _require_capability(session, ctx, Capability.STUDIO_BASIC)
            existing = session.scalar(
                select(WriterFileRow).where(
                    WriterFileRow.document_id == doc.id, WriterFileRow.path == path
                )
            )
            if existing is not None:
                raise HTTPException(409, "a file with that path already exists")
            row = WriterFileRow(
                org_id=ctx.org_id,
                document_id=doc.id,
                path=path,
                content=body.content,
                updated_by=ctx.user_id,
            )
            session.add(row)
            doc.compile_status = "none"
            doc.compile_log = ""
            session.flush()
            return {
                "id": row.id,
                "path": row.path,
                "content": row.content,
                "main": False,
                "revision": row.revision,
                "updated_by": row.updated_by,
            }

    @app.patch("/writer/{doc_id}/files/{file_id}")
    def patch_writer_file(
        doc_id: str,
        file_id: int,
        body: WriterFilePatch,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        if body.path is None and body.content is None:
            raise HTTPException(422, "provide a path or file content")
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            locked_doc = session.scalar(
                select(WriterDocumentRow)
                .where(WriterDocumentRow.id == doc.id)
                .with_for_update()
                .execution_options(populate_existing=True)
            )
            assert locked_doc is not None
            doc = locked_doc
            row = session.scalar(
                select(WriterFileRow)
                .where(WriterFileRow.id == file_id)
                .with_for_update()
                .execution_options(populate_existing=True)
            )
            if row is None or row.document_id != doc.id:
                raise HTTPException(404, "file not found")
            if body.path is not None:
                try:
                    next_path = safe_project_path(body.path)
                except LatexProjectImportError as exc:
                    raise HTTPException(422, str(exc)) from exc
                if next_path == "main.tex":
                    raise HTTPException(409, "main.tex is the fixed project entry point")
                collision = session.scalar(
                    select(WriterFileRow).where(
                        WriterFileRow.document_id == doc.id,
                        WriterFileRow.path == next_path,
                        WriterFileRow.id != row.id,
                    )
                )
                if collision is not None:
                    raise HTTPException(409, "a file with that path already exists")
                row.path = next_path
            merged = False
            if body.content is not None:
                row.content, merged = _merge_revisioned_content(
                    path=row.path,
                    current=row.content,
                    current_revision=row.revision,
                    current_updated_by=row.updated_by,
                    incoming=body.content,
                    expected_revision=body.expected_revision,
                    base_content=body.base_content,
                )
            row.revision += 1
            row.updated_by = ctx.user_id
            doc.compile_status = "none"
            doc.compile_log = ""
            return {
                "id": row.id,
                "path": row.path,
                "content": row.content,
                "main": False,
                "revision": row.revision,
                "updated_by": row.updated_by,
                "merged": merged,
            }

