    @app.post("/writer/{doc_id}/sources", status_code=201)
    def import_writer_sources(
        doc_id: str,
        body: WriterSourceImport,
        ctx: AuthContext = Depends(require_session),
    ) -> list[dict[str, Any]]:
        with db_session() as session:
            _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            _require_capability(session, ctx, Capability.STUDIO_BASIC)
        safe = Path(body.filename).name
        try:
            blob = base64.b64decode(body.content_base64, validate=True)
        except (binascii.Error, ValueError) as exc:
            raise HTTPException(422, "invalid base64 payload") from exc
        if len(blob) > 20000000:
            raise HTTPException(422, "source files are limited to 20 MB")
        try:
            if safe.lower().endswith(".pdf"):
                extracted = PdfTextExtractor().extract(blob, "application/pdf")
                imported = [
                    pdf_source(
                        safe,
                        extracted.text,
                        {
                            "title": body.title,
                            "authors": body.authors,
                            "year": body.year,
                            "doi": body.doi,
                        },
                    )
                ]
            else:
                imported = import_reference_file(safe, blob)
        except SourceImportError as exc:
            raise HTTPException(422, str(exc)) from exc
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            is_pdf = safe.lower().endswith(".pdf")
            if is_pdf:
                _require_storage(session, ctx, len(blob))
            used = {row.cite_key for row in _writer_sources(session, doc.id)}
            used.update(
                row["key"]
                for row in _writer_citation_rows(
                    _writer_works(session, ctx, list(doc.run_ids or []))
                )
            )
            rows: list[WriterSourceRow] = []
            for item in imported:
                key = _unique_source_key(item.cite_key, used)
                row = WriterSourceRow(
                    org_id=ctx.org_id,
                    document_id=doc.id,
                    filename=safe,
                    title=item.title,
                    authors=item.authors,
                    year=item.year,
                    doi=item.doi,
                    cite_key=key,
                    bibtex=make_bibtex(
                        cite_key=key,
                        title=item.title,
                        authors=item.authors,
                        year=item.year,
                        doi=item.doi,
                    ),
                    text_content=item.text_content or None,
                    byte_size=len(blob) if is_pdf and len(imported) == 1 else 0,
                )
                session.add(row)
                rows.append(row)
            session.flush()
            resolved_id = doc.id
            payload = [_source_json(row) for row in rows]
        if safe.lower().endswith(".pdf"):
            (_writer_sources_dir(resolved_id) / f"{rows[0].id}-{safe}").write_bytes(blob)
        return payload

    @app.post("/writer/{doc_id}/sources/library", status_code=201)
    def import_library_sources(
        doc_id: str,
        body: WriterLibrarySourcesImport,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        """Attach stored Library papers to a manuscript as citable sources.

        The source keeps a bounded text snapshot and exact citation metadata,
        so later Library cleanup cannot silently remove evidence from a
        manuscript. The content-addressed PDF is not copied a second time.
        """
        requested_ids = list(dict.fromkeys(body.document_ids))
        with db_session() as session:
            manuscript = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            _require_capability(session, ctx, Capability.STUDIO_BASIC)
            documents = list(
                session.scalars(
                    select(DocumentRow).where(
                        DocumentRow.id.in_(requested_ids),
                        DocumentRow.org_id == ctx.org_id,
                        or_(
                            and_(
                                DocumentRow.checksum.is_not(None),
                                DocumentRow.storage_path.is_not(None),
                            ),
                            and_(
                                DocumentRow.source == "browser_capture",
                                DocumentRow.status == "not_retrieved",
                                DocumentRow.url.is_not(None),
                            ),
                        ),
                    )
                ).all()
            )
            documents_by_id = {document.id: document for document in documents}
            missing = [
                document_id for document_id in requested_ids if document_id not in documents_by_id
            ]
            if missing:
                raise HTTPException(404, "one or more Library papers were not found")
            existing = _writer_sources(session, manuscript.id)
            existing_document_ids = {
                source.source_document_id
                for source in existing
                if source.source_document_id is not None
            }
            linked_checksums = set(
                session.scalars(
                    select(DocumentRow.checksum).where(
                        DocumentRow.id.in_(existing_document_ids),
                        DocumentRow.org_id == ctx.org_id,
                        DocumentRow.checksum.is_not(None),
                    )
                ).all()
            )
            used_keys = {source.cite_key for source in existing}
            works = {
                work.id: work
                for work in session.scalars(
                    select(WorkRow).where(
                        WorkRow.id.in_([document.work_id for document in documents])
                    )
                ).all()
            }
            capture_metadata = {
                row.document_id: row
                for row in session.scalars(
                    select(BrowserCapturedPaperMetadataRow).where(
                        BrowserCapturedPaperMetadataRow.org_id == ctx.org_id,
                        BrowserCapturedPaperMetadataRow.document_id.in_(requested_ids),
                    )
                ).all()
            }
            store = LocalDocumentStore(get_settings().documents_dir)
            created: list[WriterSourceRow] = []
            skipped: list[int] = []
            for document_id in requested_ids:
                document = documents_by_id[document_id]
                if document.id in existing_document_ids or document.checksum in linked_checksums:
                    skipped.append(document.id)
                    continue
                work = works.get(document.work_id)
                captured = capture_metadata.get(document.id)
                title = (
                    captured.title
                    if captured is not None and captured.title
                    else (work.title if work is not None else "") or document.work_id
                )
                if captured is not None:
                    authors = [
                        str(author).strip()
                        for author in captured.authors or []
                        if str(author).strip()
                    ]
                    year = _capture_year(
                        captured.published_at, work.year if work is not None else None
                    )
                    doi = captured.doi or ""
                else:
                    payload = dict(work.payload or {}) if work is not None else {}
                    authors = [
                        str(author).strip()
                        for author in payload.get("authors") or []
                        if str(author).strip()
                    ]
                    year = work.year if work is not None else None
                    doi = work.doi or "" if work is not None else ""
                text = store.get_text(document.checksum) or "" if document.checksum else ""
                if not text and document.checksum:
                    blob = store.get(document.checksum)
                    if blob is not None:
                        with contextlib.suppress(Exception):
                            text = (
                                PdfTextExtractor()
                                .extract(blob, document.content_type or "application/pdf")
                                .text
                            )
                source_filename = (
                    f"library-{document.id}.pdf"
                    if document.checksum and document.storage_path
                    else f"library-{document.id}.url"
                )
                imported = pdf_source(
                    source_filename,
                    text,
                    {"title": title, "authors": authors, "year": year, "doi": doi},
                )
                key = _unique_source_key(imported.cite_key, used_keys)
                row = WriterSourceRow(
                    org_id=ctx.org_id,
                    document_id=manuscript.id,
                    source_document_id=document.id,
                    filename=source_filename,
                    title=imported.title,
                    authors=imported.authors,
                    year=imported.year,
                    doi=imported.doi,
                    cite_key=key,
                    bibtex=make_bibtex(
                        cite_key=key,
                        title=imported.title,
                        authors=imported.authors,
                        year=imported.year,
                        doi=imported.doi,
                    ),
                    text_content=imported.text_content or None,
                    byte_size=0,
                )
                session.add(row)
                created.append(row)
                if document.checksum:
                    linked_checksums.add(document.checksum)
            session.flush()
            return {
                "created": len(created),
                "skipped": len(skipped),
                "sources": [_source_json(row) for row in created],
            }

    @app.patch("/writer/{doc_id}/sources/{source_id}")
    def patch_writer_source(
        doc_id: str,
        source_id: int,
        body: WriterSourcePatch,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            row = session.get(WriterSourceRow, source_id)
            if row is None or row.document_id != doc.id:
                raise HTTPException(404, "source not found")
            if body.title is not None:
                row.title = body.title.strip() or "Untitled source"
            if body.authors is not None:
                row.authors = [author.strip() for author in body.authors if author.strip()]
            if "year" in body.model_fields_set:
                row.year = body.year
            if body.doi is not None:
                row.doi = body.doi.strip()
            row.bibtex = make_bibtex(
                cite_key=row.cite_key,
                title=row.title,
                authors=list(row.authors or []),
                year=row.year,
                doi=row.doi,
            )
            session.flush()
            return _source_json(row)

    @app.delete("/writer/{doc_id}/sources/{source_id}")
    def delete_writer_source(
        doc_id: str, source_id: int, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            row = session.get(WriterSourceRow, source_id)
            if row is None or row.document_id != doc.id:
                raise HTTPException(404, "source not found")
            resolved_id, filename = (doc.id, row.filename)
            session.delete(row)
        for path in _writer_sources_dir(resolved_id).glob(f"{source_id}-{filename}"):
            path.unlink(missing_ok=True)
        return {"ok": True}

