    @app.post("/writer/{doc_id}/slides", status_code=201)
    def writer_create_slides(
        doc_id: str, ctx: AuthContext = Depends(require_auth)
    ) -> dict[str, Any]:
        """Draft a beamer deck from the manuscript into a new writer document,
        linked to the same searches and datasets so citations carry over."""
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            org = session.get(Org, ctx.org_id)
            assert org is not None
            try:
                check_capability(org, Capability.RESEARCH_STUDIO)
                plan = check_can_ask(
                    session,
                    org,
                    multiplier=1,
                    input_chars=len(doc.content or ""),
                    context_size=None,
                )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            parts = [doc.content or ""]
            for file_row in session.scalars(
                select(WriterFileRow).where(WriterFileRow.document_id == doc.id)
            ).all():
                parts.append(f"% --- {file_row.path} ---\n{file_row.content}")
            manuscript = "\n\n".join(parts)
            works = _writer_works(session, ctx, list(doc.run_ids or []))
            cite_keys = [row["key"] for row in _writer_citation_rows(works)] + [
                row.cite_key for row in _writer_sources(session, doc.id)
            ]
            figures = [
                row.filename
                for row in session.scalars(
                    select(WriterAssetRow).where(WriterAssetRow.document_id == doc.id)
                ).all()
            ]
            try:
                with _scoped_action_pool(
                    session,
                    org,
                    action="writer_slides",
                    resource_type="writer",
                    resource_id=doc.id,
                ) as pool:
                    deck = draft_slides(
                        pool,
                        title=doc.title,
                        manuscript=manuscript,
                        cite_keys=cite_keys,
                        figures=figures,
                    )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            except LLMConfigError as exc:
                raise HTTPException(503, "The AI assistant is not available right now.") from exc
            except SlidesDraftError as exc:
                raise HTTPException(502, str(exc)) from exc
            slides = WriterDocumentRow(
                org_id=ctx.org_id,
                project_id=doc.project_id,
                title=f"Slides: {doc.title}",
                content=deck,
                run_ids=list(doc.run_ids or []),
                dataset_ids=list(doc.dataset_ids or []),
                created_by=ctx.user_id,
                updated_by=ctx.user_id,
            )
            session.add(slides)
            session.flush()
            if figures:
                for row in session.scalars(
                    select(WriterAssetRow).where(WriterAssetRow.document_id == doc.id)
                ).all():
                    session.add(
                        WriterAssetRow(
                            org_id=ctx.org_id,
                            document_id=slides.id,
                            filename=row.filename,
                            byte_size=row.byte_size,
                            text_content=row.text_content,
                        )
                    )
            charge_credits(
                session,
                org,
                action="question",
                credits=question_cost(1, plan=plan, input_chars=len(manuscript), context_size=None),
                model="auto",
            )
            session.flush()
            payload = _writer_json(slides, full=False)
            asset_rows = session.scalars(
                select(WriterAssetRow).where(WriterAssetRow.document_id == doc.id)
            ).all()
            source_doc_id = doc.id
            slides_doc_id = slides.id
        if asset_rows:
            source_dir = _writer_assets_dir(source_doc_id)
            target_dir = _writer_assets_dir(slides_doc_id)
            target_dir.mkdir(parents=True, exist_ok=True)
            for row in asset_rows:
                blob = source_dir / row.filename
                if blob.exists():
                    (target_dir / row.filename).write_bytes(blob.read_bytes())
        return payload

    @app.get("/writer/{doc_id}/project.zip")
    def writer_project_archive(doc_id: str, ctx: AuthContext = Depends(require_auth)) -> Response:
        """Export the complete, portable LaTeX project."""
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx)
            works = _writer_works(session, ctx, list(doc.run_ids or []))
            sources = _writer_sources(session, doc.id)
            files = session.scalars(
                select(WriterFileRow).where(WriterFileRow.document_id == doc.id)
            ).all()
            resolved_id = doc.id
            title = doc.title
            main = doc.content
        output = io.BytesIO()
        with zipfile.ZipFile(output, "w", zipfile.ZIP_DEFLATED) as archive:
            archive.writestr("main.tex", main)
            archive.writestr("references.bib", to_bibtex(works) + _source_bibliography(sources))
            for row in files:
                archive.writestr(row.path, row.content)
            assets_root = _writer_assets_dir(resolved_id)
            for asset in assets_root.rglob("*"):
                if asset.is_file():
                    archive.write(asset, asset.relative_to(assets_root).as_posix())
        slug = re.sub("[^a-z0-9]+", "-", title.lower()).strip("-") or "manuscript"
        return Response(
            content=output.getvalue(),
            media_type="application/zip",
            headers={"Content-Disposition": f'attachment; filename="{slug}.zip"'},
        )

    @app.post("/writer/{doc_id}/compile", status_code=202)
    def compile_writer_document(
        doc_id: str,
        background: BackgroundTasks,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        """Schedule a compile. Runs in the background — tectonic's first run
        downloads LaTeX packages and can take minutes, which must never hold
        an HTTP request hostage. The content is snapshotted first (the
        writing ledger); poll the document for ok/error."""
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            if doc.compile_status == "running":
                raise HTTPException(409, "a compile is already running")
            _create_project_snapshot(session, doc, "compile", created_by=ctx.user_id)
            doc.compile_status = "running"
            doc.compile_log = ""
            resolved_id = doc.id
        enqueue_job(background, _execute_writer_compile, resolved_id, queue_org_id=ctx.org_id)
        return {"scheduled": True}

    @app.get("/writer/{doc_id}/pdf")
    def writer_pdf(doc_id: str, ctx: AuthContext = Depends(require_auth)) -> Response:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx)
            resolved_id = doc.id
            compile_status = doc.compile_status
        if compile_status != "ok":
            raise HTTPException(409, "the manuscript source needs a fresh compile")
        path = _writer_pdf_path(resolved_id)
        if not path.exists():
            raise HTTPException(404, "no compiled PDF yet")
        return Response(content=path.read_bytes(), media_type="application/pdf")

    def _writer_share_json(share: WriterShareRow | None, session: Session) -> dict[str, Any]:
        total = open_count = 0
        if share is not None:
            total = (
                session.scalar(
                    select(func.count(WriterCommentRow.id)).where(
                        WriterCommentRow.share_id == share.id
                    )
                )
                or 0
            )
            open_count = (
                session.scalar(
                    select(func.count(WriterCommentRow.id)).where(
                        WriterCommentRow.share_id == share.id,
                        WriterCommentRow.status == "open",
                    )
                )
                or 0
            )
        return {
            "shared": share is not None,
            "token": share.token if share else None,
            "url": f"{get_settings().app_url}/w/{share.token}" if share else None,
            "password_protected": bool(share and share.password_hash),
            "comments": total,
            "open_comments": open_count,
        }

    def _comment_json(row: WriterCommentRow) -> dict[str, Any]:
        return {
            "id": row.id,
            "author_label": row.author_label or "Reviewer",
            "author_key": row.author_key,
            "color_index": row.color_index,
            "quote": row.quote,
            "anchor_prefix": row.anchor_prefix,
            "anchor_suffix": row.anchor_suffix,
            "anchor_revision": row.anchor_revision,
            "page": row.page,
            "content": row.content,
            "status": row.status,
            "created_at": row.created_at.isoformat(),
            "resolved_at": row.resolved_at.isoformat() if row.resolved_at else None,
        }

    def _comment_color(author_key: str, author_label: str) -> int:
        """Stable reviewer color without trusting a client-selected palette slot."""
        identity = (author_key.strip() or author_label.strip() or "reviewer").casefold()
        digest = hashlib.sha256(identity.encode("utf-8")).digest()
        return digest[0] % 6

    def _new_comment(
        *,
        org_id: int,
        document_id: int,
        share_id: int | None,
        body: WriterCommentCreate,
        author_label: str | None = None,
        author_key: str | None = None,
    ) -> WriterCommentRow:
        label = (author_label if author_label is not None else body.author_label).strip()[:120]
        key = (author_key if author_key is not None else body.author_key).strip()[:120]
        return WriterCommentRow(
            org_id=org_id,
            document_id=document_id,
            share_id=share_id,
            author_label=label or "Reviewer",
            author_key=key,
            color_index=_comment_color(key, label),
            quote=body.quote.strip()[:2000],
            anchor_prefix=body.anchor_prefix.strip()[-500:],
            anchor_suffix=body.anchor_suffix.strip()[:500],
            anchor_revision=body.anchor_revision.strip()[:80],
            page=body.page,
            content=body.content.strip()[:4000],
        )

    def _public_share(
        session: Session, token: str, password: str
    ) -> tuple[WriterShareRow, WriterDocumentRow]:
        share = session.scalar(select(WriterShareRow).where(WriterShareRow.token == token))
        if share is None:
            raise HTTPException(404, "this share link is not active")
        if share.password_hash and (
            not (password and verify_password(password, share.password_hash))
        ):
            raise HTTPException(401, "incorrect share password")
        doc = session.get(WriterDocumentRow, share.document_id)
        assert doc is not None
        return (share, doc)

    @app.get("/writer/{doc_id}/share")
    def get_writer_share(doc_id: str, ctx: AuthContext = Depends(require_auth)) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx)
            share = session.scalar(
                select(WriterShareRow).where(WriterShareRow.document_id == doc.id)
            )
            return _writer_share_json(share, session)

    @app.post("/writer/{doc_id}/share", status_code=201)
    def create_writer_share(
        doc_id: str,
        body: WriterShareCreate,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="owner")
            share = session.scalar(
                select(WriterShareRow).where(WriterShareRow.document_id == doc.id)
            )
            if share is None:
                share = WriterShareRow(
                    org_id=ctx.org_id, document_id=doc.id, created_by=ctx.user_id
                )
                session.add(share)
            if body.password:
                if len(body.password) < 8:
                    raise HTTPException(422, "the password needs at least 8 characters")
                share.password_hash = hash_password(body.password)
            session.flush()
            return _writer_share_json(share, session)

    @app.delete("/writer/{doc_id}/share")
    def delete_writer_share(
        doc_id: str, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="owner")
            share = session.scalar(
                select(WriterShareRow).where(WriterShareRow.document_id == doc.id)
            )
            if share is not None:
                session.execute(
                    delete(WriterCommentRow).where(WriterCommentRow.share_id == share.id)
                )
                session.delete(share)
            return {"ok": True}

