    @app.get("/writer/{doc_id}/sync/source")
    def writer_sync_source(
        doc_id: str,
        path: str,
        line: int,
        column: int = 1,
        ctx: AuthContext = Depends(require_auth),
    ) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            resolved_id = doc.id
            try:
                safe_path = safe_project_path(path)
            except LatexProjectImportError as exc:
                raise HTTPException(422, str(exc)) from exc
            # Resolve to the *stored* project file name and use that from here
            # on. The request never names a path on disk: it selects one of this
            # document's own files, so a traversal or absolute path cannot be
            # rebuilt downstream from a string that only had to compare equal.
            stored_path = next(
                (name for name in _writer_project_files(session, doc) if name == safe_path),
                None,
            )
            if stored_path is None:
                raise HTTPException(404, "Writer file not found")
        pdf_path = _writer_pdf_path(resolved_id)
        sync_path = _writer_synctex_path(resolved_id)
        if not pdf_path.exists() or not sync_path.exists():
            raise HTTPException(409, "compile the manuscript to enable source sync")
        try:
            result = synctex_forward(
                pdf=pdf_path.read_bytes(),
                synctex=sync_path.read_bytes(),
                path=stored_path,
                line=line,
                column=column,
            )
        except SynctexUnavailableError as exc:
            raise HTTPException(503, "source sync is temporarily unavailable") from exc
        if result is None:
            raise HTTPException(404, "no rendered position for this source line")
        return result

    @app.get("/writer/{doc_id}/sync/pdf")
    def writer_sync_pdf(
        doc_id: str,
        page: int,
        x: float,
        y: float,
        ctx: AuthContext = Depends(require_auth),
    ) -> dict[str, Any]:
        with db_session() as session:
            resolved_id = _owned_writer_doc(session, doc_id, ctx).id
        pdf_path = _writer_pdf_path(resolved_id)
        sync_path = _writer_synctex_path(resolved_id)
        if not pdf_path.exists() or not sync_path.exists():
            raise HTTPException(409, "compile the manuscript to enable PDF sync")
        try:
            result = synctex_inverse(
                pdf=pdf_path.read_bytes(),
                synctex=sync_path.read_bytes(),
                page=page,
                x=x,
                y=y,
            )
        except SynctexUnavailableError as exc:
            raise HTTPException(503, "PDF sync is temporarily unavailable") from exc
        if result is None:
            raise HTTPException(404, "no source position for this PDF coordinate")
        return result

