    _ASSET_IMAGE_TYPES = {
        ".png": "image/png",
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg",
        ".webp": "image/webp",
        ".gif": "image/gif",
    }

    @app.get("/writer/{doc_id}/assets/{asset_id}/image")
    def writer_asset_image(
        doc_id: str, asset_id: int, ctx: AuthContext = Depends(require_auth)
    ) -> Response:
        """The asset's pixels, so the Visuals menu can show what each file is."""
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx)
            row = session.get(WriterAssetRow, asset_id)
            if row is None or row.document_id != doc.id:
                raise HTTPException(404, "asset not found")
            media_type = _ASSET_IMAGE_TYPES.get(Path(row.filename).suffix.lower())
            if media_type is None:
                raise HTTPException(404, "not an image asset")
            path = _writer_assets_dir(doc.id) / row.filename
            if not path.exists():
                raise HTTPException(404, "asset file is gone")
            blob = path.read_bytes()
        return Response(content=blob, media_type=media_type)

    @app.post("/writer/{doc_id}/assets", status_code=201)
    def upload_writer_asset(
        doc_id: str,
        body: WriterAssetCreate,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        """Upload a figure or PDF. Files join every compile's working
        directory (so \\includegraphics{filename} just works), and PDFs
        additionally get their text extracted so the editing chat can read
        them as background material."""
        safe = Path(body.filename).name.replace(" ", "-")
        if not safe or not safe.lower().endswith((".png", ".jpg", ".jpeg", ".pdf")):
            raise HTTPException(422, "figures must be .png, .jpg or .pdf")
        try:
            blob = base64.b64decode(body.content_base64, validate=True)
        except (binascii.Error, ValueError) as exc:
            raise HTTPException(422, "invalid base64 payload") from exc
        if len(blob) > 10000000:
            raise HTTPException(422, "figures are limited to 10 MB")
        text_content: str | None = None
        if safe.lower().endswith(".pdf"):
            try:
                validate_pdf_structure(blob)
            except UploadError as exc:
                raise HTTPException(422, str(exc)) from exc
            extracted = PdfTextExtractor().extract(blob, "application/pdf")
            text_content = extracted.text[:20000] or None
        else:
            try:
                decoded, image_format = decode_image(blob)
                decoded.close()
            except UnsafeImageError as exc:
                raise HTTPException(422, str(exc)) from exc
            expected_formats = {".png": {"PNG"}, ".jpg": {"JPEG"}, ".jpeg": {"JPEG"}}
            if image_format not in expected_formats[Path(safe).suffix.lower()]:
                raise HTTPException(422, "the image bytes do not match the filename extension")
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            resolved_id = doc.id
            existing = session.scalar(
                select(WriterAssetRow).where(
                    WriterAssetRow.document_id == doc.id,
                    WriterAssetRow.filename == safe,
                )
            )
            _require_storage(
                session,
                ctx,
                len(blob) - (existing.byte_size if existing is not None else 0),
            )
            if existing is None:
                existing = WriterAssetRow(org_id=ctx.org_id, document_id=doc.id, filename=safe)
                session.add(existing)
            existing.byte_size = len(blob)
            existing.text_content = text_content
            session.flush()
            asset_id = existing.id
        (_writer_assets_dir(resolved_id) / safe).write_bytes(blob)
        return {
            "id": asset_id,
            "filename": safe,
            "byte_size": len(blob),
            "readable": bool(text_content),
        }

    @app.delete("/writer/{doc_id}/assets/{asset_id}")
    def delete_writer_asset(
        doc_id: str, asset_id: int, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            resolved_id = doc.id
            row = session.get(WriterAssetRow, asset_id)
            if row is None or row.document_id != doc.id:
                raise HTTPException(404, "asset not found")
            filename = row.filename
            session.delete(row)
        (_writer_assets_dir(resolved_id) / filename).unlink(missing_ok=True)
        return {"ok": True}

    @app.get("/writer/{doc_id}/artifacts/{kind}")
    def writer_artifact(
        doc_id: str, kind: str, run: int, ctx: AuthContext = Depends(require_auth)
    ) -> dict[str, Any]:
        """A paper-ready LaTeX snippet from a linked run's audited record:
        the evidence table (booktabs), the methods paragraph, or the
        PRISMA 2020 flow as TikZ. Inserted at the cursor by the editor."""
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx)
            if run not in list(doc.run_ids or []):
                raise HTTPException(404, "Link that search to the document first.")
            run_row = session.get(Run, run)
            if run_row is None or run_row.org_id != ctx.org_id:
                raise HTTPException(404, "run not found")
            if kind == "methods":
                latex = methods_paragraph_tex(render_methods(session, run_row), run_row.public_id)
            elif kind == "prisma":
                counts = PrismaCounts(**run_row.prisma) if run_row.prisma else PrismaCounts()
                latex = prisma_flow_tikz(counts, run_row.public_id)
            elif kind == "evidence":
                latex = ""
            else:
                raise HTTPException(404, "unknown artifact")
        if kind == "evidence":
            table = get_extraction(str(run), ctx)
            if not table["rows"]:
                raise HTTPException(
                    404,
                    "No evidence table for this search yet. Build it on the run's Evidence tab first.",
                )
            latex = render_extraction_tex(table["fields"], table["rows"])
        return {"kind": kind, "latex": latex}

    @app.post("/writer/{doc_id}/contributions", status_code=201)
    def log_writer_contributions(
        doc_id: str,
        body: WriterContributionEvents,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        """The client reports which AI proposals actually landed (manual or
        auto apply). Append-only; feeds the contribution log."""
        allowed = {"ai_edit_applied"}
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx, minimum="editor")
            logged = 0
            for event in body.events:
                kind = str(event.get("kind", ""))
                if kind not in allowed:
                    continue
                try:
                    chars_added = max(0, int(event.get("chars_added") or 0))
                    chars_removed = max(0, int(event.get("chars_removed") or 0))
                except (TypeError, ValueError):
                    continue
                message_id = event.get("message_id")
                session.add(
                    WriterContributionRow(
                        org_id=ctx.org_id,
                        document_id=doc.id,
                        kind=kind,
                        payload={
                            "chars_added": chars_added,
                            "chars_removed": chars_removed,
                            "auto": bool(event.get("auto")),
                            "message_id": message_id if isinstance(message_id, int) else None,
                        },
                    )
                )
                logged += 1
        return {"logged": logged}

    @app.get("/writer/{doc_id}/contribution-log")
    def writer_contribution_log(
        doc_id: str, ctx: AuthContext = Depends(require_auth)
    ) -> dict[str, Any]:
        """The AI transparency report: counted from recorded events only
        (assistant turns, applied proposals, compiles, uploads), with an
        honest disclosure paragraph ready to paste or insert."""
        with db_session() as session:
            doc = _owned_writer_doc(session, doc_id, ctx)
            messages = session.scalars(
                select(WriterMessageRow)
                .where(WriterMessageRow.document_id == doc.id)
                .order_by(WriterMessageRow.id)
            ).all()
            contributions = session.scalars(
                select(WriterContributionRow)
                .where(WriterContributionRow.document_id == doc.id)
                .order_by(WriterContributionRow.id)
            ).all()
            snapshots = session.scalars(
                select(WriterSnapshotRow.note).where(WriterSnapshotRow.document_id == doc.id)
            ).all()
            assets = session.scalars(
                select(WriterAssetRow).where(WriterAssetRow.document_id == doc.id)
            ).all()
            linked = session.scalars(
                select(Run).where(Run.id.in_(list(doc.run_ids or [])), Run.org_id == ctx.org_id)
            ).all()
            assistant_turns = [m for m in messages if m.role == "assistant"]
            applied_events = [c for c in contributions if c.kind == "ai_edit_applied"]
            summary = {
                "assistant_turns": len(assistant_turns),
                "edits_proposed": sum(
                    len((m.payload or {}).get("edits") or []) for m in assistant_turns
                ),
                "edits_applied": len(applied_events),
                "edits_applied_auto": sum(
                    1 for c in applied_events if (c.payload or {}).get("auto")
                ),
                "ai_chars_added": sum(
                    int((c.payload or {}).get("chars_added") or 0) for c in applied_events
                ),
                "ai_chars_removed": sum(
                    int((c.payload or {}).get("chars_removed") or 0) for c in applied_events
                ),
                "compiles": sum(1 for note in snapshots if note == "compile"),
                "snapshots": len(snapshots),
                "figures": len(assets),
                "readable_pdfs": sum(1 for a in assets if a.text_content),
                "linked_searches": [r.public_id for r in linked],
                "created_at": doc.created_at.isoformat(),
                "updated_at": doc.updated_at.isoformat(),
            }
            events = [
                {
                    "kind": c.kind,
                    "payload": {
                        "repository_access": "private",
                        "verification_status": str(
                            (c.payload or {}).get("verification_status") or "passed"
                        ),
                    }
                    if (c.payload or {}).get("repository_access") == "private"
                    else c.payload,
                    "created_at": c.created_at.isoformat(),
                }
                for c in contributions[-100:]
            ]
        return {
            "summary": summary,
            "events": events,
            "disclosure": build_disclosure(summary),
            "disclosure_tex": disclosure_tex(summary),
        }

    _survey_response_limiter = build_rate_limiter(
        "survey-response", max_hits=30, window_seconds=60.0
    )

    def _owned_survey(session: Session, survey_id: str, ctx: AuthContext) -> SurveyRow:
        row = session.scalar(
            select(SurveyRow).where(
                SurveyRow.public_id == survey_id, SurveyRow.org_id == ctx.org_id
            )
        )
        if row is None and survey_id.isdigit():
            candidate = session.get(SurveyRow, int(survey_id))
            row = candidate if candidate is not None and candidate.org_id == ctx.org_id else None
        if row is None:
            raise HTTPException(404, "survey not found")
        return row

    def _survey_json(
        session: Session, row: SurveyRow, *, include_responses: bool = False
    ) -> dict[str, Any]:
        responses = session.scalars(
            select(SurveyResponseRow)
            .where(SurveyResponseRow.survey_id == row.id)
            .order_by(SurveyResponseRow.id.desc())
        ).all()
        stored_settings = dict(row.settings or {})
        public_settings = {
            "collect_identity": bool(stored_settings.get("collect_identity")),
            "confirmation": str(
                stored_settings.get("confirmation") or "Thank you for taking part."
            ),
            "password_protected": bool(stored_settings.get("password_hash")),
            "result_dataset_id": stored_settings.get("result_dataset_id"),
        }
        payload: dict[str, Any] = {
            "id": row.id,
            "public_id": row.public_id,
            "project_id": row.project_id,
            "title": row.title,
            "description": row.description,
            "status": row.status,
            "questions": list(row.questions or []),
            "settings": public_settings,
            "response_count": len(responses),
            "participant_information": dict(row.participant_information or {}),
            "participant_information_ready": not participant_information_gaps(
                row.participant_information
            ),
            "participant_information_gaps": participant_information_gaps(
                row.participant_information
            ),
            "summary": survey_summary(
                list(row.questions or []),
                [{"answers": response.answers} for response in responses],
            ),
            "created_at": row.created_at.isoformat(),
            "updated_at": row.updated_at.isoformat(),
        }
        if include_responses:
            payload["responses"] = [
                {
                    "id": response.public_id,
                    "answers": response.answers,
                    "respondent_label": response.respondent_label,
                    "submitted_at": response.submitted_at.isoformat(),
                }
                for response in responses[:2000]
            ]
        return payload

    def _survey_participation_surface(row: SurveyRow) -> dict[str, Any]:
        return {
            "title": row.title,
            "description": row.description,
            "questions": list(row.questions or []),
            "collect_identity": bool((row.settings or {}).get("collect_identity")),
            "notice": participant_notice(dict(row.participant_information or {}), mode="survey"),
        }

    def _require_survey_participant_information(row: SurveyRow) -> None:
        if participant_information_gaps(row.participant_information):
            raise HTTPException(
                409,
                "Complete and review the study's participant information before accepting responses.",
            )

    def _public_survey_json(row: SurveyRow, *, unlocked: bool) -> dict[str, Any]:
        _require_survey_participant_information(row)
        settings = dict(row.settings or {})
        protected = bool(settings.get("password_hash"))
        payload: dict[str, Any] = {
            "public_id": row.public_id,
            "title": row.title,
            "description": row.description,
            "password_protected": protected,
            "questions": list(row.questions or []) if unlocked or not protected else [],
            "settings": {
                "collect_identity": bool(settings.get("collect_identity")),
                "confirmation": str(settings.get("confirmation") or "Thank you for taking part."),
                "password_protected": protected,
            },
        }
        if unlocked or not protected:
            surface = _survey_participation_surface(row)
            payload["participant_notice"] = surface["notice"]
            payload["participant_information_fingerprint"] = notice_fingerprint(surface)
        return payload

    def _survey_password_valid(row: SurveyRow, password: str) -> bool:
        password_hash = str((row.settings or {}).get("password_hash") or "")
        return not password_hash or (bool(password) and verify_password(password, password_hash))

    def _survey_csv_blob(row: SurveyRow, responses: list[SurveyResponseRow]) -> bytes:
        output = io.StringIO()
        writer = csv.writer(output)
        questions = list(row.questions or [])
        writer.writerow(
            [
                "response_id",
                "submitted_at",
                "respondent_label",
                *[question["title"] for question in questions],
            ]
        )
        for response in responses:
            writer.writerow(
                [
                    response.public_id,
                    response.submitted_at.isoformat(),
                    response.respondent_label,
                    *[
                        json.dumps(
                            response.answers.get(str(question["id"]), ""),
                            ensure_ascii=False,
                        )
                        if isinstance(response.answers.get(str(question["id"])), list)
                        else response.answers.get(str(question["id"]), "")
                        for question in questions
                    ],
                ]
            )
        return output.getvalue().encode("utf-8")

    @app.post("/surveys", status_code=201)
    def create_survey(
        body: SurveyCreate, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            org = session.get(Org, ctx.org_id)
            assert org is not None
            if body.project_id is not None:
                project = session.get(Project, body.project_id)
                if project is None or project.org_id != ctx.org_id:
                    raise HTTPException(404, "project not found")
            questions = normalize_questions(body.questions) or [
                {
                    "id": "q1",
                    "title": "What would you like us to know?",
                    "description": "",
                    "type": "long_text",
                    "required": False,
                    "options": [],
                    "min": None,
                    "max": None,
                }
            ]
            try:
                check_survey_questions(org, len(questions))
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            row = SurveyRow(
                org_id=ctx.org_id,
                project_id=body.project_id,
                title=body.title.strip(),
                description=body.description.strip(),
                questions=questions,
                settings={
                    "collect_identity": False,
                    "confirmation": "Thank you for taking part.",
                },
            )
            session.add(row)
            session.flush()
            return _survey_json(session, row)

