    @app.patch("/surveys/{survey_id}")
    def update_survey(
        survey_id: str, body: SurveyPatch, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            row = _owned_survey(session, survey_id, ctx)
            session.refresh(row, with_for_update=True)
            values = body.model_dump(exclude_unset=True)
            if "participant_information" in values and values["participant_information"] is None:
                values["participant_information"] = {}
            if "project_id" in values and values["project_id"] is not None:
                project = session.get(Project, values["project_id"])
                if project is None or project.org_id != ctx.org_id:
                    raise HTTPException(404, "project not found")
            if "questions" in values:
                questions = normalize_questions(values.pop("questions") or [])
                if not questions:
                    raise HTTPException(422, "a survey needs at least one question")
                org = session.get(Org, ctx.org_id)
                assert org is not None
                try:
                    check_survey_questions(org, len(questions))
                except EntitlementError as exc:
                    raise _http_402(exc) from exc
                row.questions = questions
            if "settings" in values:
                requested = values.pop("settings") or {}
                stored = dict(row.settings or {})
                row.settings = {
                    "collect_identity": bool(requested.get("collect_identity")),
                    "confirmation": str(
                        requested.get("confirmation") or "Thank you for taking part."
                    )[:500],
                    **(
                        {"password_hash": stored["password_hash"]}
                        if stored.get("password_hash")
                        else {}
                    ),
                    **(
                        {"result_dataset_id": stored["result_dataset_id"]}
                        if stored.get("result_dataset_id")
                        else {}
                    ),
                }
            for field, value in values.items():
                setattr(row, field, value.strip() if isinstance(value, str) else value)
            if body.status == "live":
                _require_survey_participant_information(row)
            row.updated_at = datetime.now(UTC)
            session.flush()
            return _survey_json(session, row, include_responses=True)

    @app.delete("/surveys/{survey_id}")
    def delete_survey(
        survey_id: str, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            row = _owned_survey(session, survey_id, ctx)
            session.execute(delete(SurveyMessageRow).where(SurveyMessageRow.survey_id == row.id))
            session.execute(delete(SurveyResponseRow).where(SurveyResponseRow.survey_id == row.id))
            session.execute(
                delete(WriterSurveyContextRow).where(WriterSurveyContextRow.survey_id == row.id)
            )
            session.delete(row)
        return {"ok": True}

