    @app.post("/public/surveys/{survey_id}/responses", status_code=201)
    def submit_survey_response(
        survey_id: str, body: SurveyResponseCreate, request: Request
    ) -> dict[str, Any]:
        _throttle(_survey_response_limiter, request)
        with db_session() as session:
            row = session.scalar(
                select(SurveyRow).where(SurveyRow.public_id == survey_id).with_for_update()
            )
            if row is None or row.status != "live":
                raise HTTPException(404, "survey not found")
            if not _survey_password_valid(row, body.password):
                raise HTTPException(401, "incorrect survey password")
            _require_survey_participant_information(row)
            surface = _survey_participation_surface(row)
            if not secrets.compare_digest(
                body.participant_information_fingerprint, notice_fingerprint(surface)
            ):
                raise HTTPException(
                    409,
                    "The study information changed. Reload it before submitting your responses.",
                )
            if surface["notice"]["requires_consent"] and (not body.consent):
                raise HTTPException(
                    422, "Please confirm your consent before submitting your responses."
                )
            org = session.get(Org, row.org_id)
            assert org is not None
            try:
                check_survey_response_available(session, org, row.id)
            except EntitlementError:
                raise HTTPException(409, "this survey is no longer accepting responses") from None
            try:
                answers = validate_answers(list(row.questions or []), body.answers)
            except (TypeError, ValueError) as exc:
                raise HTTPException(422, str(exc)) from exc
            response = SurveyResponseRow(
                org_id=row.org_id,
                survey_id=row.id,
                answers=answers,
                respondent_label=body.respondent_label.strip()[:160]
                if (row.settings or {}).get("collect_identity")
                else "",
                metadata_json={},
                participant_information_snapshot=participation_snapshot(
                    surface,
                    consent=bool(body.consent and surface["notice"]["requires_consent"]),
                    mode="survey",
                ),
            )
            session.add(response)
            session.flush()
            return {
                "id": response.public_id,
                "confirmation": (row.settings or {}).get(
                    "confirmation", "Thank you for taking part."
                ),
            }

