    @app.post("/surveys/{survey_id}/chat")
    def survey_chat(
        survey_id: str, body: SurveyChatCreate, ctx: AuthContext = Depends(require_auth)
    ) -> dict[str, Any]:
        if current_agent_turn_row_id() is None:
            return _specialist_chat_sync(
                kind="survey",
                resource_id=survey_id,
                org_id=ctx.org_id,
                user_id=ctx.user_id,
                turn_id=body.turn_id,
                request_payload=body.model_dump(mode="json", exclude={"turn_id"}),
                worker=lambda: survey_chat(survey_id, body, ctx),
                authorize=lambda session: _owned_survey(session, survey_id, ctx),
            )
        with db_session() as session:
            _begin_specialist_chat_start(session)
            chat_model = _resolve_chat_model_for(session, ctx, body.model)
            row = _owned_survey(session, survey_id, ctx)
            _lock_specialist_chat_resource(session, row)
            org = session.get(Org, ctx.org_id)
            assert org is not None
            try:
                plan = check_can_ask(
                    session,
                    org,
                    multiplier=chat_model.multiplier,
                    input_chars=len(body.question),
                    context_size=None,
                )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            survey_base_credits = question_cost(
                chat_model.multiplier,
                plan=plan,
                input_chars=len(body.question),
                context_size=None,
            )
            responses = session.scalars(
                select(SurveyResponseRow)
                .where(SurveyResponseRow.survey_id == row.id)
                .order_by(SurveyResponseRow.id)
                .limit(2000)
            ).all()
            history = load_context_rows(
                session,
                SurveyMessageRow,
                resource_column=SurveyMessageRow.survey_id,
                resource_id=row.id,
                org_id=row.org_id,
                current_request=body.question,
            )
            try:
                with _scoped_action_pool(
                    session,
                    org,
                    action="survey_chat",
                    resource_type="survey",
                    resource_id=row.id,
                    model_id=chat_model.id,
                    action_id=agent_turn_action_id(ctx.org_id, body.turn_id),
                    reserve_credits=survey_base_credits,
                    settle_reserved_credits=False,
                ) as pool:
                    turn = run_survey_agent(
                        pool,
                        request=body.question,
                        title=row.title,
                        description=row.description,
                        status=row.status,
                        questions=list(row.questions or []),
                        settings={
                            "collect_identity": bool((row.settings or {}).get("collect_identity")),
                            "confirmation": str(
                                (row.settings or {}).get("confirmation")
                                or "Thank you for taking part."
                            ),
                            "password_protected": bool((row.settings or {}).get("password_hash")),
                        },
                        responses=[{"answers": response.answers} for response in responses],
                        history=[
                            {"role": message.role, "content": message.content}
                            for message in reversed(history)
                            if not _is_specialist_terminal_receipt(message)
                            and (not _specialist_message_belongs_to_turn(message, body.turn_id))
                        ],
                        language=ctx.language,
                        assistant_preferences=ctx.assistant_preferences,
                    )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            except LLMConfigError as exc:
                raise HTTPException(503, "The AI assistant is not available right now.") from exc
            mutation = apply_survey_actions(
                title=row.title,
                description=row.description,
                questions=list(row.questions or []),
                settings=dict(row.settings or {}),
                actions=turn.actions,
                response_count=len(responses),
            )
            total_mutations = len(mutation.results)
            execution_results: list[dict[str, Any]] = []
            for index, result in enumerate(mutation.results, start=1):
                validated = bool(result.get("applied"))
                applied_now = validated and body.auto_apply
                staged_now = validated and (not body.auto_apply)
                visible_result = {
                    **result,
                    "applied": applied_now,
                    "staged": staged_now,
                }
                execution_results.append(visible_result)
                emit_agent_event(
                    "change.completed"
                    if applied_now
                    else "change.proposed"
                    if staged_now
                    else "tool.failed",
                    tool="survey.apply_change",
                    operation=str(result.get("operation") or "survey_change"),
                    label=str(result.get("label") or "Update the survey"),
                    detail=str(result.get("detail") or "")[:2000],
                    input=safe_event_value(
                        turn.actions[index - 1]
                        if index - 1 < len(turn.actions)
                        else {"operation": result.get("operation")}
                    ),
                    output=safe_event_value(visible_result),
                    before=safe_event_value(result.get("before")),
                    after=safe_event_value(result.get("after")),
                    applied=applied_now,
                    index=index,
                    total=total_mutations,
                )
            staged = mutation.changed and (not body.auto_apply)
            if mutation.changed and body.auto_apply:
                row.title = mutation.title
                row.description = mutation.description
                row.questions = mutation.questions
                row.settings = mutation.settings
                row.updated_at = datetime.now(UTC)
            failed_actions = [result for result in mutation.results if not result.get("applied")]
            answer = turn.answer
            if failed_actions and (not any(result.get("applied") for result in mutation.results)):
                answer += "\n\nI left the survey unchanged because the requested edit could not be applied safely."
            if execution_results:
                try:
                    with _scoped_action_pool(
                        session,
                        org,
                        action="survey_chat_result_review",
                        resource_type="survey",
                        resource_id=row.id,
                        model_id=chat_model.id,
                        action_id=agent_turn_action_id(ctx.org_id, body.turn_id, "result_review"),
                    ) as result_pool:
                        reviewed = review_execution_results(
                            result_pool,
                            workspace="survey",
                            request=body.question,
                            initial_answer=answer,
                            executed_results=execution_results,
                            language=ctx.language,
                        )
                    answer = reviewed.answer
                except (EntitlementError, LLMConfigError):
                    emit_agent_event(
                        "checkpoint.completed",
                        tool="survey.inspect_results",
                        label="Survey changes ready",
                        detail="The applied or staged survey changes are ready to review.",
                        output=safe_event_value(execution_results),
                        result_count=len(execution_results),
                    )
            assistant_payload: dict[str, Any] = {
                "response_count": len(responses),
                "actions": mutation.results,
                "survey_updated": mutation.changed and (not staged),
                "workspace_actions": bind_workspace_actions(
                    turn.workspace_actions,
                    project_id=row.project_id,
                    source_type="survey",
                    source_id=row.public_id,
                    source_title=row.title,
                    source_numeric_id=row.id,
                ),
            }
            if staged:
                assistant_payload["proposed_actions"] = turn.actions
                assistant_payload["proposal_status"] = "pending"
            fence_agent_turn(session)
            assistant_message = SurveyMessageRow(
                org_id=ctx.org_id,
                survey_id=row.id,
                role="assistant",
                content=answer,
                payload=assistant_payload,
            )
            _ensure_specialist_user_message(
                session,
                kind="survey",
                resource_id=row.public_id,
                org_id=ctx.org_id,
                turn_id=body.turn_id,
                request_payload=body.model_dump(mode="json", exclude={"turn_id"}),
            )
            session.add(assistant_message)
            charge_credits(
                session,
                org,
                action="question",
                credits=survey_base_credits,
                model=chat_model.id,
            )
            session.flush()
            return {
                "message_id": assistant_message.id,
                "answer": answer,
                "response_count": len(responses),
                "actions": mutation.results,
                "workspace_actions": assistant_payload["workspace_actions"],
                "survey": _survey_json(session, row, include_responses=True),
            }

