    @app.post("/datasets/{dataset_id}/versions", status_code=201)
    def create_dataset_version(
        dataset_id: str,
        body: DatasetVersionCreate,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        safe = Path(body.filename).name
        try:
            blob = base64.b64decode(body.content_base64, validate=True)
        except (binascii.Error, ValueError) as exc:
            raise HTTPException(422, "invalid base64 payload") from exc
        if len(blob) > 100000000:
            raise HTTPException(422, "datasets are limited to 100 MB")
        with db_session() as entitlement_session:
            org = entitlement_session.get(Org, ctx.org_id)
            assert org is not None
            try:
                check_dataset_import(org, byte_size=len(blob), row_count=0)
            except EntitlementError as exc:
                raise _http_402(exc) from exc
        try:
            parsed = parse_dataset(blob, safe)
        except DatasetImportError as exc:
            raise HTTPException(422, str(exc)) from exc
        with db_session() as session:
            dataset = _owned_dataset(session, dataset_id, ctx)
            org = session.get(Org, ctx.org_id)
            assert org is not None
            try:
                check_dataset_import(org, byte_size=len(blob), row_count=len(parsed.rows))
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            _require_storage(session, ctx, len(blob) + (len(blob) - dataset.byte_size))
            latest = (
                session.scalar(
                    select(func.max(DatasetVersionRow.version)).where(
                        DatasetVersionRow.dataset_id == dataset.id
                    )
                )
                or 0
            )
            version = latest + 1
            row = DatasetVersionRow(
                org_id=ctx.org_id,
                dataset_id=dataset.id,
                version=version,
                filename=safe,
                checksum=hashlib.sha256(blob).hexdigest(),
                byte_size=len(blob),
                row_count=len(parsed.rows),
                profile=parsed.profile,
                note=body.note.strip(),
                created_by=ctx.user_id,
            )
            session.add(row)
            old_filename = dataset.filename
            dataset.filename = safe
            dataset.format = parsed.format
            dataset.row_count = len(parsed.rows)
            dataset.byte_size = len(blob)
            dataset.profile = parsed.profile
            if dataset.project_id is not None:
                project = _owned_project(session, dataset.project_id, ctx)
                _project_event(
                    session,
                    project,
                    ctx,
                    "dataset_version_created",
                    {"dataset_id": dataset.id, "version": version},
                )
            session.flush()
            payload = {
                "id": row.id,
                "version": row.version,
                "checksum": row.checksum,
                "row_count": row.row_count,
                "note": row.note,
            }
            resolved_id = dataset.id
        old_path = _dataset_path(resolved_id, old_filename)
        if old_path != _dataset_path(resolved_id, safe):
            old_path.unlink(missing_ok=True)
        _dataset_path(resolved_id, safe).write_bytes(blob)
        _dataset_version_path(resolved_id, version, safe).write_bytes(blob)
        return payload

    @app.delete("/datasets/{dataset_id}")
    def delete_dataset(
        dataset_id: str, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            row = _owned_dataset(session, dataset_id, ctx)
            resolved_id, filename, public_id = (row.id, row.filename, row.public_id)
            docs = session.scalars(
                select(WriterDocumentRow).where(WriterDocumentRow.org_id == ctx.org_id)
            ).all()
            for doc in docs:
                if public_id in list(doc.dataset_ids or []):
                    doc.dataset_ids = [
                        value for value in list(doc.dataset_ids or []) if value != public_id
                    ]
            session.execute(delete(AnalysisRecipeRow).where(AnalysisRecipeRow.dataset_id == row.id))
            session.execute(delete(DatasetVersionRow).where(DatasetVersionRow.dataset_id == row.id))
            session.delete(row)
        _dataset_path(resolved_id, filename).unlink(missing_ok=True)
        shutil.rmtree(
            get_settings().data_dir / "datasets" / "versions" / str(resolved_id),
            ignore_errors=True,
        )
        return {"ok": True}

    @app.post("/datasets/{dataset_id}/chart", status_code=201)
    def create_dataset_chart(
        dataset_id: str,
        body: DatasetChartCreate,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        with db_session() as session:
            dataset = _owned_dataset(session, dataset_id, ctx)
            _require_capability(session, ctx, Capability.STUDIO_BASIC)
            try:
                image = render_dataset_chart(
                    dict(dataset.profile or {}),
                    x_column=body.x_column,
                    y_column=body.y_column,
                    kind=body.kind,
                    title=body.title.strip() or dataset.name,
                )
            except DatasetImportError as exc:
                raise HTTPException(422, str(exc)) from exc
            _require_storage(session, ctx, len(image))
            fig = FigureRow(
                org_id=ctx.org_id,
                project_id=dataset.project_id,
                prompt=body.title.strip() or f"{body.y_column} by {body.x_column}",
                status="ok",
                model="Exact data renderer",
                config={
                    "kind": "plot",
                    "chart_kind": body.kind,
                    "dataset_id": dataset.public_id,
                    "dataset_name": dataset.name,
                    "x_column": body.x_column,
                    "y_column": body.y_column,
                    "resolution": "2k",
                    "aspect_ratio": "16:9",
                    "review_passes": 0,
                    "exact": True,
                },
                byte_size=len(image),
            )
            session.add(fig)
            session.flush()
            payload = _figure_json(fig, None)
            resolved_id = fig.id
        _figure_path(resolved_id).write_bytes(image)
        return payload

    def _meta_chart_figure(
        session: Session,
        ctx: AuthContext,
        dataset: ResearchDatasetRow,
        *,
        kind: str,
        label_column: str,
        effect_column: str,
        se_column: str,
        title: str,
    ) -> tuple[FigureRow, bytes]:
        """DerSimonian-Laird from the exact profile, drawn as forest or funnel."""
        _require_capability(session, ctx, Capability.STUDIO_BASIC)
        analysis = run_analysis(
            dict(dataset.profile or {}),
            kind="meta_analysis",
            definition={
                "label_column": label_column,
                "effect_column": effect_column,
                "se_column": se_column,
            },
        )
        image = (
            render_forest_plot(analysis, title)
            if kind == "forest"
            else render_funnel_plot(analysis, title)
        )
        _require_storage(session, ctx, len(image))
        fig = FigureRow(
            org_id=ctx.org_id,
            project_id=dataset.project_id,
            prompt=title,
            status="ok",
            model="Exact data renderer",
            config={
                "kind": "plot",
                "meta_chart": kind,
                "dataset_id": dataset.public_id,
                "dataset_name": dataset.name,
                "resolution": "2k",
                "aspect_ratio": "16:9",
                "review_passes": 0,
                "exact": True,
            },
            byte_size=len(image),
        )
        session.add(fig)
        session.flush()
        return (fig, image)

