    @app.post("/datasets/{dataset_id}/chat")
    def dataset_chat(
        dataset_id: str,
        body: DatasetChatCreate,
        ctx: AuthContext = Depends(require_auth),
    ) -> dict[str, Any]:
        """Grounded conversation about one dataset. The model answers from the
        exact profile and proposes operations; every number it returns was
        computed server-side by the deterministic recipes and renderer."""
        if current_agent_turn_row_id() is None:
            return _specialist_chat_sync(
                kind="dataset",
                resource_id=dataset_id,
                org_id=ctx.org_id,
                user_id=ctx.user_id,
                turn_id=body.turn_id,
                request_payload=body.model_dump(mode="json", exclude={"turn_id"}),
                worker=lambda: dataset_chat(dataset_id, body, ctx),
                authorize=lambda session: _owned_dataset(session, dataset_id, ctx),
            )
        chart_files: list[tuple[int, bytes]] = []
        with db_session() as session:
            _begin_specialist_chat_start(session)
            chat_model = _resolve_chat_model_for(session, ctx, body.model)
            row = _owned_dataset(session, dataset_id, ctx)
            _lock_specialist_chat_resource(session, row)
            org = session.get(Org, ctx.org_id)
            assert org is not None
            try:
                plan = check_can_ask(
                    session,
                    org,
                    multiplier=chat_model.multiplier,
                    input_chars=len(body.question),
                    context_size=None,
                )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            dataset_base_credits = question_cost(
                chat_model.multiplier,
                plan=plan,
                input_chars=len(body.question),
                context_size=None,
            )
            versions = session.scalars(
                select(DatasetVersionRow)
                .where(DatasetVersionRow.dataset_id == row.id)
                .order_by(DatasetVersionRow.version.desc())
                .limit(10)
            ).all()
            history = load_context_rows(
                session,
                DatasetMessageRow,
                resource_column=DatasetMessageRow.dataset_id,
                resource_id=row.id,
                org_id=row.org_id,
                current_request=body.question,
            )
            try:
                with _scoped_action_pool(
                    session,
                    org,
                    action="dataset_chat",
                    resource_type="dataset",
                    resource_id=row.id,
                    model_id=chat_model.id,
                    action_id=agent_turn_action_id(ctx.org_id, body.turn_id),
                    reserve_credits=dataset_base_credits,
                    settle_reserved_credits=False,
                ) as pool:
                    turn = run_dataset_agent(
                        pool,
                        request=body.question,
                        name=row.name,
                        description=row.description,
                        provenance=row.provenance,
                        license=row.license,
                        format=row.format,
                        row_count=row.row_count,
                        profile=dict(row.profile or {}),
                        versions=[
                            {
                                "version": version.version,
                                "filename": version.filename,
                                "rows": version.row_count,
                                "note": version.note,
                            }
                            for version in versions
                        ],
                        history=[
                            {"role": message.role, "content": message.content}
                            for message in reversed(history)
                            if not _is_specialist_terminal_receipt(message)
                            and (not _specialist_message_belongs_to_turn(message, body.turn_id))
                        ],
                        language=ctx.language,
                        assistant_preferences=ctx.assistant_preferences,
                    )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            except LLMConfigError as exc:
                raise HTTPException(503, "The AI assistant is not available right now.") from exc
            results: list[dict[str, Any]] = []
            profile_changed = False

            def record_failure(operation: str, label: str, detail: str) -> None:
                failure = {
                    "operation": operation,
                    "applied": False,
                    "label": label,
                    "detail": detail,
                }
                results.append(failure)
                emit_agent_event(
                    "tool.failed",
                    tool=f"dataset.{operation or 'run_action'}",
                    label=label,
                    detail=detail,
                    output=safe_event_value(failure),
                )

            for action in turn.actions:
                operation = str(action.get("operation") or "")
                action_label = str(
                    action.get("name") or action.get("title") or operation.replace("_", " ")
                )[:240]
                emit_agent_event(
                    "tool.started",
                    tool=f"dataset.{operation or 'run_action'}",
                    label=action_label or "Run the data operation",
                    detail="Running this validated step against the complete stored dataset.",
                    input=safe_event_value(action),
                )
                if operation == "run_analysis":
                    label = str(action.get("name") or "Dataset analysis").strip()[:240]
                    label = label or "Dataset analysis"
                    analysis_definition = dict(action.get("definition") or {})
                    try:
                        analysis = run_analysis(
                            dict(row.profile or {}),
                            kind=str(action.get("kind") or ""),
                            definition=analysis_definition,
                        )
                    except DatasetImportError as exc:
                        record_failure(
                            operation,
                            label,
                            dataset_failure_detail(
                                exc, column=str(analysis_definition.get("column") or "")
                            ),
                        )
                        continue
                    version = (
                        session.scalar(
                            select(func.max(DatasetVersionRow.version)).where(
                                DatasetVersionRow.dataset_id == row.id
                            )
                        )
                        or 1
                    )
                    recipe = AnalysisRecipeRow(
                        org_id=ctx.org_id,
                        project_id=row.project_id,
                        dataset_id=row.id,
                        dataset_version=version,
                        name=label,
                        kind=str(action.get("kind") or ""),
                        definition=dict(action.get("definition") or {}),
                        result=analysis,
                        status="ready",
                        created_by=ctx.user_id,
                    )
                    session.add(recipe)
                    session.flush()
                    results.append(
                        {
                            "operation": operation,
                            "applied": True,
                            "label": label,
                            "kind": str(action.get("kind") or ""),
                            "definition": dict(action.get("definition") or {}),
                            "result": analysis,
                            "analysis_id": recipe.public_id,
                        }
                    )
                    emit_agent_event(
                        "tool.completed",
                        tool="dataset.run_analysis",
                        label=label,
                        detail="The deterministic analysis completed on the stored dataset.",
                        output=safe_event_value(analysis),
                        result_count=1,
                    )
                    continue
                if operation == "create_chart":
                    x_col = str(action.get("x_column") or "")
                    y_col = str(action.get("y_column") or "")
                    chart_kind = str(action.get("kind") or "bar")
                    title = str(action.get("title") or "").strip() or f"{y_col} by {x_col}"
                    try:
                        _require_capability(session, ctx, Capability.STUDIO_BASIC)
                        image = render_dataset_chart(
                            dict(row.profile or {}),
                            x_column=x_col,
                            y_column=y_col,
                            kind=chart_kind,
                            title=title,
                        )
                    except EntitlementError:
                        record_failure(
                            operation,
                            title,
                            "Exact charts need a plan with the Visual Lab.",
                        )
                        continue
                    except DatasetImportError as exc:
                        record_failure(operation, title, dataset_failure_detail(exc))
                        continue
                    _require_storage(session, ctx, len(image))
                    fig = FigureRow(
                        org_id=ctx.org_id,
                        project_id=row.project_id,
                        prompt=title,
                        status="ok",
                        model="Exact data renderer",
                        config={
                            "kind": "plot",
                            "chart_kind": chart_kind,
                            "dataset_id": row.public_id,
                            "dataset_name": row.name,
                            "x_column": x_col,
                            "y_column": y_col,
                            "resolution": "2k",
                            "aspect_ratio": "16:9",
                            "review_passes": 0,
                            "exact": True,
                        },
                        byte_size=len(image),
                    )
                    session.add(fig)
                    session.flush()
                    chart_files.append((fig.id, image))
                    results.append(
                        {
                            "operation": operation,
                            "applied": True,
                            "label": title,
                            "figure_id": fig.public_id,
                            "byte_size": len(image),
                            "kind": chart_kind,
                            "x_column": x_col,
                            "y_column": y_col,
                        }
                    )
                    emit_agent_event(
                        "tool.completed",
                        tool="dataset.create_chart",
                        label=title,
                        detail="The chart was rendered from exact stored values.",
                        output=safe_event_value(results[-1]),
                        result_count=1,
                    )
                    continue
                if operation == "create_meta_chart":
                    meta_kind = str(action.get("kind") or "forest")
                    title = str(action.get("title") or "").strip() or "Meta-analysis"
                    try:
                        fig, image = _meta_chart_figure(
                            session,
                            ctx,
                            row,
                            kind=meta_kind,
                            label_column=str(action.get("label_column") or ""),
                            effect_column=str(action.get("effect_column") or ""),
                            se_column=str(action.get("se_column") or ""),
                            title=title,
                        )
                    except EntitlementError:
                        record_failure(
                            operation,
                            title,
                            "Exact charts need a plan with the Visual Lab.",
                        )
                        continue
                    except DatasetImportError as exc:
                        record_failure(operation, title, dataset_failure_detail(exc))
                        continue
                    chart_files.append((fig.id, image))
                    results.append(
                        {
                            "operation": operation,
                            "applied": True,
                            "label": title,
                            "figure_id": fig.public_id,
                            "byte_size": len(image),
                            "kind": meta_kind,
                        }
                    )
                    emit_agent_event(
                        "tool.completed",
                        tool="dataset.create_meta_chart",
                        label=title,
                        detail="The meta-analysis visual was rendered from validated columns.",
                        output=safe_event_value(results[-1]),
                        result_count=1,
                    )
                    continue
                if operation == "set_profile":
                    changes = dict(action.get("changes") or {})
                    limits = {
                        "name": 240,
                        "description": 4000,
                        "provenance": 4000,
                        "license": 120,
                    }
                    before_profile = {
                        field: getattr(row, field) for field in limits if field in changes
                    }
                    for field, limit in limits.items():
                        if field not in changes:
                            continue
                        value = str(changes[field] or "").strip()[:limit]
                        if field == "name" and (not value):
                            continue
                        if field == "license" and (not value):
                            value = "Not specified"
                        setattr(row, field, value)
                        profile_changed = True
                    if profile_changed:
                        row.updated_at = datetime.now(UTC)
                    after_profile = {
                        field: getattr(row, field) for field in limits if field in changes
                    }
                    results.append(
                        {
                            "operation": operation,
                            "applied": profile_changed,
                            "label": "Updated the dataset profile",
                        }
                    )
                    emit_agent_event(
                        "change.completed" if profile_changed else "tool.failed",
                        tool="dataset.set_profile",
                        label="Updated the dataset profile",
                        input=safe_event_value(action),
                        output=safe_event_value(results[-1]),
                        before=safe_event_value(before_profile),
                        after=safe_event_value(after_profile),
                        applied=profile_changed,
                    )
                    continue
                if operation == "render_visual":
                    results.append(
                        {
                            "operation": operation,
                            "applied": True,
                            "label": "Visual brief prepared",
                            "prompt": str(action.get("prompt") or "")[:1000],
                        }
                    )
                    emit_agent_event(
                        "tool.completed",
                        tool="dataset.prepare_visual",
                        label="Scientific visual brief prepared",
                        detail="The brief is ready for explicit confirmation in Visual Lab.",
                        output=safe_event_value(results[-1]),
                        result_count=1,
                    )
                    continue
            answer = turn.answer
            if results:
                try:
                    with _scoped_action_pool(
                        session,
                        org,
                        action="dataset_chat_result_review",
                        resource_type="dataset",
                        resource_id=row.id,
                        model_id=chat_model.id,
                        action_id=agent_turn_action_id(ctx.org_id, body.turn_id, "result_review"),
                    ) as result_pool:
                        reviewed = review_execution_results(
                            result_pool,
                            workspace="dataset",
                            request=body.question,
                            initial_answer=turn.answer,
                            executed_results=results,
                            language=ctx.language,
                        )
                    answer = reviewed.answer
                except (EntitlementError, LLMConfigError):
                    emit_agent_event(
                        "checkpoint.completed",
                        tool="dataset.inspect_results",
                        label="Dataset results ready",
                        detail="The completed dataset work is ready to review in the Data Hub.",
                        output=safe_event_value(results),
                        result_count=len(results),
                    )
            artifacts = _specialist_result_artifacts(
                kind="dataset", resource_id=row.public_id, result={"actions": results}
            )
            fence_agent_turn(session)
            assistant_message = DatasetMessageRow(
                org_id=ctx.org_id,
                dataset_id=row.id,
                role="assistant",
                content=answer,
                payload={
                    "actions": results,
                    "artifacts": artifacts,
                    "dataset_updated": profile_changed,
                    "workspace_actions": bind_workspace_actions(
                        turn.workspace_actions,
                        project_id=row.project_id,
                        source_type="dataset",
                        source_id=row.public_id,
                        source_title=row.name,
                        source_numeric_id=row.id,
                    ),
                },
            )
            _ensure_specialist_user_message(
                session,
                kind="dataset",
                resource_id=row.public_id,
                org_id=ctx.org_id,
                turn_id=body.turn_id,
                request_payload=body.model_dump(mode="json", exclude={"turn_id"}),
            )
            session.add(assistant_message)
            charge_credits(
                session,
                org,
                action="question",
                credits=dataset_base_credits,
                model=chat_model.id,
            )
            session.flush()
            response_payload = {
                "message_id": assistant_message.id,
                "answer": answer,
                "actions": results,
                "artifacts": artifacts,
                "workspace_actions": bind_workspace_actions(
                    turn.workspace_actions,
                    project_id=row.project_id,
                    source_type="dataset",
                    source_id=row.public_id,
                    source_title=row.name,
                    source_numeric_id=row.id,
                ),
                "dataset": _dataset_json(row, full=True),
            }
        for fig_id, image in chart_files:
            _figure_path(fig_id).write_bytes(image)
        return response_payload

    def _repository_connection_json(row: RepositoryConnectionRow) -> dict[str, Any]:

        def timestamp(value: datetime | None) -> str | None:
            if value is None:
                return None
            if value.tzinfo is None:
                value = value.replace(tzinfo=UTC)
            return value.isoformat()

        return {
            "id": row.public_id,
            "provider": "github",
            "repository_url": row.repository_url,
            "owner": row.owner,
            "name": row.name,
            "created_at": timestamp(row.created_at),
            "updated_at": timestamp(row.updated_at),
            "last_used_at": timestamp(row.last_used_at),
        }

    def _owned_repository_connection(
        session: Session, connection_id: str, ctx: AuthContext, *, lock: bool = False
    ) -> RepositoryConnectionRow:
        statement = select(RepositoryConnectionRow).where(
            RepositoryConnectionRow.public_id == connection_id,
            RepositoryConnectionRow.org_id == ctx.org_id,
            RepositoryConnectionRow.creator_user_id == ctx.user_id,
        )
        if lock:
            statement = statement.with_for_update().execution_options(populate_existing=True)
        row = session.scalar(statement)
        if row is None:
            raise HTTPException(
                404,
                {
                    "code": "repository_connection_not_found",
                    "message": "Repository connection not found.",
                },
            )
        return row

    @app.get("/repository-connections")
    def list_repository_connections(
        ctx: AuthContext = Depends(require_session),
    ) -> list[dict[str, Any]]:
        with db_session() as session:
            rows = session.scalars(
                select(RepositoryConnectionRow)
                .where(
                    RepositoryConnectionRow.org_id == ctx.org_id,
                    RepositoryConnectionRow.creator_user_id == ctx.user_id,
                )
                .options(
                    load_only(
                        RepositoryConnectionRow.public_id,
                        RepositoryConnectionRow.repository_url,
                        RepositoryConnectionRow.owner,
                        RepositoryConnectionRow.name,
                        RepositoryConnectionRow.created_at,
                        RepositoryConnectionRow.updated_at,
                        RepositoryConnectionRow.last_used_at,
                    )
                )
                .order_by(RepositoryConnectionRow.created_at, RepositoryConnectionRow.id)
            ).all()
            return [_repository_connection_json(row) for row in rows]

    @app.post("/repository-connections", status_code=201)
    def create_repository_connection(
        body: RepositoryConnectionCreate, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        """Persist an explicitly consented, repository-bound PAT ciphertext."""
        if not get_settings().repository_analysis_enabled:
            raise HTTPException(
                409,
                {
                    "code": "repository_analysis_disabled",
                    "message": "Repository analysis is temporarily disabled by the operator.",
                },
            )
        try:
            requested_repository = parse_public_github_repository(body.repository_url)
        except RepositoryIngestError as exc:
            raise HTTPException(422, {"code": exc.code, "message": str(exc)}) from exc
        if not _rate_limit_allowed(_repository_connection_limiter, str(ctx.user_id)):
            raise HTTPException(
                429,
                {
                    "code": "repository_connection_rate_limited",
                    "message": "Too many GitHub connection attempts. Try again later.",
                },
                headers={"Retry-After": "300"},
            )
        with db_session() as session:
            _require_capability(session, ctx, Capability.STUDIO_BASIC)
            if (
                int(
                    session.scalar(
                        select(func.count())
                        .select_from(RepositoryConnectionRow)
                        .where(
                            RepositoryConnectionRow.org_id == ctx.org_id,
                            RepositoryConnectionRow.creator_user_id == ctx.user_id,
                        )
                    )
                    or 0
                )
                >= _MAX_REPOSITORY_CONNECTIONS_PER_USER
            ):
                raise HTTPException(
                    409,
                    {
                        "code": "repository_connection_limit_reached",
                        "message": "Disconnect a repository before connecting another one.",
                    },
                )
        access_token = body.access_token.get_secret_value()
        if (
            not access_token
            or len(access_token) > 1024
            or access_token != access_token.strip()
            or any(not 33 <= ord(character) <= 126 for character in access_token)
        ):
            raise HTTPException(
                422,
                {
                    "code": "github_connection_failed",
                    "message": "GitHub could not authorize this credential.",
                },
            )
        try:
            encrypt_credential("repository-connection-configuration-probe")
        except CredentialError as exc:
            raise HTTPException(
                503,
                {
                    "code": "repository_credentials_unavailable",
                    "message": "Encrypted repository connections are unavailable.",
                },
            ) from exc
        try:
            record = github_repository_record(requested_repository, access_token=access_token)
            canonical_repository = parse_public_github_repository(str(record["repository_url"]))
            actual_ref, commit_sha = resolve_github_ref(
                canonical_repository,
                str(record.get("default_branch") or "") or None,
                access_token=access_token,
            )
            del actual_ref
            probe_github_archive_access(canonical_repository, commit_sha, access_token=access_token)
            encrypted = encrypt_credential(
                json.dumps(
                    {
                        "version": 1,
                        "org_id": ctx.org_id,
                        "creator_user_id": ctx.user_id,
                        "github_repository_id": int(record["id"]),
                        "access_token": access_token,
                    },
                    sort_keys=True,
                    separators=(",", ":"),
                )
            )
        except CredentialError as exc:
            raise HTTPException(
                503,
                {
                    "code": "repository_credentials_unavailable",
                    "message": "Encrypted repository connections are unavailable.",
                },
            ) from exc
        except RepositoryIngestError as exc:
            raise HTTPException(
                422,
                {
                    "code": "github_connection_failed",
                    "message": "GitHub could not authorize read-only access to this private repository.",
                },
            ) from exc
        finally:
            access_token = ""
        now = datetime.now(UTC)
        with db_session() as session:
            _capture_transaction_lock(
                session, ctx.org_id, f"repository-connection-user:{ctx.user_id}"
            )
            _require_capability(session, ctx, Capability.STUDIO_BASIC)
            existing = session.scalar(
                select(RepositoryConnectionRow).where(
                    RepositoryConnectionRow.org_id == ctx.org_id,
                    RepositoryConnectionRow.creator_user_id == ctx.user_id,
                    RepositoryConnectionRow.github_repository_id == int(record["id"]),
                )
            )
            if existing is not None:
                raise HTTPException(
                    409,
                    {
                        "code": "repository_connection_exists",
                        "message": "This private repository is already connected.",
                    },
                )
            count = int(
                session.scalar(
                    select(func.count())
                    .select_from(RepositoryConnectionRow)
                    .where(
                        RepositoryConnectionRow.org_id == ctx.org_id,
                        RepositoryConnectionRow.creator_user_id == ctx.user_id,
                    )
                )
                or 0
            )
            if count >= _MAX_REPOSITORY_CONNECTIONS_PER_USER:
                raise HTTPException(
                    409,
                    {
                        "code": "repository_connection_limit_reached",
                        "message": "Disconnect a repository before connecting another one.",
                    },
                )
            connection = RepositoryConnectionRow(
                org_id=ctx.org_id,
                creator_user_id=ctx.user_id,
                provider="github",
                github_repository_id=int(record["id"]),
                full_name=str(record["full_name"]),
                repository_url=str(record["repository_url"]),
                owner=str(record["owner"]),
                name=str(record["name"]),
                repository_visibility=str(record["visibility"]),
                credential_encrypted=encrypted,
                credential_storage_version=_GITHUB_PAT_STORAGE_VERSION,
                credential_storage_confirmed_at=now,
                created_at=now,
                updated_at=now,
            )
            try:
                with session.begin_nested():
                    session.add(connection)
                    session.flush()
            except IntegrityError as exc:
                raise HTTPException(
                    409,
                    {
                        "code": "repository_connection_exists",
                        "message": "This private repository is already connected.",
                    },
                ) from exc
            return _repository_connection_json(connection)

    @app.delete("/repository-connections/{connection_id}", status_code=204)
    def delete_repository_connection(
        connection_id: str, ctx: AuthContext = Depends(require_session)
    ) -> Response:
        with db_session() as session:
            _capture_transaction_lock(
                session, ctx.org_id, f"repository-connection-user:{ctx.user_id}"
            )
            connection = _owned_repository_connection(session, connection_id, ctx, lock=True)
            analyses = list(
                session.scalars(
                    select(RepositoryAnalysisRow)
                    .where(
                        RepositoryAnalysisRow.org_id == ctx.org_id,
                        RepositoryAnalysisRow.creator_user_id == ctx.user_id,
                        RepositoryAnalysisRow.repository_connection_id == connection.id,
                    )
                    .order_by(RepositoryAnalysisRow.id)
                    .with_for_update()
                ).all()
            )
            active = [row for row in analyses if row.status in {"queued", "fetching", "analyzing"}]
            cancel_repository_analysis_jobs(session, [row.id for row in active])
            now = datetime.now(UTC)
            for row in active:
                row.cancel_requested = True
                row.status = "cancelled"
                row.error = "Repository connection was disconnected."
                row.error_code = "repository_connection_revoked"
                row.finished_at = now
                row.updated_at = now
                finish_ai_action(session, row.action_id, status="cancelled")
            for row in analyses:
                row.repository_connection_id = None
            connection.credential_encrypted = ""
            session.delete(connection)
        return Response(status_code=204)

    def _owned_repository_analysis(
        session: Session, analysis_id: str, ctx: AuthContext, *, lock: bool = False
    ) -> RepositoryAnalysisRow:
        statement = select(RepositoryAnalysisRow).where(
            RepositoryAnalysisRow.public_id == analysis_id,
            RepositoryAnalysisRow.org_id == ctx.org_id,
            RepositoryAnalysisRow.creator_user_id == ctx.user_id,
        )
        if lock:
            statement = statement.with_for_update().execution_options(populate_existing=True)
        row = session.scalar(statement)
        if row is None:
            raise HTTPException(404, "repository analysis not found")
        return row

    def _repository_analysis_json(
        row: RepositoryAnalysisRow, *, full: bool = True
    ) -> dict[str, Any]:
        metadata = dict(row.analysis_metadata or {})
        public_metadata: dict[str, Any] = {}
        for key in (
            "analysis_mode",
            "parser_ids",
            "parser_counts",
            "language_counts",
            "parser_mode_counts",
            "generic_file_count",
            "specific_file_count",
            "unsupported_file_count",
            "extracted_evidence_count",
            "persisted_evidence_count",
            "evidence_fact_limit_reached",
            "fact_extraction_complete",
            "adapter_skipped_resource_limit",
            "unresolved_submodule_count",
            "candidate_nodes_total",
            "candidate_nodes_retained",
            "candidate_nodes_omitted",
            "candidate_edges_total",
            "candidate_edges_retained",
            "candidate_edges_omitted",
        ):
            value = metadata.get(key)
            if isinstance(value, list):
                public_metadata[key] = [str(item)[:80] for item in value[:100]]
            elif isinstance(value, dict):
                public_metadata[key] = {
                    str(item_key)[:80]: max(0, int(item_value))
                    for item_key, item_value in list(value.items())[:100]
                    if isinstance(item_value, int)
                }
            elif isinstance(value, (str, int, bool)):
                public_metadata[key] = value
        payload: dict[str, Any] = {
            "public_id": row.public_id,
            "project_id": row.project_id,
            "repository_access": row.repository_access,
            "repository_url": row.repository_url,
            "owner": row.owner,
            "name": row.name,
            "ref": row.ref,
            "subpath": row.subpath,
            "commit_sha": row.commit_sha,
            "status": row.status,
            "error": row.error,
            "error_code": row.error_code,
            "goal": row.goal,
            "diagram_kind": row.diagram_kind,
            "language": row.language,
            "coverage": dict(row.coverage or {}),
            "analysis_metadata": public_metadata,
            "created_at": row.created_at.isoformat(),
            "updated_at": row.updated_at.isoformat(),
        }
        if full:
            payload["archive_sha256"] = row.archive_sha256
            payload["diagram_spec"] = dict(row.diagram_spec or {})
            payload["evidence"] = list(row.evidence or [])
        return payload

    @app.post("/repository-analyses", status_code=202)
    def create_repository_analysis(
        body: RepositoryAnalysisCreate,
        background: BackgroundTasks,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        """Analyze an authorized GitHub snapshot without executing it.

        The confirmation covers analysis and transmission of the bounded,
        screened goal with opaque graph metadata, plus screened display labels
        during optional figure styling. Raw repository evidence and code are
        not transmitted. The confirmation does not assert or infer a
        repository license from public visibility.
        """
        if not get_settings().repository_analysis_enabled:
            raise HTTPException(
                409,
                {
                    "code": "repository_analysis_disabled",
                    "message": "Repository analysis is temporarily disabled by the operator.",
                },
            )
        try:
            repository = parse_public_github_repository(body.repository_url)
            requested_ref = normalize_ref(body.ref)
            subpath = normalize_subpath(body.subpath)
        except RepositoryIngestError as exc:
            raise HTTPException(422, {"code": exc.code, "message": str(exc)}) from exc
        request_id = body.request_id.strip()
        goal = body.goal.strip()
        repository_connection_public_id = (body.repository_connection_id or "").strip()
        repository_access = "private" if repository_connection_public_id else "public"
        if not request_id or len(goal) < 3:
            raise HTTPException(422, "request_id and goal cannot be blank")
        fingerprint_payload = {
            "repository_url": repository.canonical_url,
            "ref": requested_ref,
            "subpath": subpath,
            "goal": goal,
            "diagram_kind": body.diagram_kind,
            "language": body.language,
            "project_id": body.project_id,
            "repository_connection_id": repository_connection_public_id or None,
            "repository_access": repository_access,
            "rights_confirmed": True,
        }
        fingerprint = hashlib.sha256(
            json.dumps(
                fingerprint_payload,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
            ).encode("utf-8")
        ).hexdigest()
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            existing = session.scalar(
                select(RepositoryAnalysisRow).where(
                    RepositoryAnalysisRow.org_id == ctx.org_id,
                    RepositoryAnalysisRow.creator_user_id == ctx.user_id,
                    RepositoryAnalysisRow.client_request_id == request_id,
                )
            )
            if existing is not None:
                if existing.request_fingerprint != fingerprint:
                    raise HTTPException(
                        409,
                        {
                            "code": "repository_request_id_conflict",
                            "message": "This request_id is already bound to another analysis.",
                        },
                    )
                return _repository_analysis_json(existing)
            project: Project | None = None
            if body.project_id is not None:
                project = _owned_project(session, body.project_id, ctx, lock=True)
            repository_connection: RepositoryConnectionRow | None = None
            if repository_connection_public_id:
                _capture_transaction_lock(
                    session, ctx.org_id, f"repository-connection-user:{ctx.user_id}"
                )
                repository_connection = _owned_repository_connection(
                    session, repository_connection_public_id, ctx, lock=True
                )
                if (
                    repository_connection.repository_url.casefold()
                    != repository.canonical_url.casefold()
                ):
                    raise HTTPException(
                        422,
                        {
                            "code": "repository_connection_mismatch",
                            "message": "The selected connection belongs to another repository.",
                        },
                    )
            _require_capability(session, ctx, Capability.STUDIO_BASIC)
            org = session.get(Org, ctx.org_id)
            assert org is not None
            plan = plan_for_org(org)
            base_credits = max(
                1,
                question_cost(1, plan=plan, input_chars=len(goal), context_size=0) * 2,
            )
            now = datetime.now(UTC)
            row = RepositoryAnalysisRow(
                org_id=ctx.org_id,
                creator_user_id=ctx.user_id,
                project_id=project.id if project is not None else None,
                repository_connection_id=repository_connection.id
                if repository_connection is not None
                else None,
                repository_access=repository_access,
                client_request_id=request_id,
                request_fingerprint=fingerprint,
                repository_url=repository.canonical_url,
                owner=repository.owner,
                name=repository.name,
                ref=requested_ref,
                subpath=subpath,
                goal=goal,
                diagram_kind=body.diagram_kind,
                language=body.language,
                rights_confirmed=True,
                rights_confirmed_at=now,
                status="queued",
                action_id=secrets.token_urlsafe(18),
                base_credits=base_credits,
            )
            try:
                with session.begin_nested():
                    session.add(row)
                    session.flush()
            except IntegrityError as exc:
                existing = session.scalar(
                    select(RepositoryAnalysisRow).where(
                        RepositoryAnalysisRow.org_id == ctx.org_id,
                        RepositoryAnalysisRow.creator_user_id == ctx.user_id,
                        RepositoryAnalysisRow.client_request_id == request_id,
                    )
                )
                if existing is None:
                    raise
                if existing.request_fingerprint != fingerprint:
                    raise HTTPException(
                        409,
                        {
                            "code": "repository_request_id_conflict",
                            "message": "This request_id is already bound to another analysis.",
                        },
                    ) from exc
                return _repository_analysis_json(existing)
            try:
                begin_ai_action(
                    session,
                    org,
                    action="repository_analysis",
                    resource_type="repository_analysis",
                    resource_id=row.id,
                    action_id=row.action_id,
                    reserve_credits=base_credits,
                )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            enqueue_job(
                background,
                _execute_repository_analysis,
                row.id,
                session=session,
                timeout_seconds=3600,
                max_attempts=2,
                queue_org_id=ctx.org_id,
            )
            return _repository_analysis_json(row)

