    @app.patch("/voice/invites/{invite_id}")
    def patch_voice_invite(
        invite_id: str,
        body: VoiceInvitePatch,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        with db_session() as session:
            invite = session.scalar(
                select(VoiceInviteRow).where(
                    VoiceInviteRow.public_id == invite_id,
                    VoiceInviteRow.org_id == ctx.org_id,
                )
            )
            if invite is None:
                raise HTTPException(404, "invite not found")
            if body.active:
                _require_capability(session, ctx, Capability.RESEARCH_STUDIO)
                study = session.get(VoiceStudyRow, invite.study_id)
                assert study is not None
                _require_voice_participant_information(study)
            invite.active = body.active
            used = session.scalar(
                select(func.count()).where(
                    VoiceSessionRow.invite_id == invite.id,
                    or_(
                        VoiceSessionRow.status.in_(("running", "completed")),
                        and_(
                            VoiceSessionRow.status == "aborted",
                            VoiceSessionRow.cost_units > 0,
                        ),
                    ),
                )
            )
            return _voice_invite_json(invite, int(used or 0))

    def _describe_voice_action(action: dict[str, Any]) -> str:
        operation = str(action.get("operation") or "")
        if operation == "set_guide":
            return f"Replace guide: {len(action.get('sections') or [])} topics"
        if operation == "set_persona":
            changes = dict(action.get("changes") or {})
            pretty = {
                "patience_ms": lambda value: f"patience {value} ms",
                "max_session_minutes": lambda value: f"cap {value} min",
                "budget_minutes": lambda value: f"budget {value} min",
            }
            parts = [
                pretty.get(key, lambda v, k=key: f"{k.replace('_', ' ')} {v}")(value)
                for key, value in changes.items()
            ]
            return "Interviewer: " + ", ".join(parts)
        if operation == "set_consent":
            return "Update participant-facing texts"
        if operation == "rename":
            return f"Rename to “{action.get('title', '')}”"
        return operation

    def _voice_action_changes(
        action: dict[str, Any],
        *,
        before_sections: Sequence[Mapping[str, Any]] | None = None,
    ) -> list[dict[str, Any]]:
        """Expose only concrete guide differences in the agent timeline."""
        operation = str(action.get("operation") or "")
        if operation != "set_guide":
            return [{"operation": operation, "label": _describe_voice_action(action)}]
        sections = [dict(section) for section in action.get("sections") or []]
        previous = (
            [dict(section) for section in before_sections] if before_sections is not None else []
        )
        changes: list[dict[str, Any]] = []
        for offset in range(max(len(previous), len(sections))):
            before = previous[offset] if offset < len(previous) else None
            after = sections[offset] if offset < len(sections) else None
            if before == after:
                continue
            if before is None:
                change_operation = "add_guide_topic"
                prefix = "Added"
            elif after is None:
                change_operation = "remove_guide_topic"
                prefix = "Removed"
            else:
                change_operation = "update_guide_topic"
                prefix = "Updated"
            visible = after or before or {}
            changes.append(
                {
                    "operation": change_operation,
                    "label": f"{prefix} topic {offset + 1}: {str(visible.get('title') or 'Untitled')}",
                    "detail": "\n".join(
                        part
                        for part in (
                            str(visible.get("question") or "").strip(),
                            "Probes: "
                            + " · ".join(str(item) for item in visible.get("probes") or [])
                            if visible.get("probes")
                            else "",
                        )
                        if part
                    ),
                    "input": {"operation": change_operation, "index": offset},
                    "before": before,
                    "after": after,
                }
            )
        return changes

    def _apply_study_actions(
        row: VoiceStudyRow, actions: list[dict[str, Any]], *, session_cap_minutes: int
    ) -> list[dict[str, Any]]:
        """Land validated designer actions through the editor's own rules."""
        assessed_scope_before = _voice_study_assessed_scope(row)
        results: list[dict[str, Any]] = []
        total_actions = len(actions)
        for action_index, action in enumerate(actions, start=1):
            operation = str(action.get("operation") or "")
            before_state: Any = None
            after_state: Any = None
            emit_agent_event(
                "tool.started",
                tool=f"interview_study.{operation or 'apply_change'}",
                label=str(action.get("label") or operation.replace("_", " ").title()),
                detail="Applying this validated change to the open interview study.",
                input=safe_event_value(action),
                index=action_index,
                total=total_actions,
            )
            before_count = len(results)
            if operation == "set_guide":
                before_state = dict(row.guide or {})
                normalized = {"sections": action["sections"]}
                if normalized != dict(row.guide or {}):
                    row.guide = normalized
                    row.guide_version += 1
                after_state = dict(row.guide or {})
                results.extend(
                    {**change, "applied": True}
                    for change in _voice_action_changes(
                        action,
                        before_sections=list(before_state.get("sections") or []),
                    )
                )
                results.append(
                    {
                        "operation": operation,
                        "applied": True,
                        "label": f"Guide replaced: {len(normalized['sections'])} topics (v{row.guide_version})",
                        "detail": "All topics were validated and written in the displayed order.",
                        "timeline_hidden": True,
                    }
                )
            elif operation == "set_persona":
                before_state = {
                    "tone": row.tone,
                    "voice": row.voice,
                    "language": row.language,
                    "mode": row.mode,
                    "patience_ms": row.patience_ms,
                    "max_session_minutes": row.max_session_minutes,
                    "retention": row.retention,
                    "budget_minutes": row.budget_minutes,
                }
                changes = dict(action.get("changes") or {})
                applied: list[str] = []
                if "tone" in changes:
                    row.tone = changes["tone"]
                    applied.append(f"tone {changes['tone']}")
                if "voice" in changes:
                    row.voice = changes["voice"]
                    applied.append(f"voice {changes['voice']}")
                if "language" in changes:
                    row.language = changes["language"]
                    applied.append(f"language {changes['language']}")
                if "mode" in changes:
                    row.mode = changes["mode"]
                    applied.append(f"mode {changes['mode']}")
                if "patience_ms" in changes:
                    row.patience_ms = min(3000, max(600, changes["patience_ms"]))
                    applied.append(f"patience {row.patience_ms} ms")
                next_max_session_minutes = row.max_session_minutes
                if "max_session_minutes" in changes:
                    next_max_session_minutes = min(
                        session_cap_minutes,
                        max(LIVE_SESSION_MIN_MINUTES, changes["max_session_minutes"]),
                    )
                    applied.append(f"cap {next_max_session_minutes} min")
                if "retention" in changes:
                    row.retention = changes["retention"]
                    applied.append(
                        "recording kept" if changes["retention"] == "keep" else "transcript only"
                    )
                next_budget_minutes = row.budget_minutes
                if "budget_minutes" in changes:
                    next_budget_minutes = min(
                        6000, max(LIVE_SESSION_MIN_MINUTES, changes["budget_minutes"])
                    )
                budget_was_aligned = next_budget_minutes < next_max_session_minutes
                if budget_was_aligned:
                    next_budget_minutes = next_max_session_minutes
                row.max_session_minutes = next_max_session_minutes
                row.budget_minutes = next_budget_minutes
                if "budget_minutes" in changes or budget_was_aligned:
                    budget_label = f"budget {row.budget_minutes} min"
                    if budget_was_aligned:
                        budget_label += " (matched to session cap)"
                    applied.append(budget_label)
                _require_valid_voice_study_limits(
                    max_session_minutes=row.max_session_minutes,
                    budget_minutes=row.budget_minutes,
                )
                results.append(
                    {
                        "operation": operation,
                        "applied": bool(applied),
                        "label": "Interviewer updated: " + ", ".join(applied)
                        if applied
                        else "No valid interviewer change",
                    }
                )
                after_state = {
                    "tone": row.tone,
                    "voice": row.voice,
                    "language": row.language,
                    "mode": row.mode,
                    "patience_ms": row.patience_ms,
                    "max_session_minutes": row.max_session_minutes,
                    "retention": row.retention,
                    "budget_minutes": row.budget_minutes,
                }
            elif operation == "set_consent":
                before_state = {
                    "consent_text": row.consent_text,
                    "contact_line": row.contact_line,
                }
                changes = dict(action.get("changes") or {})
                if "consent_text" in changes:
                    row.consent_text = changes["consent_text"][:4000]
                if "contact_line" in changes:
                    row.contact_line = changes["contact_line"][:240]
                results.append(
                    {
                        "operation": operation,
                        "applied": True,
                        "label": "Participant-facing texts updated",
                    }
                )
                after_state = {
                    "consent_text": row.consent_text,
                    "contact_line": row.contact_line,
                }
            elif operation == "rename":
                before_state = {"title": row.title}
                row.title = action["title"]
                after_state = {"title": row.title}
                results.append(
                    {
                        "operation": operation,
                        "applied": True,
                        "label": f"Renamed to “{row.title}”",
                    }
                )
            action_results = results[before_count:]
            action_applied = any(result.get("applied") for result in action_results)
            emit_agent_event(
                "tool.completed" if action_applied else "tool.failed",
                tool=f"interview_study.{operation or 'apply_change'}",
                label=str(action_results[-1].get("label"))
                if action_results
                else "No valid interview-study change",
                detail="The open interview study was updated."
                if action_applied
                else "The requested change did not pass the study editor rules.",
                output=safe_event_value(action_results),
                before=safe_event_value(before_state),
                after=safe_event_value(after_state),
                applied=action_applied,
                index=action_index,
                total=total_actions,
                result_count=len(action_results),
            )
        if assessed_scope_before != _voice_study_assessed_scope(row):
            _invalidate_voice_study_approval(row)
        return results

