    @app.post("/voice/studies/{study_id}/chat")
    def voice_study_chat(
        study_id: str,
        body: VoiceStudyChatCreate,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        """The study designer agent: it drafts and edits the guide, persona
        and consent through the same validated rules as the manual editor,
        so it can never do anything the researcher could not."""
        if current_agent_turn_row_id() is None:
            return _specialist_chat_sync(
                kind="interview-study",
                resource_id=study_id,
                org_id=ctx.org_id,
                user_id=ctx.user_id,
                turn_id=body.turn_id,
                request_payload=body.model_dump(mode="json", exclude={"turn_id"}),
                worker=lambda: voice_study_chat(study_id, body, ctx),
                authorize=lambda session: _owned_voice_study_for_ai(session, study_id, ctx),
            )
        with db_session() as session:
            _begin_specialist_chat_start(session)
            chat_model = _resolve_chat_model_for(session, ctx, body.model)
            row = _owned_voice_study_for_ai(session, study_id, ctx)
            _lock_specialist_chat_resource(session, row)
            if body.auto_apply:
                _ensure_voice_study_mutable(session, row)
            org = session.get(Org, ctx.org_id)
            assert org is not None
            try:
                plan = check_can_ask(
                    session,
                    org,
                    multiplier=chat_model.multiplier,
                    input_chars=len(body.question),
                    context_size=None,
                )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            study_base_credits = question_cost(
                chat_model.multiplier,
                plan=plan,
                input_chars=len(body.question),
                context_size=None,
            )
            session_rows = session.scalars(
                select(VoiceSessionRow)
                .where(VoiceSessionRow.study_id == row.id)
                .order_by(VoiceSessionRow.id.desc())
                .limit(5)
            ).all()
            history = load_context_rows(
                session,
                VoiceStudyMessageRow,
                resource_column=VoiceStudyMessageRow.study_id,
                resource_id=row.id,
                org_id=row.org_id,
                current_request=body.question,
            )
            requested_study_scope = _voice_study_scope_fingerprint(row)
            try:
                with _scoped_action_pool(
                    session,
                    org,
                    action="voice_study_chat",
                    resource_type="voice_study",
                    resource_id=row.id,
                    model_id=chat_model.id,
                    action_id=agent_turn_action_id(ctx.org_id, body.turn_id),
                    reserve_credits=study_base_credits,
                    settle_reserved_credits=False,
                ) as pool:
                    turn = run_study_agent(
                        pool,
                        request=body.question,
                        study={
                            "title": row.title,
                            "language": row.language,
                            "tone": row.tone,
                            "voice": row.voice,
                            "patience_ms": row.patience_ms,
                            "max_session_minutes": row.max_session_minutes,
                            "retention": row.retention,
                            "budget_minutes": row.budget_minutes,
                            "consent_text": row.consent_text,
                            "contact_line": row.contact_line,
                            "guide_version": row.guide_version,
                            "guide": dict(row.guide or {}),
                            "recent_sessions": [
                                {
                                    "participant": item.participant_label,
                                    "status": item.status,
                                    "minutes": round(item.duration_ms / 60000, 1),
                                }
                                for item in session_rows
                            ],
                        },
                        history=[
                            {"role": message.role, "content": message.content}
                            for message in reversed(history)
                            if not _is_specialist_terminal_receipt(message)
                            and (not _specialist_message_belongs_to_turn(message, body.turn_id))
                        ],
                        language=ctx.language,
                        assistant_preferences=ctx.assistant_preferences,
                    )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            except LLMConfigError as exc:
                raise HTTPException(503, "The AI assistant is not available right now.") from exc
            proposals: list[dict[str, Any]] = []
            if body.auto_apply:
                if session.get_bind().dialect.name == "sqlite":
                    session.connection().exec_driver_sql("BEGIN IMMEDIATE")
                row = _owned_voice_study_for_ai(session, study_id, ctx, for_update=True)
                fence_agent_turn(session)
                _ensure_voice_study_mutable(session, row)
                if _voice_study_scope_fingerprint(row) != requested_study_scope:
                    raise HTTPException(
                        409,
                        "the study changed while the designer was working; review and retry",
                    )
                org = session.scalar(
                    select(Org)
                    .where(Org.id == ctx.org_id)
                    .execution_options(populate_existing=True)
                )
                assert org is not None
                plan = plan_for_org(org)
                results = _apply_study_actions(
                    row,
                    turn.actions,
                    session_cap_minutes=_plan_max_live_session_minutes(plan),
                )
                assistant_payload: dict[str, Any] = {"actions": results}
            else:
                results = []
                proposals = [
                    change
                    for action in turn.actions
                    for change in _voice_action_changes(
                        action,
                        before_sections=list(dict(row.guide or {}).get("sections") or []),
                    )
                ]
                assistant_payload = (
                    {
                        "proposals": proposals,
                        "proposed_actions": turn.actions,
                        "resolved": False,
                    }
                    if proposals
                    else {"actions": []}
                )
                for index, proposal in enumerate(proposals, start=1):
                    emit_agent_event(
                        "change.proposed",
                        tool="interview_study.propose_change",
                        operation=str(proposal.get("operation") or "guide_change"),
                        label=str(
                            proposal.get("label")
                            or proposal.get("text")
                            or "Prepared an interview-study change"
                        )[:500],
                        detail=str(proposal.get("detail") or "")[:2000],
                        input=safe_event_value(proposal),
                        applied=False,
                        index=index,
                        total=len(proposals),
                    )
            execution_results = (
                results
                if body.auto_apply
                else [{**proposal, "applied": False, "staged": True} for proposal in proposals]
            )
            answer = turn.answer
            if execution_results:
                try:
                    with _scoped_action_pool(
                        session,
                        org,
                        action="voice_study_chat_result_review",
                        resource_type="voice_study",
                        resource_id=row.id,
                        model_id=chat_model.id,
                        action_id=agent_turn_action_id(ctx.org_id, body.turn_id, "result_review"),
                    ) as result_pool:
                        reviewed = review_execution_results(
                            result_pool,
                            workspace="interview_study",
                            request=body.question,
                            initial_answer=answer,
                            executed_results=execution_results,
                            language=ctx.language,
                        )
                    answer = reviewed.answer
                except (EntitlementError, LLMConfigError):
                    emit_agent_event(
                        "checkpoint.completed",
                        tool="interview_study.inspect_results",
                        label="Interview changes ready",
                        detail="The applied or staged interview changes are ready to review.",
                        output=safe_event_value(execution_results),
                        result_count=len(execution_results),
                    )
            assistant_payload["workspace_actions"] = bind_workspace_actions(
                turn.workspace_actions,
                project_id=row.project_id,
                source_type="ai_interview",
                source_id=row.public_id,
                source_title=row.title,
                source_numeric_id=row.id,
            )
            fence_agent_turn(session)
            assistant = VoiceStudyMessageRow(
                org_id=ctx.org_id,
                study_id=row.id,
                role="assistant",
                content=answer,
                payload=assistant_payload,
            )
            _ensure_specialist_user_message(
                session,
                kind="interview-study",
                resource_id=row.public_id,
                org_id=ctx.org_id,
                turn_id=body.turn_id,
                request_payload=body.model_dump(mode="json", exclude={"turn_id"}),
            )
            session.add(assistant)
            charge_credits(
                session,
                org,
                action="question",
                credits=study_base_credits,
                model=chat_model.id,
            )
            session.flush()
            return {
                "answer": answer,
                "actions": results,
                "proposals": proposals,
                "workspace_actions": assistant_payload["workspace_actions"],
                "message_id": assistant.id,
                "study": _voice_study_json(row),
            }

    @app.post("/voice/studies/{study_id}/chat/stream")
    def voice_study_chat_stream(
        study_id: str,
        body: VoiceStudyChatCreate,
        request: Request,
        ctx: AuthContext = Depends(require_session),
    ) -> StreamingResponse:
        return _specialist_chat_sse(
            kind="interview-study",
            resource_id=study_id,
            org_id=ctx.org_id,
            user_id=ctx.user_id,
            turn_id=body.turn_id,
            request_payload=body.model_dump(mode="json", exclude={"turn_id"}),
            last_event_id=_last_sse_event_id(request),
            worker=lambda: voice_study_chat(study_id, body, ctx),
            authorize=lambda session: _owned_voice_study_for_ai(session, study_id, ctx),
        )

    @app.post("/voice/studies/{study_id}/chat/{message_id}/apply")
    def apply_voice_study_proposal(
        study_id: str, message_id: int, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        """Land a staged designer proposal through the editor's own rules;
        a proposal resolves exactly once."""
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            row = _owned_voice_study(session, study_id, ctx, for_update=True)
            _require_capability(session, ctx, Capability.RESEARCH_STUDIO)
            _ensure_voice_study_mutable(session, row)
            org = session.get(Org, ctx.org_id)
            assert org is not None
            message = session.get(VoiceStudyMessageRow, message_id)
            if message is None or message.study_id != row.id or message.role != "assistant":
                raise HTTPException(404, "proposal not found")
            payload = dict(message.payload or {})
            actions = [dict(action) for action in payload.get("proposed_actions") or []]
            if not actions:
                raise HTTPException(404, "proposal not found")
            if payload.get("resolved"):
                raise HTTPException(409, "the proposal was already applied")
            results = _apply_study_actions(
                row,
                actions,
                session_cap_minutes=_plan_max_live_session_minutes(plan_for_org(org)),
            )
            payload["resolved"] = True
            payload["actions"] = results
            message.payload = payload
            session.flush()
            return {"actions": results, "study": _voice_study_json(row)}

    _talk_limiter = build_rate_limiter("talk", max_hits=10, window_seconds=60.0)

    def _public_invite(
        session: Session, token: str, *, for_update: bool = False
    ) -> tuple[VoiceInviteRow, VoiceStudyRow]:
        invite_statement = select(VoiceInviteRow).where(VoiceInviteRow.public_id == token)
        if for_update:
            invite_statement = invite_statement.with_for_update()
        invite = session.scalar(invite_statement)
        if invite is None:
            raise HTTPException(404, "this invitation does not exist")
        study_statement = select(VoiceStudyRow).where(VoiceStudyRow.id == invite.study_id)
        if for_update:
            study_statement = study_statement.with_for_update()
        study = session.scalar(study_statement)
        assert study is not None
        _normalize_voice_study_limits(study)
        return (invite, study)

    def _public_consent_surface(study: VoiceStudyRow, plan: Plan) -> dict[str, Any]:
        """Canonical participant-facing facts accepted by consent."""
        spoken_available = bool(
            get_settings().public_gemini_live_enabled and voice_study_spoken_processing_ready(study)
        )
        return {
            "title": study.title,
            "language": study.language,
            "expected_minutes": min(
                study.max_session_minutes, _plan_max_live_session_minutes(plan)
            ),
            "minimum_age": 18,
            "retention": study.retention,
            "consent_text": study.consent_text,
            "contact_line": study.contact_line,
            "study_scope_revision": str(
                (study.participant_information or {}).get("dpia_public_scope_token") or ""
            ),
            "available_modes": ["text", "live"] if spoken_available else ["text"],
            "live_provider": "Google Gemini",
            "provider_disclosure_version": PUBLIC_TALK_CONSENT_VERSION,
            "privacy_notice_url": get_settings().privacy_notice_url,
            "terms_url": get_settings().terms_url,
            "age_declaration": "Ich bestätige, dass ich mindestens 18 Jahre alt bin."
            if study.language == "de"
            else "I confirm that I am at least 18 years old.",
            "participant_notices": {
                mode: participant_notice(
                    dict(study.participant_information or {}),
                    mode=cast(Literal["text", "live"], mode),
                    language=study.language,
                    recording=study.retention == "keep",
                )
                for mode in (["text", "live"] if spoken_available else ["text"])
            },
        }

    def _public_consent_fingerprint(study: VoiceStudyRow, plan: Plan) -> str:
        encoded = json.dumps(
            _public_consent_surface(study, plan),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        return hashlib.sha256(encoded).hexdigest()

    def _invite_state(session: Session, invite: VoiceInviteRow, study: VoiceStudyRow) -> str:
        """open, or the honest reason the door is closed."""
        if not invite.active:
            return "inactive"
        if invite.expires_at is not None:
            expires = invite.expires_at
            if expires.tzinfo is None:
                expires = expires.replace(tzinfo=UTC)
            if expires < datetime.now(UTC):
                return "expired"
        if voice_participant_information_gaps(
            study.participant_information,
            expected_scope_fingerprint=_voice_study_scope_fingerprint(study),
            study_language=study.language,
        ):
            return "unavailable"
        used = int(
            session.scalar(
                select(func.count()).where(
                    VoiceSessionRow.invite_id == invite.id,
                    or_(
                        VoiceSessionRow.status.in_(("running", "completed")),
                        and_(
                            VoiceSessionRow.status == "aborted",
                            VoiceSessionRow.cost_units > 0,
                        ),
                    ),
                )
            )
            or 0
        )
        if used >= invite.max_sessions:
            return "full"
        org = session.get(Org, study.org_id)
        assert org is not None
        try:
            check_capability(org, Capability.RESEARCH_STUDIO)
        except EntitlementError:
            return "unavailable"
        used_minutes = _study_used_minutes(session, study)
        authorized_minutes = min(
            study.max_session_minutes, _plan_max_live_session_minutes(plan_for_org(org))
        )
        if used_minutes + authorized_minutes > study.budget_minutes:
            return "full"
        return "open"

    @app.get("/public/talk/{token}")
    def public_talk_info(token: str, request: Request) -> dict[str, Any]:
        """What a participant may know before consenting: the study surface,
        never the guide, never the prompt."""
        _throttle(_public_read_limiter, request)
        with db_session() as session:
            invite, study = _public_invite(session, token)
            running = session.scalars(
                select(VoiceSessionRow).where(
                    VoiceSessionRow.invite_id == invite.id,
                    VoiceSessionRow.status == "running",
                )
            ).all()
            for item in running:
                _expire_stalled_voice_session(session, study, item)
            state = _invite_state(session, invite, study)
            org = session.get(Org, study.org_id)
            assert org is not None
            plan = plan_for_org(org)
            consent_surface = _public_consent_surface(study, plan)
            return {
                "state": state,
                "live_available": "live" in consent_surface["available_modes"],
                **consent_surface,
                "consent_fingerprint": _public_consent_fingerprint(study, plan),
                "passcode_required": bool(invite.passcode),
            }

    @app.post("/public/talk/{token}/sessions", status_code=202)
    def public_talk_start(token: str, body: PublicTalkStart, request: Request) -> dict[str, Any]:
        """Consent in, single-use app relay ticket out. The consent timestamp
        is part of the session's audit record."""
        _throttle(_talk_limiter, request)
        if not body.consent:
            raise HTTPException(422, "consent is required to start")
        settings = get_settings()
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            invite, study = _public_invite(session, token, for_update=True)
            if not body.age_confirmed:
                raise HTTPException(
                    422,
                    "Bitte bestätigen Sie, dass Sie mindestens 18 Jahre alt sind."
                    if study.language == "de"
                    else "Please confirm that you are at least 18 years old.",
                )
            org = session.get(Org, study.org_id)
            assert org is not None
            plan = plan_for_org(org)
            if not secrets.compare_digest(
                body.consent_fingerprint, _public_consent_fingerprint(study, plan)
            ):
                raise HTTPException(
                    409, "study consent information changed; reload before consenting"
                )
            state = _invite_state(session, invite, study)
            if state != "open":
                raise HTTPException(409, f"this study is not accepting sessions ({state})")
            used_minutes_before = _study_used_minutes(session, study)
            if invite.passcode:
                supplied = body.passcode.strip()
                if invite.passcode.startswith("pbkdf2_sha256$"):
                    valid_passcode = verify_password(supplied, invite.passcode)
                else:
                    valid_passcode = secrets.compare_digest(supplied, invite.passcode)
                    if valid_passcode:
                        invite.passcode = hash_password(supplied)
                if not valid_passcode:
                    raise HTTPException(403, "wrong access code")
            text_mode = body.mode == "text"
            if not text_mode and (
                not settings.public_gemini_live_enabled
                or not voice_study_spoken_processing_ready(study)
            ):
                raise HTTPException(409, _public_spoken_voice_unavailable_detail(study.language))
            if not text_mode and (not body.audio_consent):
                raise HTTPException(
                    422,
                    "Please confirm audio processing before starting the spoken interview.",
                )
            authorization_caps = [
                study.max_session_minutes,
                _plan_max_live_session_minutes(plan),
            ]
            authorized_minutes = min(authorization_caps)
            reserve_credits = (
                authorized_minutes * question_cost(plan=plan)
                if text_mode
                else interview_live_minutes_cost(authorized_minutes * 60000, plan)
            )
            try:
                check_credits(session, org, reserve_credits)
            except EntitlementError as exc:
                raise HTTPException(409, _public_voice_capacity_detail(study.language)) from exc
            nth = (
                int(
                    session.scalar(
                        select(func.count()).where(
                            VoiceSessionRow.study_id == study.id,
                            VoiceSessionRow.kind == "field",
                        )
                    )
                    or 0
                )
                + 1
            )
            prefix = invite.label.strip()
            participant_label = f"{prefix} {nth}" if prefix else f"P{nth}"
            prompt = build_interviewer_prompt(
                title=study.title,
                language=study.language,
                tone=study.tone,
                guide=dict(study.guide or {}),
                max_session_minutes=authorized_minutes,
                mode=study.mode,
            )
            live = VoiceSessionRow(
                org_id=study.org_id,
                study_id=study.id,
                invite_id=invite.id,
                kind="field",
                model="text" if text_mode else LIVE_MODEL,
                guide_version=study.guide_version,
                prompt=prompt,
                participant_label=participant_label,
                consent_at=datetime.now(UTC),
                consent_fingerprint=body.consent_fingerprint,
                consent_snapshot=participation_snapshot(
                    _public_consent_surface(study, plan),
                    consent=bool(
                        body.consent
                        and (study.participant_information or {}).get("legal_basis") == "consent"
                    ),
                    audio_consent=bool(body.audio_consent and (not text_mode)),
                    age_confirmed=body.age_confirmed,
                    mode=body.mode,
                ),
                authorized_duration_ms=authorized_minutes * 60000,
            )
            session.add(live)
            session.flush()
            try:
                action_row = begin_ai_action(
                    session,
                    org,
                    action="interview_text_turn" if text_mode else "interview_live",
                    resource_type="voice_session",
                    resource_id=live.id,
                    reserve_credits=reserve_credits,
                )
                if text_mode:
                    reserved_units = authorized_minutes * question_cost(plan=plan)
                else:
                    affordable_minutes = affordable_live_minutes(action_row.cost_limit_usd)
                    if affordable_minutes < LIVE_SESSION_MIN_MINUTES:
                        raise EntitlementError(
                            "The available AI capacity cannot cover the minimum live session.",
                            code="capacity_exhausted",
                        )
                    authorized_minutes = min(authorized_minutes, affordable_minutes)
                    reserved_units = interview_live_minutes_cost(authorized_minutes * 60000, plan)
                action_row.reserved_credits = reserved_units
                action_row.remaining_credits = reserved_units
                if not text_mode:
                    action_row.cost_limit_usd = min(
                        action_row.cost_limit_usd,
                        authorized_minutes * LIVE_MINUTE_COST_USD,
                    )
                    check_action_cost(
                        session,
                        action_row.action_id,
                        authorized_minutes * LIVE_MINUTE_COST_USD,
                    )
            except EntitlementError as exc:
                raise HTTPException(409, _public_voice_capacity_detail(study.language)) from exc
            if used_minutes_before + authorized_minutes > study.budget_minutes:
                raise HTTPException(409, "this study is not accepting sessions (full)")
            prompt = build_interviewer_prompt(
                title=study.title,
                language=study.language,
                tone=study.tone,
                guide=dict(study.guide or {}),
                max_session_minutes=authorized_minutes,
                mode=study.mode,
            )
            live.prompt = prompt
            live.authorized_duration_ms = authorized_minutes * 60000
            payload = {
                "id": live.public_id,
                "mode": body.mode,
                "language": study.language,
                "max_session_minutes": authorized_minutes,
                "retention": study.retention,
                "participant_label": participant_label,
            }
            if not text_mode:
                payload.update(
                    {
                        **prepare_voice_relay(live, study, action_row),
                        "model": LIVE_MODEL,
                    }
                )
            return payload

    def _public_running_session(
        session: Session, token: str, session_id: str, *, for_update: bool = False
    ) -> tuple[VoiceSessionRow, VoiceStudyRow]:
        invite, study = _public_invite(session, token, for_update=for_update)
        statement = select(VoiceSessionRow).where(
            VoiceSessionRow.public_id == session_id,
            VoiceSessionRow.invite_id == invite.id,
        )
        if for_update:
            statement = statement.with_for_update()
        live = session.scalar(statement)
        if live is None:
            raise HTTPException(404, "session not found")
        return (live, study)

    def _require_public_session_continuation(
        session: Session,
        invite: VoiceInviteRow,
        study: VoiceStudyRow,
        live: VoiceSessionRow,
    ) -> None:
        """Recheck revocable authorization before every billable text turn.

        Session-count and study-budget gates apply only when a session starts:
        the running session itself may have filled those limits. The exact
        approved guide and consent surface are frozen while a session runs,
        but link revocation, link expiry and workspace capability loss take
        effect immediately, matching the spoken relay's recurring checks.
        """
        now = datetime.now(UTC)
        if not invite.active:
            state = "inactive"
        elif (
            invite.expires_at is not None
            and (
                invite.expires_at.replace(tzinfo=UTC)
                if invite.expires_at.tzinfo is None
                else invite.expires_at
            )
            <= now
        ):
            state = "expired"
        elif (
            live.consent_at is None
            or not live.consent_fingerprint
            or (not voice_study_participation_ready(study))
            or (not voice_session_scope_matches(study, live.consent_snapshot))
        ):
            state = "unavailable"
        else:
            org = session.get(Org, study.org_id)
            if org is None:
                state = "unavailable"
            else:
                try:
                    check_capability(org, Capability.RESEARCH_STUDIO)
                except EntitlementError:
                    state = "unavailable"
                else:
                    return
        raise HTTPException(409, f"this session is no longer authorized ({state})")

    @app.post("/public/talk/{token}/sessions/{session_id}/reissue")
    def public_talk_reissue(
        token: str, session_id: str, body: PublicTalkReissue, request: Request
    ) -> dict[str, Any]:
        """Reject legacy replacement-token requests without provider egress.

        Gemini credentials cannot be revoked after issuance. Minting another
        credential after a network loss could therefore leave two sessions
        consuming the same action budget concurrently. Scheduled socket
        rotations continue through Gemini session-resumption handles in the
        browser; an interruption without a safe handle ends and saves the
        partial interview instead.
        """
        _throttle(_talk_limiter, request)
        del body
        with db_session() as session:
            _, study = _public_running_session(session, token, session_id)
            german = study.language == "de"
            message = (
                "Die Verbindung wurde unterbrochen und kann nicht fortgesetzt werden. Bitte beenden Sie das Interview, um den bisherigen Stand zu speichern."
                if german
                else "The connection was interrupted and cannot be continued. Please end the interview to save the progress so far."
            )
            raise HTTPException(409, message)

    @app.post("/public/talk/{token}/sessions/{session_id}/messages")
    def public_talk_message(
        token: str, session_id: str, body: PublicTalkMessage, request: Request
    ) -> dict[str, Any]:
        """Continue an explicitly text-mode interview within its time cap."""
        _throttle(_talk_limiter, request)
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            invite, study = _public_invite(session, token, for_update=True)
            live = session.scalar(
                select(VoiceSessionRow)
                .where(
                    VoiceSessionRow.public_id == session_id,
                    VoiceSessionRow.invite_id == invite.id,
                )
                .with_for_update()
            )
            if live is None:
                raise HTTPException(404, "session not found")
            _require_public_session_continuation(session, invite, study, live)
            if live.status != "running":
                raise HTTPException(409, "the session is already settled")
            if live.model != "text":
                raise HTTPException(409, "live audio sessions do not accept text turns")
            prompt = live.prompt
            language = study.language
            org_id = study.org_id
            resource_id = live.id
            reservation = session.scalar(
                select(CapacityReservationRow)
                .where(
                    CapacityReservationRow.org_id == org_id,
                    CapacityReservationRow.resource_type == "voice_session",
                    CapacityReservationRow.resource_id == str(resource_id),
                    CapacityReservationRow.status == "active",
                )
                .with_for_update()
            )
            if reservation is None or reservation.action != "interview_text_turn":
                raise HTTPException(409, "the session authorization has expired")
            session_action_id = reservation.action_id
            session_org = session.get(Org, org_id)
            assert session_org is not None
            plan = plan_for_org(session_org)
            authorized_minutes = _voice_authorized_minutes(live, study, reservation, plan)
            started_at = live.started_at
            if started_at.tzinfo is None:
                started_at = started_at.replace(tzinfo=UTC)
            if datetime.now(UTC) - started_at >= timedelta(minutes=authorized_minutes):
                raise HTTPException(409, "the session time limit has been reached")
            per_turn_units = max(1, reservation.reserved_credits // authorized_minutes)
            max_turns = max(1, reservation.reserved_credits // per_turn_units)
            if live.text_turns_claimed >= max_turns:
                raise HTTPException(409, "the text interview turn limit has been reached")
            live.text_turns_claimed += 1
            claimed_session_id = live.id
            claimed_public_id = live.public_id
        german = language == "de"
        chat_note = (
            "\nDies ist ein schriftliches Interview in einem Chat. Antworte als Interviewerin in kurzen Chat-Nachrichten, eine Frage auf einmal, ohne Formatierung."
            if german
            else "\nThis is a written interview in a chat. Answer as the interviewer in short chat messages, one question at a time, no formatting."
        )
        who = {
            "interviewer": "Interviewerin" if german else "Interviewer",
            "participant": "Person" if german else "Participant",
        }
        history = render_conversation_context(
            [
                {
                    "role": "assistant" if turn.role == "interviewer" else "user",
                    "content": turn.text,
                }
                for turn in body.history
            ],
            max_chars=16000,
            recent_turns=30,
            per_turn_chars=1200,
            current_request=body.message,
        )

        def release_text_turn_claim() -> None:
            with db_session() as release_session:
                if release_session.get_bind().dialect.name == "sqlite":
                    release_session.connection().exec_driver_sql("BEGIN IMMEDIATE")
                claimed = release_session.scalar(
                    select(VoiceSessionRow)
                    .where(VoiceSessionRow.id == claimed_session_id)
                    .with_for_update()
                )
                if (
                    claimed is not None
                    and claimed.status == "running"
                    and (claimed.text_turns_claimed > 0)
                ):
                    claimed.text_turns_claimed -= 1

        try:
            with db_session() as action_session:
                if action_session.get_bind().dialect.name == "sqlite":
                    action_session.connection().exec_driver_sql("BEGIN IMMEDIATE")
                current_invite, current_study = _public_invite(
                    action_session, token, for_update=True
                )
                current_live = action_session.scalar(
                    select(VoiceSessionRow)
                    .where(
                        VoiceSessionRow.id == claimed_session_id,
                        VoiceSessionRow.invite_id == current_invite.id,
                    )
                    .with_for_update()
                )
                if current_live is None:
                    raise HTTPException(404, "session not found")
                current_reservation = action_session.scalar(
                    select(CapacityReservationRow)
                    .where(
                        CapacityReservationRow.org_id == org_id,
                        CapacityReservationRow.action_id == session_action_id,
                        CapacityReservationRow.resource_type == "voice_session",
                        CapacityReservationRow.resource_id == str(resource_id),
                        CapacityReservationRow.status == "active",
                    )
                    .with_for_update()
                )
                if current_reservation is None:
                    raise HTTPException(409, "the session authorization has expired")
                org = action_session.scalar(select(Org).where(Org.id == org_id).with_for_update())
                if org is None:
                    raise HTTPException(409, "this session is no longer authorized")
                _require_public_session_continuation(
                    action_session, current_invite, current_study, current_live
                )
                if current_live.status != "running" or current_live.model != "text":
                    raise HTTPException(409, "the session is no longer accepting text turns")
                pool = _build_scoped_pool(
                    action_session,
                    org,
                    action_id=session_action_id,
                    resource_type="voice_session",
                    resource_id=resource_id,
                )
                if pool is None:
                    raise LLMConfigError("no model provider configured")
                response = pool.complete(
                    TaskType.CHAT,
                    system=prompt + chat_note,
                    prompt=(f"Bisheriger Verlauf:\n{history}\n\n" if history and german else "")
                    + (f"Conversation so far:\n{history}\n\n" if history and (not german) else "")
                    + f"Person: {body.message}\n{who['interviewer']}:",
                    max_tokens=400,
                )
        except HTTPException:
            release_text_turn_claim()
            raise
        except (
            BudgetExceededError,
            EntitlementError,
            LLMConfigError,
            ProviderError,
        ) as exc:
            release_text_turn_claim()
            logging.getLogger(__name__).warning(
                "Text interview provider request failed for voice session %s: %s",
                claimed_public_id,
                redact_log_value(str(exc)),
                exc_info=True,
            )
            raise HTTPException(
                503,
                "Die Interviewerin ist gerade nicht erreichbar. Bitte versuchen Sie es gleich noch einmal."
                if german
                else "The interviewer is temporarily unavailable. Please try again shortly.",
            ) from exc
        reply = response.text.strip()
        if reply.lower().startswith(who["interviewer"].lower() + ":"):
            reply = reply[len(who["interviewer"]) + 1 :].strip()
        return {"reply": reply[:2000]}

    @app.post("/public/talk/{token}/sessions/{session_id}/finalize")
    def public_talk_finalize(
        token: str,
        session_id: str,
        body: VoiceSessionFinalize,
        background: BackgroundTasks,
        request: Request,
    ) -> dict[str, Any]:
        """The participant's browser settles the session; the researcher gets
        the interview and one email nudge."""
        _throttle(_talk_limiter, request)
        stop_relay_before_finalize(session_id, invite_token=token)
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            live, study = _public_running_session(session, token, session_id, for_update=True)
            if live.status != "running":
                return {"status": live.status}
            audio_blob = _decoded_session_audio(body, live=live, study=study)
            analysis_scope_ready = _voice_session_analysis_scope_ready(live, study)
            org = session.get(Org, study.org_id)
            assert org is not None
            payload, interview_id, _action_id = _settle_voice_session(
                session,
                live,
                study,
                body,
                org=org,
                ui_language=study.language,
                audio_blob=audio_blob,
            )
            study_title = study.title
            participant_label = live.participant_label
            duration_ms = live.duration_ms
            org_id = study.org_id
        if interview_id is not None:
            if analysis_scope_ready:
                _enqueue_live_analysis(background, interview_id, org_id)
            else:
                _mark_live_analysis_scope_required(interview_id, org_id)
            enqueue_job(
                background,
                _notify_voice_session,
                org_id,
                study_title,
                participant_label,
                duration_ms,
                str(payload.get("interview_id") or ""),
                queue_org_id=org_id,
            )
        return {"status": payload["status"]}

    @app.post("/imports", status_code=201)
    def create_import(
        body: ImportCreate, ctx: AuthContext = Depends(require_auth)
    ) -> dict[str, Any]:
        """Parse an RIS/BibTeX export into a batch of records. Attach the
        batch to a new search (import_batch_ids) and it joins identification
        as its own database arm, with a PRISMA-S entry."""
        with db_session() as session:
            _require_capability(session, ctx, Capability.EXPERT_SEARCH)
        parsed = parse_references(body.filename, body.text)
        if not parsed:
            raise HTTPException(422, "no records found — is this a RIS or BibTeX export?")
        with db_session() as session:
            row = ImportBatchRow(
                org_id=ctx.org_id,
                label=body.label.strip(),
                filename=body.filename.strip(),
                records=parsed,
                count=len(parsed),
            )
            session.add(row)
            session.flush()
            return {
                "id": row.id,
                "label": row.label or row.filename,
                "filename": row.filename,
                "count": row.count,
            }

