    def _owned_reference_connector(
        session: Session, connector_id: str, ctx: AuthContext
    ) -> ReferenceConnectorRow:
        connector = session.scalar(
            select(ReferenceConnectorRow).where(
                ReferenceConnectorRow.public_id == connector_id,
                ReferenceConnectorRow.org_id == ctx.org_id,
            )
        )
        if connector is None and connector_id.isdigit():
            candidate = session.get(ReferenceConnectorRow, int(connector_id))
            connector = candidate if candidate and candidate.org_id == ctx.org_id else None
        if connector is None:
            raise HTTPException(404, "reference connector not found")
        return connector

    def _connector_json(row: ReferenceConnectorRow) -> dict[str, Any]:
        config = dict(row.config or {})
        return {
            "id": row.public_id,
            "provider": row.provider,
            "name": row.name,
            "status": row.status,
            "library_type": row.library_type,
            "library_id": row.library_id,
            "collection_key": row.collection_key,
            "library_version": row.library_version,
            "item_count": row.item_count,
            "last_error": row.last_error,
            "last_synced_at": row.last_synced_at.isoformat() if row.last_synced_at else None,
            "collections": list(config.get("collections") or []),
            "import_batch_id": config.get("import_batch_id"),
            "created_at": row.created_at.isoformat(),
        }

    def _materialize_connector_batch(
        session: Session, connector: ReferenceConnectorRow
    ) -> ImportBatchRow:
        records = connector_records(session, connector.id)
        connector.item_count = len(records)
        config = dict(connector.config or {})
        batch_id = config.get("import_batch_id")
        batch = session.get(ImportBatchRow, int(batch_id)) if batch_id else None
        if batch is None or batch.org_id != connector.org_id:
            batch = ImportBatchRow(
                org_id=connector.org_id,
                label=f"{connector.name} ({connector.provider.title()})",
                filename=f"{connector.provider}-{connector.public_id}.ris",
            )
            session.add(batch)
            session.flush()
            config["import_batch_id"] = batch.id
            connector.config = config
        batch.records = records
        batch.count = len(records)
        return batch

    def _sync_zotero_reference(
        session: Session, connector: ReferenceConnectorRow
    ) -> dict[str, Any]:
        try:
            key = decrypt_credential(connector.credential or "")
        except CredentialError as exc:
            raise HTTPException(503, str(exc)) from exc
        client = ZoteroClient(key, connector.library_type, connector.library_id)
        previous_version = connector.library_version
        try:
            page = client.read_items(
                since=previous_version, collection_key=connector.collection_key
            )
            deleted_keys, deleted_version = client.deleted_since(previous_version)
            collections = client.list_collections()
        except (httpx.HTTPError, ValueError) as exc:
            raise HTTPException(502, "Zotero could not be synchronized") from exc
        rows = [
            (
                str(item.get("key") or (item.get("data") or {}).get("key") or ""),
                int(item.get("version") or (item.get("data") or {}).get("version") or 0),
                zotero_record(item),
            )
            for item in page.items
            if item.get("key") or (item.get("data") or {}).get("key")
        ]
        created, updated_count = upsert_connector_items(session, connector, rows)
        deleted = mark_deleted(session, connector.id, deleted_keys)
        connector.library_version = max(page.library_version, deleted_version, previous_version)
        connector.config = {**dict(connector.config or {}), "collections": collections}
        _materialize_connector_batch(session, connector)
        return {
            "created": created,
            "updated": updated_count,
            "deleted": deleted,
            "library_version": connector.library_version,
            "item_count": connector.item_count,
        }

