    @app.patch("/projects/{project_id}/studies/{study_id}")
    def update_study(
        project_id: int,
        study_id: int,
        body: StudyPatch,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        with db_session() as session:
            project = _owned_project(session, project_id, ctx)
            row = session.get(StudyRow, study_id)
            if row is None or row.project_id != project.id or row.org_id != ctx.org_id:
                raise HTTPException(404, "study not found")
            for field, value in body.model_dump(exclude_unset=True).items():
                setattr(row, field, value)
            _project_event(session, project, ctx, "study_updated", {"study_id": row.id})
            session.flush()
            return _study_json(row)

