    @app.post("/projects/{project_id}/risk-of-bias", status_code=201)
    def create_risk_of_bias(
        project_id: int,
        body: RiskOfBiasCreate,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        with db_session() as session:
            project = _owned_project(session, project_id, ctx)
            if body.study_id is not None:
                study = session.get(StudyRow, body.study_id)
                if study is None or study.project_id != project.id:
                    raise HTTPException(404, "study not found")
            if body.run_id is not None:
                run = _owned_run(session, body.run_id, ctx)
                if run.project_id != project.id:
                    raise HTTPException(404, "run not found")
                if _companion_paper_run_owner(run) is not None:
                    raise HTTPException(
                        409,
                        "Private Companion paper chats cannot be linked to shared reviews",
                    )
            row = RiskOfBiasRow(
                org_id=ctx.org_id,
                project_id=project.id,
                reviewer_user_id=ctx.user_id,
                **body.model_dump(),
            )
            session.add(row)
            session.flush()
            _project_event(session, project, ctx, "risk_of_bias_recorded", {"id": row.id})
            return {
                "id": row.id,
                "tool": row.tool,
                "overall": row.overall,
                "status": row.status,
            }

