    @app.get("/runs/{run_id}/evidence-graph")
    def run_evidence_graph(run_id: str, ctx: AuthContext = Depends(require_auth)) -> dict[str, Any]:
        """A resolved claim-to-source graph for the run's research project."""
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            if run.project_id is None:
                return {
                    "project_id": None,
                    "claims": [],
                    "evidence": [],
                    "edges": [],
                    "summary": {
                        "claims": 0,
                        "evidence": 0,
                        "unsupported": 0,
                        "unverified": 0,
                        "contradictions": 0,
                    },
                    "note": "Assign this search to a project to build a durable evidence graph.",
                }
            project = _owned_project(session, run.project_id, ctx)
            claims = session.scalars(
                select(EvidenceClaimRow)
                .where(
                    EvidenceClaimRow.project_id == project.id,
                    EvidenceClaimRow.org_id == ctx.org_id,
                )
                .order_by(EvidenceClaimRow.updated_at.desc())
            ).all()
            claim_ids = [claim.id for claim in claims]
            links = (
                session.scalars(
                    select(ClaimEvidenceRow)
                    .where(
                        ClaimEvidenceRow.org_id == ctx.org_id,
                        ClaimEvidenceRow.claim_id.in_(claim_ids),
                    )
                    .order_by(ClaimEvidenceRow.id)
                ).all()
                if claim_ids
                else []
            )
            run_work_ids = set(
                session.scalars(
                    select(SourceRecordRow.work_id).where(
                        SourceRecordRow.run_id == run.id,
                        SourceRecordRow.org_id == ctx.org_id,
                    )
                ).all()
            )
            work_target_ids = {
                link.target_id for link in links if link.target_type in {"work", "quote"}
            }
            works = {
                work.id: work
                for work in session.scalars(
                    select(WorkRow).where(WorkRow.id.in_(work_target_ids))
                ).all()
            }
            studies = {
                str(study.id): study
                for study in session.scalars(
                    select(StudyRow).where(
                        StudyRow.project_id == project.id, StudyRow.org_id == ctx.org_id
                    )
                ).all()
            }
            studies.update({study.public_id: study for study in studies.values()})
            datasets = {
                str(dataset.id): dataset
                for dataset in session.scalars(
                    select(ResearchDatasetRow).where(
                        ResearchDatasetRow.project_id == project.id,
                        ResearchDatasetRow.org_id == ctx.org_id,
                    )
                ).all()
            }
            datasets.update({dataset.public_id: dataset for dataset in datasets.values()})
            analyses = {
                str(analysis.id): analysis
                for analysis in session.scalars(
                    select(AnalysisRecipeRow).where(
                        AnalysisRecipeRow.project_id == project.id,
                        AnalysisRecipeRow.org_id == ctx.org_id,
                    )
                ).all()
            }
            analyses.update({analysis.public_id: analysis for analysis in analyses.values()})
            writers = {
                writer.id: writer
                for writer in session.scalars(
                    select(WriterDocumentRow).where(
                        WriterDocumentRow.project_id == project.id,
                        WriterDocumentRow.org_id == ctx.org_id,
                    )
                ).all()
            }
            evidence_by_key: dict[str, dict[str, Any]] = {}
            edges: list[dict[str, Any]] = []
            for link in links:
                key = f"{link.target_type}:{link.target_id}"
                title = link.target_id
                year: int | None = None
                retracted = False
                if link.target_type in {"work", "quote"}:
                    work = works.get(link.target_id)
                    if work:
                        title = work.title
                        year = work.year
                        retracted = bool((work.payload or {}).get("is_retracted", False))
                elif link.target_type == "study":
                    study = studies.get(link.target_id)
                    if study:
                        title = study.title
                elif link.target_type == "dataset":
                    dataset = datasets.get(link.target_id)
                    if dataset:
                        title = dataset.name
                elif link.target_type == "analysis":
                    analysis = analyses.get(link.target_id)
                    if analysis:
                        title = analysis.name
                evidence_by_key.setdefault(
                    key,
                    {
                        "id": key,
                        "target_type": link.target_type,
                        "target_id": link.target_id,
                        "title": title,
                        "year": year,
                        "retracted": retracted,
                        "in_run": link.target_id in run_work_ids,
                    },
                )
                edges.append(
                    {
                        "id": link.id,
                        "claim_id": link.claim_id,
                        "evidence_id": key,
                        "target_type": link.target_type,
                        "target_id": link.target_id,
                        "relationship": link.relationship,
                        "locator": link.locator,
                        "quote": link.quote,
                        "note": link.note,
                        "source_version": link.source_version,
                        "verified": link.verified,
                    }
                )
            links_by_claim: dict[int, list[ClaimEvidenceRow]] = {}
            for link in links:
                links_by_claim.setdefault(link.claim_id, []).append(link)
            claim_payload = []
            for claim in claims:
                resolved_links = links_by_claim.get(claim.id, [])
                payload = _claim_json(claim, resolved_links)
                writer = writers.get(claim.writer_document_id or -1)
                payload["writer_title"] = writer.title if writer else None
                payload["impact"] = (
                    "critical"
                    if any(
                        link.relationship in {"contradicts", "retracted"} for link in resolved_links
                    )
                    else "attention"
                    if any(
                        link.relationship in {"mixed", "outdated", "qualifies"} or not link.verified
                        for link in resolved_links
                    )
                    else "stable"
                    if resolved_links
                    else "unsupported"
                )
                claim_payload.append(payload)
            return {
                "project_id": project.id,
                "project_name": project.name,
                "claims": claim_payload,
                "evidence": list(evidence_by_key.values()),
                "edges": edges,
                "available_evidence": [
                    {
                        "target_type": "work",
                        "target_id": work.id,
                        "title": work.title,
                        "year": work.year,
                    }
                    for work in session.scalars(
                        select(WorkRow)
                        .join(SourceRecordRow, SourceRecordRow.work_id == WorkRow.id)
                        .where(
                            SourceRecordRow.run_id == run.id,
                            SourceRecordRow.org_id == ctx.org_id,
                        )
                        .distinct()
                        .order_by(WorkRow.year.desc())
                        .limit(250)
                    ).all()
                ],
                "writers": [
                    {"id": writer.id, "title": writer.title} for writer in writers.values()
                ],
                "summary": {
                    "claims": len(claims),
                    "evidence": len(evidence_by_key),
                    "unsupported": sum(not links_by_claim.get(claim.id) for claim in claims),
                    "unverified": sum(not link.verified for link in links),
                    "contradictions": sum(
                        link.relationship in {"contradicts", "retracted"} for link in links
                    ),
                },
                "note": "",
            }

    @app.post("/runs/{run_id}/claims", status_code=201)
    def create_run_claim(
        run_id: str, body: ClaimCreate, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            if run.project_id is None:
                raise HTTPException(409, "assign the search to a project first")
            project = _owned_project(session, run.project_id, ctx)
            if body.writer_document_id is not None:
                writer = session.get(WriterDocumentRow, body.writer_document_id)
                if writer is None or writer.org_id != ctx.org_id or writer.project_id != project.id:
                    raise HTTPException(404, "writer document not found")
            row = EvidenceClaimRow(
                org_id=ctx.org_id,
                project_id=project.id,
                owner_user_id=ctx.user_id,
                **body.model_dump(),
            )
            session.add(row)
            session.flush()
            _project_event(
                session,
                project,
                ctx,
                "claim_created",
                {"claim_id": row.id, "run_id": run.id},
            )
            return _claim_json(row)

    @app.patch("/runs/{run_id}/claims/{claim_id}")
    def update_run_claim(
        run_id: str,
        claim_id: int,
        body: ClaimPatch,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            if run.project_id is None:
                raise HTTPException(409, "assign the search to a project first")
            claim = session.get(EvidenceClaimRow, claim_id)
            if claim is None or claim.org_id != ctx.org_id or claim.project_id != run.project_id:
                raise HTTPException(404, "claim not found")
            for field, value in body.model_dump(exclude_unset=True).items():
                setattr(claim, field, value)
            links = session.scalars(
                select(ClaimEvidenceRow).where(
                    ClaimEvidenceRow.claim_id == claim.id,
                    ClaimEvidenceRow.org_id == ctx.org_id,
                )
            ).all()
            return _claim_json(claim, list(links))

