    @app.post("/projects/{project_id}/analyses", status_code=201)
    def create_analysis_recipe(
        project_id: int,
        body: AnalysisRecipeCreate,
        ctx: AuthContext = Depends(require_session),
    ) -> dict[str, Any]:
        with db_session() as session:
            project = _owned_project(session, project_id, ctx)
            dataset = _owned_dataset(session, body.dataset_id, ctx)
            version = (
                session.scalar(
                    select(func.max(DatasetVersionRow.version)).where(
                        DatasetVersionRow.dataset_id == dataset.id
                    )
                )
                or 1
            )
            try:
                result = run_analysis(
                    dict(dataset.profile or {}),
                    kind=body.kind,
                    definition=body.definition,
                )
            except DatasetImportError as exc:
                raise HTTPException(422, str(exc)) from exc
            row = AnalysisRecipeRow(
                org_id=ctx.org_id,
                project_id=project.id,
                dataset_id=dataset.id,
                dataset_version=version,
                name=body.name.strip(),
                kind=body.kind,
                definition=body.definition,
                result=result,
                status="ready",
                created_by=ctx.user_id,
            )
            session.add(row)
            session.flush()
            _project_event(session, project, ctx, "analysis_created", {"analysis_id": row.id})
            return {
                "id": row.id,
                "public_id": row.public_id,
                "dataset_version": row.dataset_version,
                "name": row.name,
                "status": row.status,
            }

