    @app.delete("/projects/{project_id}")
    def delete_project(project_id: int, ctx: AuthContext = Depends(require_auth)) -> dict[str, Any]:
        """Delete a project and every run in it (a running run blocks this)."""
        if ctx.token_kind != "session":
            raise HTTPException(
                403,
                {
                    "code": "project_delete_owner_required",
                    "message": "Deleting a shared project requires the workspace owner.",
                },
            )
        removable_checksums: set[str] = set()
        with db_session() as session:
            actor = session.get(User, ctx.user_id)
            if actor is None or actor.org_id != ctx.org_id or actor.role != "owner":
                raise HTTPException(
                    403,
                    {
                        "code": "project_delete_owner_required",
                        "message": "Deleting a shared project requires the workspace owner.",
                    },
                )
            project = _owned_project(session, project_id, ctx)
            locked_project = session.scalar(
                select(Project)
                .where(Project.id == project.id, Project.org_id == ctx.org_id)
                .with_for_update()
            )
            if locked_project is None:
                raise HTTPException(404, "project not found")
            project = locked_project
            project_runs = session.scalars(select(Run).where(Run.project_id == project_id)).all()
            runs: list[Run] = []
            for run in project_runs:
                if _run_visible_to_user(run, ctx.user_id):
                    runs.append(run)
                else:
                    run.project_id = None
            if any(r.status == "running" for r in runs):
                raise HTTPException(409, "a run in this project is still running; cancel it first")
            document_statement = (
                select(BrainstormProjectDocumentRow)
                .where(
                    BrainstormProjectDocumentRow.org_id == ctx.org_id,
                    BrainstormProjectDocumentRow.project_id == project_id,
                )
                .order_by(
                    BrainstormProjectDocumentRow.user_id,
                    BrainstormProjectDocumentRow.id,
                )
            )
            if session.get_bind().dialect.name != "sqlite":
                document_statement = document_statement.with_for_update()
            session.scalars(document_statement).all()
            synthesis_statement = (
                select(BrainstormProjectSynthesisRow)
                .where(
                    BrainstormProjectSynthesisRow.org_id == ctx.org_id,
                    BrainstormProjectSynthesisRow.project_id == project_id,
                    BrainstormProjectSynthesisRow.status == "pending",
                )
                .order_by(BrainstormProjectSynthesisRow.id)
            )
            if session.get_bind().dialect.name != "sqlite":
                synthesis_statement = synthesis_statement.with_for_update()
            pending_project_syntheses = list(session.scalars(synthesis_statement).all())
            cancel_project_brainstorm_jobs(session, [row.id for row in pending_project_syntheses])
            for synthesis in pending_project_syntheses:
                finish_ai_action(session, synthesis.action_id, status="cancelled")
            for run in runs:
                removable_checksums.update(_delete_run_rows(session, run))
            claim_ids = session.scalars(
                select(EvidenceClaimRow.id).where(EvidenceClaimRow.project_id == project_id)
            ).all()
            if claim_ids:
                session.execute(
                    delete(ClaimEvidenceRow).where(ClaimEvidenceRow.claim_id.in_(claim_ids))
                )
            for child_model in (
                BrainstormProjectSynthesisRow,
                BrainstormProjectDocumentRow,
                SubmissionRow,
                EvidenceClaimRow,
                RiskOfBiasRow,
                AnalysisRecipeRow,
                LibraryAccessGrantRow,
                ProjectEventRow,
                ProjectTaskRow,
                StudyRow,
            ):
                session.execute(delete(child_model).where(child_model.project_id == project_id))
            for linked_model in (
                WriterDocumentRow,
                ResearchDatasetRow,
                LiveCompanionSessionRow,
                LibraryWebSourceRow,
                FigureRow,
                RepositoryAnalysisRow,
                DocumentRow,
                SurveyRow,
                InterviewRow,
                VoiceStudyRow,
                ProtocolRow,
            ):
                session.execute(
                    update(linked_model)
                    .where(linked_model.project_id == project_id)
                    .values(project_id=None)
                )
            session.execute(
                update(KnowledgePageRow)
                .where(
                    KnowledgePageRow.org_id == ctx.org_id,
                    KnowledgePageRow.project_id == project_id,
                )
                .values(
                    project_id=None,
                    revision=KnowledgePageRow.revision + 1,
                    updated_at=datetime.now(UTC),
                )
            )
            session.delete(project)
            deleted_runs = len(runs)
        _cleanup_document_checksums(removable_checksums)
        return {"deleted": project_id, "runs_deleted": deleted_runs}

    @app.get("/runs")
    def list_runs(
        project_id: int | None = None,
        limit: int = 200,
        ctx: AuthContext = Depends(require_auth),
    ) -> list[dict[str, Any]]:
        """The org's runs, newest first — the history/sidebar view."""
        with db_session() as session:
            stmt = select(Run).where(Run.org_id == ctx.org_id)
            if project_id is not None:
                stmt = stmt.where(Run.project_id == project_id)
            runs = [
                run
                for run in session.scalars(stmt.order_by(Run.id.desc()).limit(500)).all()
                if _run_visible_to_user(run, ctx.user_id)
            ][: max(1, min(limit, 500))]
            return [
                {
                    "id": r.id,
                    "public_id": r.public_id,
                    "project_id": r.project_id,
                    "question": r.question,
                    "title": r.title,
                    "status": r.status,
                    "created_at": r.created_at.isoformat(),
                    "finished_at": r.finished_at.isoformat() if r.finished_at else None,
                    "prisma": r.prisma,
                    "is_demo": r.is_demo,
                }
                for r in runs
            ]

    @app.post("/runs", status_code=202)
    def create_run_unfiled(
        body: RunCreate,
        background: BackgroundTasks,
        ctx: AuthContext = Depends(require_auth),
    ) -> dict[str, Any]:
        """Create a run outside any project folder — a chat does not have to
        belong to a project."""
