    @app.post("/runs/{run_id}/share", status_code=201)
    def create_run_share(
        run_id: str, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        """Mint (or return) the public read-only link to this run's record."""
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            if _companion_paper_run_owner(run) is not None:
                raise HTTPException(409, "Private Companion paper chats cannot be shared")
            if run.status != "completed":
                raise HTTPException(409, "share once the run is completed")
            share = session.scalar(select(RunShareRow).where(RunShareRow.run_id == run.id))
            if share is None:
                share = RunShareRow(org_id=ctx.org_id, run_id=run.id, created_by=ctx.user_id)
                session.add(share)
                session.flush()
            return {"token": share.token, "url": _share_url(share.token)}

    @app.delete("/runs/{run_id}/share")
    def delete_run_share(
        run_id: str, ctx: AuthContext = Depends(require_session)
    ) -> dict[str, Any]:
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            share = session.scalar(select(RunShareRow).where(RunShareRow.run_id == run.id))
            if share is not None:
                session.delete(share)
            return {"ok": True}

    def _shared_run(session: Session, token: str) -> Run:
        share = session.scalar(select(RunShareRow).where(RunShareRow.token == token))
        run = session.get(Run, share.run_id) if share is not None else None
        if run is None or run.status != "completed":
            raise HTTPException(404, "this share link is not active")
        return run

    @app.get("/public/runs/{token}")
    def public_shared_run(token: str, request: Request) -> dict[str, Any]:
        """The shared record: frozen protocol, counts, methods and every
        include/exclude decision with its reason. No workspace internals."""
        _throttle(_public_read_limiter, request)
        with db_session() as session:
            run = _shared_run(session, token)
            protocol: ReviewProtocol | None = None
            if run.protocol_id is not None:
                protocol_row = session.get(ProtocolRow, run.protocol_id)
                if protocol_row is not None:
                    protocol = ReviewProtocol.model_validate(protocol_row.payload)
            works = works_for_run(session, run.id, org_id=run.org_id)
            ranking_protocol = protocol or ReviewProtocol(
                question=run.question, query_string=run.question
            )
            retracted_dois = load_retracted_dois(get_settings().data_dir)
            retracted_ids = frozenset(
                work.id for work in works if (work.doi or "").lower() in retracted_dois
            )
            ranked = rank_works(works, ranking_protocol, retracted_ids=retracted_ids)
            final = _final_decisions(session, run.id, run.org_id)
            items: list[dict[str, Any]] = []
            for position, rw in enumerate(ranked, start=1):
                decision = final.get(rw.work.id)
                items.append(
                    {
                        "rank": position,
                        "id": rw.work.id,
                        "title": rw.work.title,
                        "authors": rw.work.authors,
                        "year": rw.work.year,
                        "venue": rw.work.venue,
                        "doi": rw.work.doi,
                        "oa_url": rw.work.oa_url,
                        "cited_by_count": rw.work.cited_by_count,
                        "score": rw.score,
                        "retracted": rw.retracted,
                        "verdict": decision.verdict if decision else None,
                        "verdict_reason": _public_review_reason(decision.reason)
                        if decision
                        else None,
                    }
                )
            return {
                "title": run.title or run.question,
                "question": run.question,
                "created_at": run.created_at.isoformat(),
                "query_string": protocol.query_string if protocol else "",
                "inclusion_criteria": protocol.inclusion_criteria if protocol else [],
                "exclusion_criteria": protocol.exclusion_criteria if protocol else [],
                "prisma": dict(run.prisma or {}),
                "methods": render_methods(session, run),
                "works": items,
            }

