    @app.post("/runs/{run_id}/zotero")
    def sync_zotero(
        run_id: str, body: ZoteroSync, ctx: AuthContext = Depends(require_auth)
    ) -> dict[str, Any]:
        """Push a run's works into the caller's Zotero library (their own key,
        used once and not stored)."""
        if body.library_type not in ("user", "group"):
            raise HTTPException(400, "library_type must be 'user' or 'group'")
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            _require_capability(session, ctx, Capability.EXPERT_SEARCH)
            works = works_for_run(
                session, run.id, included_only=body.included_only, org_id=ctx.org_id
            )
        client = ZoteroClient(body.api_key, body.library_type, body.library_id)
        result = client.create_items(to_zotero_items(works))
        return {
            "created": result.created,
            "failed": result.failed,
            "library": body.library_id,
        }

    @app.post("/runs/{run_id}/reference-connectors/{connector_id}")
    def push_reference_connector(
        run_id: str,
        connector_id: str,
        body: ConnectorPush,
        ctx: AuthContext = Depends(require_auth),
    ) -> dict[str, Any]:
        """Publish a run to a connected Zotero library or Citavi exchange project."""
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            _require_capability(session, ctx, Capability.EXPERT_SEARCH)
            connector = _owned_reference_connector(session, connector_id, ctx)
            works = works_for_run(
                session, run.id, included_only=body.included_only, org_id=ctx.org_id
            )
            known = {
                row.fingerprint
                for row in session.scalars(
                    select(ReferenceConnectorItemRow).where(
                        ReferenceConnectorItemRow.connector_id == connector.id,
                        ReferenceConnectorItemRow.deleted.is_(False),
                    )
                ).all()
            }
            work_payloads = [
                {
                    "title": work.title,
                    "abstract": work.abstract or "",
                    "year": work.year,
                    "doi": work.doi or "",
                    "authors": work.authors,
                    "venue": work.venue or "",
                    "reference_type": work.work_type or "article",
                    "citation_key": "",
                    "keywords": ["SixSentences"],
                    "categories": [],
                    "notes": [source_identifier_note(work)] if source_identifier_note(work) else [],
                    "url": source_record_url(work),
                    "isbn": "",
                    "issn": "",
                    "attachments": [],
                }
                for work in works
            ]
            pending = [
                (work, payload)
                for work, payload in zip(works, work_payloads, strict=True)
                if reference_fingerprint(payload) not in known
            ]
            skipped = len(works) - len(pending)
            if connector.provider == "citavi":
                created, updated_count = upsert_connector_items(
                    session,
                    connector,
                    [(f"six:{work.id}", 1, payload) for work, payload in pending],
                )
                _materialize_connector_batch(session, connector)
                return {
                    "provider": "citavi",
                    "created": created,
                    "updated": updated_count,
                    "skipped": skipped,
                    "failed": 0,
                    "export_url": f"/reference-connectors/{connector.public_id}/export?format=ris",
                }
            try:
                key = decrypt_credential(connector.credential or "")
            except CredentialError as exc:
                raise HTTPException(503, str(exc)) from exc
            client = ZoteroClient(key, connector.library_type, connector.library_id)
            result = client.create_items(to_zotero_items([work for work, _ in pending]))
            sync = _sync_zotero_reference(session, connector)
            return {
                "provider": "zotero",
                "created": result.created,
                "updated": sync["updated"],
                "skipped": skipped,
                "failed": result.failed,
                "library": connector.library_id,
            }

    @app.post("/runs/{run_id}/chat")
    def chat(
        run_id: str, body: ChatRequest, ctx: AuthContext = Depends(require_auth)
    ) -> dict[str, Any]:
        _require_public_chat_web_search_scope(
            body.question, body.web_search_public_data_confirmed, body.web_search_query
        )
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            chat_model = _resolve_run_chat_model_for(session, ctx, run, body.model)
            run.config = {**(run.config or {}), "chat_model": chat_model.id}
            org = session.get(Org, ctx.org_id)
            assert org is not None
            try:
                check_feature(org, "chat")
                if get_settings().websearch_enabled and explicit_web_research_request(
                    body.question
                ):
                    check_capability(org, Capability.DEEP_REVIEW)
                plan = check_can_ask(
                    session,
                    org,
                    multiplier=chat_model.multiplier,
                    input_chars=len(body.question),
                    context_size=body.context_size,
                )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            charge_credits(
                session,
                org,
                action="question",
                credits=question_cost(
                    chat_model.multiplier,
                    plan=plan,
                    input_chars=len(body.question),
                    context_size=body.context_size,
                ),
                run_id=run.id,
                model=chat_model.id,
            )
            selection: dict[str, Any] | None = None
            if body.selection is not None:
                doc = _owned_document(session, body.selection.document_id, ctx)
                work = session.get(WorkRow, doc.work_id)
                selection = {
                    "document_id": doc.id,
                    "work_id": doc.work_id,
                    "title": work.title if work else "the paper",
                    "page": body.selection.page,
                    "quote": body.selection.quote,
                    "checksum": doc.checksum,
                }
            try:
                with (
                    _scoped_action_pool(
                        session,
                        org,
                        action="run_chat",
                        resource_type="run",
                        resource_id=run.id,
                        model_id=chat_model.id,
                        run_id=run.id,
                    ) as pool,
                    chat_turn_scope(body.turn_id),
                ):
                    answer = answer_question(
                        session,
                        run,
                        pool,
                        body.question,
                        context_size=body.context_size,
                        selection=selection,
                        response_language=ctx.language,
                        assistant_preferences=ctx.assistant_preferences,
                        viewer_user_id=ctx.user_id,
                        web_search_public_data_confirmed=body.web_search_public_data_confirmed,
                        web_search_query=body.web_search_query,
                        web_search_notice_version=body.web_search_notice_version,
                    )
            except EntitlementError as exc:
                raise _http_402(exc) from exc
            except LLMConfigError as exc:
                raise HTTPException(
                    503,
                    "The AI assistant is not available right now. Please try again shortly.",
                ) from exc
            except ChatError as exc:
                raise HTTPException(422, str(exc)) from exc
            charge_credits(
                session,
                org,
                action="agent_tools",
                credits=agent_tool_cost(answer.tools_used, chat_model.multiplier, plan=plan)
                + question_settlement_cost(
                    chat_model.multiplier,
                    plan=plan,
                    input_chars=len(body.question),
                    requested_context_size=body.context_size,
                    sources_considered=answer.sources_considered,
                    output_chars=len(answer.answer),
                ),
                run_id=run.id,
                model=chat_model.id,
            )
            return answer.model_dump()

    @app.get("/runs/{run_id}/chat/turns/active")
    def active_chat_turn(
        run_id: str, ctx: AuthContext = Depends(require_auth)
    ) -> dict[str, Any] | None:
        """Discover this user's active turn without exposing its request body."""
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            row = session.scalar(
                select(ChatTurnRow)
                .where(
                    ChatTurnRow.run_id == run.id,
                    ChatTurnRow.org_id == ctx.org_id,
                    ChatTurnRow.user_id == ctx.user_id,
                    ChatTurnRow.active_slot == 1,
                )
                .order_by(ChatTurnRow.id.desc())
                .with_for_update()
            )
            if row is None:
                return None
            _expire_stale_chat_turn(session, row)
            state = _chat_turn_state(row)
            row_id = row.id
            terminal = row.status in _CHAT_TURN_TERMINAL
        if terminal:
            _ensure_chat_turn_terminal_receipt(row_id)
        return state

