    @app.post("/runs/{run_id}/chat/turns/{turn_id}/stop")
    def stop_chat_turn(
        run_id: str, turn_id: str, ctx: AuthContext = Depends(require_auth)
    ) -> dict[str, Any]:
        """Request cancellation, including before the matching stream starts."""
        if not re.fullmatch("[A-Za-z0-9][A-Za-z0-9_-]{7,63}", turn_id):
            raise HTTPException(422, "invalid turn id")
        now = datetime.now(UTC)
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            _signal_chat_turn_cancel(ctx.org_id, run.id, turn_id)
            session.scalar(select(Run.id).where(Run.id == run.id).with_for_update())
            turn = session.scalar(
                select(ChatTurnRow).where(
                    ChatTurnRow.run_id == run.id,
                    ChatTurnRow.turn_id == turn_id,
                    ChatTurnRow.org_id == ctx.org_id,
                )
            )
            if turn is not None and turn.user_id != ctx.user_id:
                raise HTTPException(404, "chat turn not found")
            if turn is None:
                turn = ChatTurnRow(
                    turn_id=turn_id,
                    org_id=ctx.org_id,
                    run_id=run.id,
                    user_id=ctx.user_id,
                    action_id=_chat_turn_action_id(ctx.org_id, run.id, turn_id),
                    status="cancelled",
                    active_slot=None,
                    cancel_requested_at=now,
                    finished_at=now,
                )
                session.add(turn)
                resolved_status = "cancelled"
            elif turn.status == "queued":
                updated_status = session.execute(
                    update(ChatTurnRow)
                    .where(ChatTurnRow.id == turn.id, ChatTurnRow.status == "queued")
                    .values(
                        status="cancelled",
                        active_slot=None,
                        cancel_requested_at=turn.cancel_requested_at or now,
                        finished_at=now,
                    )
                    .returning(ChatTurnRow.status)
                ).scalar_one_or_none()
                session.expire_all()
                resolved_status = (
                    str(updated_status)
                    if updated_status is not None
                    else str(
                        session.scalar(select(ChatTurnRow.status).where(ChatTurnRow.id == turn.id))
                    )
                )
            elif turn.status == "running":
                updated_status = session.execute(
                    update(ChatTurnRow)
                    .where(ChatTurnRow.id == turn.id, ChatTurnRow.status == "running")
                    .values(
                        status="cancel_requested",
                        cancel_requested_at=turn.cancel_requested_at or now,
                    )
                    .returning(ChatTurnRow.status)
                ).scalar_one_or_none()
                session.expire_all()
                resolved_status = (
                    str(updated_status)
                    if updated_status is not None
                    else str(
                        session.scalar(select(ChatTurnRow.status).where(ChatTurnRow.id == turn.id))
                    )
                )
            else:
                resolved_status = turn.status
            session.flush()
            turn_row_id = turn.id
            if resolved_status in _CHAT_TURN_TERMINAL:
                terminal_turn = session.scalar(
                    select(ChatTurnRow)
                    .where(ChatTurnRow.id == turn_row_id)
                    .with_for_update()
                    .execution_options(populate_existing=True)
                )
                if terminal_turn is not None:
                    _persist_chat_turn_terminal_receipt(session, terminal_turn)
                    ensure_chat_turn_terminal_event(session, terminal_turn)
        if resolved_status in _CHAT_TURN_TERMINAL:
            _ensure_chat_turn_terminal_receipt(turn_row_id)
        return {"turn_id": turn_id, "status": resolved_status}

    @app.post("/runs/{run_id}/chat/stream")
    def stream_chat(
        run_id: str, body: ChatRequest, ctx: AuthContext = Depends(require_auth)
    ) -> StreamingResponse:
        """Stream one durable, cancellable and idempotent grounded chat turn."""
        _require_public_chat_web_search_scope(
            body.question,
            body.web_search_public_data_confirmed,
            body.web_search_query,
            require_topic=False,
        )
        replay: tuple[str, dict[str, Any]] | None = None
        chat_model: ChatModel | None = None
        selection: dict[str, Any] | None = None
        try:
            with db_session() as session:
                run = _owned_run(session, run_id, ctx)
                resolved_run_id = run.id
                session.scalar(select(Run.id).where(Run.id == run.id).with_for_update())
                turn = session.scalar(
                    select(ChatTurnRow).where(
                        ChatTurnRow.run_id == run.id,
                        ChatTurnRow.turn_id == body.turn_id,
                        ChatTurnRow.org_id == ctx.org_id,
                    )
                )
                if turn is not None:
                    if turn.user_id != ctx.user_id:
                        raise HTTPException(404, "chat turn not found")
                    replay_model_id = turn.model
                    if body.model is not None:
                        replay_model_id = _resolve_chat_model_for(session, ctx, body.model).id
                    replay_hash = _chat_turn_request_hash(
                        body.model_dump(mode="json", exclude={"turn_id", "model"}),
                        replay_model_id,
                    )
                    if turn.request_hash and turn.request_hash != replay_hash:
                        raise HTTPException(409, "turn id is already bound to another request")
                    if _chat_turn_is_cancelled(turn.status):
                        replay = ("turn.cancelled", {"status": "cancelled"})
                    elif turn.status == "completed":
                        replay = ("turn.completed", {"answer": turn.answer or {}})
                    elif turn.status == "failed":
                        replay = (
                            "turn.failed",
                            {"message": turn.error_message or "This turn could not be completed."},
                        )
                    else:
                        raise HTTPException(
                            409,
                            {
                                "message": "this turn is already running",
                                "turn_id": turn.turn_id,
                            },
                        )
                else:
                    _require_public_chat_web_search_scope(
                        body.question,
                        body.web_search_public_data_confirmed,
                        body.web_search_query,
                    )
                    chat_model = _resolve_run_chat_model_for(session, ctx, run, body.model)
                    run.config = {**(run.config or {}), "chat_model": chat_model.id}
                    org = session.get(Org, ctx.org_id)
                    assert org is not None
                    try:
                        check_feature(org, "chat")
                        if get_settings().websearch_enabled and explicit_web_research_request(
                            body.question
                        ):
                            check_capability(org, Capability.DEEP_REVIEW)
                        check_can_ask(
                            session,
                            org,
                            multiplier=chat_model.multiplier,
                            input_chars=len(body.question),
                            context_size=body.context_size,
                        )
                    except EntitlementError as exc:
                        raise _http_402(exc) from exc
                    if body.selection is not None:
                        doc = _owned_document(session, body.selection.document_id, ctx)
                        work = session.get(WorkRow, doc.work_id)
                        selection = {
                            "document_id": doc.id,
                            "work_id": doc.work_id,
                            "title": work.title if work else "the paper",
                            "page": body.selection.page,
                            "quote": body.selection.quote,
                            "checksum": doc.checksum,
                        }
                    request_hash = _chat_turn_request_hash(
                        body.model_dump(mode="json", exclude={"turn_id", "model"}),
                        chat_model.id,
                    )
                    active = session.scalar(
                        select(ChatTurnRow)
                        .where(ChatTurnRow.run_id == run.id, ChatTurnRow.active_slot == 1)
                        .with_for_update()
                        .execution_options(populate_existing=True)
                    )
                    if active is not None and _expire_stale_chat_turn(session, active):
                        _persist_chat_turn_terminal_receipt(session, active)
                        active = None
                    if active is not None:
                        detail: dict[str, Any] = {"message": "another turn is already running"}
                        if active.user_id == ctx.user_id:
                            detail["turn_id"] = active.turn_id
                        raise HTTPException(409, detail)
                    turn = ChatTurnRow(
                        turn_id=body.turn_id,
                        org_id=ctx.org_id,
                        run_id=run.id,
                        user_id=ctx.user_id,
                        question=body.question,
                        request_hash=request_hash,
                        model=chat_model.id,
                        status="queued",
                        active_slot=1,
                        action_id=_chat_turn_action_id(ctx.org_id, run.id, body.turn_id),
                    )
                    session.add(turn)
                    session.flush()
                turn_row_id = turn.id
        except IntegrityError as exc:
            raise HTTPException(409, "this chat turn already exists") from exc
        if replay is not None:
            return _single_chat_turn_sse(turn_row_id, body.turn_id)
        assert chat_model is not None
        buffered_delta = ""
        buffered_reasoning = ""
        deferred_answer_completed: dict[str, Any] | None = None
        streamed_answer = ""
        cancel_event = _chat_turn_cancel_event(ctx.org_id, resolved_run_id, body.turn_id)
        cancel_probe_lock = threading.Lock()
        last_cancel_probe = 0.0

        def cancelled() -> bool:
            nonlocal last_cancel_probe
            if cancel_event.is_set():
                return True
            now = time.monotonic()
            with cancel_probe_lock:
                if cancel_event.is_set():
                    return True
                if now - last_cancel_probe < 0.15:
                    return False
                last_cancel_probe = now
                with db_session() as probe_session:
                    status = probe_session.scalar(
                        select(ChatTurnRow.status).where(ChatTurnRow.id == turn_row_id)
                    )
                if status is None or status not in {"queued", "running"}:
                    cancel_event.set()
                    return True
            return False

        def raise_if_cancelled() -> None:
            if cancelled():
                raise LLMCancelledError("chat turn cancelled")

        def emit(
            event: str, payload: dict[str, Any], *, event_session: Session | None = None
        ) -> None:
            if event_session is not None:
                append_chat_turn_event(event_session, turn_row_id, event=event, payload=payload)
                return
            with db_session() as durable_session:
                append_chat_turn_event(durable_session, turn_row_id, event=event, payload=payload)

        def flush_delta(event_session: Session | None = None) -> None:
            nonlocal buffered_delta
            if buffered_delta:
                emit(
                    "answer.delta",
                    {"delta": buffered_delta},
                    event_session=event_session,
                )
                buffered_delta = ""

        def flush_reasoning(event_session: Session | None = None) -> None:
            nonlocal buffered_reasoning
            if buffered_reasoning:
                emit(
                    "reasoning.delta",
                    {"reasoning": buffered_reasoning},
                    event_session=event_session,
                )
                buffered_reasoning = ""

        def on_delta(delta: str) -> None:
            nonlocal buffered_delta, streamed_answer
            raise_if_cancelled()
            flush_reasoning()
            streamed_answer += delta
            buffered_delta += delta
            if len(buffered_delta) >= 28 or "\n" in buffered_delta:
                flush_delta()

        def on_reasoning(delta: str) -> None:
            nonlocal buffered_reasoning
            raise_if_cancelled()
            buffered_reasoning += delta
            if len(buffered_reasoning) >= 28 or "\n" in buffered_reasoning:
                flush_reasoning()

        def on_stream_reset() -> None:
            nonlocal buffered_delta, buffered_reasoning, streamed_answer
            raise_if_cancelled()
            buffered_delta = ""
            buffered_reasoning = ""
            streamed_answer = ""
            emit(
                "answer.reset",
                {
                    "phase": "writing",
                    "label": "Continuing with a stable research route",
                },
            )

        def on_event(event: str, payload: dict[str, Any]) -> None:
            nonlocal deferred_answer_completed
            raise_if_cancelled()
            if event == "answer.completed":
                deferred_answer_completed = dict(payload)
                return
            emit(event, payload)

        def persist_cancelled_partial() -> None:
            """Keep already visible prose stable after a stop and page reload."""
            content = streamed_answer.strip()
            if not content:
                return
            with db_session() as partial_session:
                existing = partial_session.scalar(
                    select(ChatMessageRow).where(
                        ChatMessageRow.run_id == resolved_run_id,
                        ChatMessageRow.org_id == ctx.org_id,
                        ChatMessageRow.role == "assistant",
                        ChatMessageRow.payload["turn_id"].as_string() == body.turn_id,
                    )
                )
                partial_payload = {
                    "turn_id": body.turn_id,
                    "cancelled": True,
                    "partial": True,
                }
                if existing is not None:
                    existing.content = content
                    existing.payload = {**(existing.payload or {}), **partial_payload}
                else:
                    partial_session.add(
                        ChatMessageRow(
                            org_id=ctx.org_id,
                            run_id=resolved_run_id,
                            role="assistant",
                            content=content,
                            citations=[],
                            payload=partial_payload,
                        )
                    )
                turn = partial_session.get(ChatTurnRow, turn_row_id)
                if turn is not None and turn.status in {
                    "cancel_requested",
                    "cancelled",
                }:
                    turn.answer = {
                        "answer": content,
                        "cancelled": True,
                        "partial": True,
                    }

        def maintain_worker_lease(stop: threading.Event) -> None:
            while not stop.wait(_CHAT_TURN_HEARTBEAT_SECONDS):
                try:
                    live = _heartbeat_chat_turn(turn_row_id)
                except Exception:
                    logging.getLogger(__name__).warning(
                        "chat turn heartbeat failed",
                        extra={"run_id": resolved_run_id, "turn_id": body.turn_id},
                        exc_info=True,
                    )
                    continue
                if not live:
                    return

        def produce() -> None:
            heartbeat_stop = threading.Event()
            heartbeat_thread = threading.Thread(
                target=maintain_worker_lease,
                args=(heartbeat_stop,),
                daemon=True,
                name=f"chat-heartbeat-{resolved_run_id}-{body.turn_id[:8]}",
            )
            heartbeat_thread.start()
            try:
                with db_session() as session:
                    turn = session.scalar(
                        select(ChatTurnRow).where(ChatTurnRow.id == turn_row_id).with_for_update()
                    )
                    if turn is None or _chat_turn_is_cancelled(turn.status):
                        raise LLMCancelledError("chat turn cancelled before start")
                    if turn.status != "queued":
                        raise RuntimeError("chat turn was already claimed")
                    turn.status = "running"
                    turn.started_at = datetime.now(UTC)
                    turn.updated_at = turn.started_at
                    append_chat_turn_event_for_row(
                        session,
                        turn,
                        event="turn.started",
                        payload={"status": "running"},
                    )
                    session.commit()
                    run = session.get(Run, resolved_run_id)
                    org = session.get(Org, ctx.org_id)
                    if run is None or run.org_id != ctx.org_id or org is None:
                        raise RuntimeError("conversation is no longer available")
                    raise_if_cancelled()
                    plan = check_can_ask(
                        session,
                        org,
                        multiplier=chat_model.multiplier,
                        input_chars=len(body.question),
                        context_size=body.context_size,
                    )
                    turn = session.get(ChatTurnRow, turn_row_id)
                    assert turn is not None
                    if not turn.base_charged:
                        raise_if_cancelled()
                        charge_credits(
                            session,
                            org,
                            action="question",
                            credits=question_cost(
                                chat_model.multiplier,
                                plan=plan,
                                input_chars=len(body.question),
                                context_size=body.context_size,
                            ),
                            run_id=run.id,
                            model=chat_model.id,
                        )
                        turn.base_charged = True
                        session.commit()
                    with _scoped_action_pool(
                        session,
                        org,
                        action="run_chat",
                        resource_type="chat_turn",
                        resource_id=body.turn_id,
                        model_id=chat_model.id,
                        run_id=run.id,
                        action_id=turn.action_id,
                    ) as pool:
                        pool.cancel_check = cancelled
                        with chat_turn_scope(body.turn_id):
                            answer = answer_question(
                                session,
                                run,
                                pool,
                                body.question,
                                context_size=body.context_size,
                                selection=selection,
                                response_language=ctx.language,
                                assistant_preferences=ctx.assistant_preferences,
                                viewer_user_id=ctx.user_id,
                                event_sink=on_event,
                                delta_sink=on_delta,
                                reasoning_sink=on_reasoning
                                if chat_model.reasoning_visible
                                else None,
                                stream_reset_sink=on_stream_reset,
                                web_search_public_data_confirmed=body.web_search_public_data_confirmed,
                                web_search_query=body.web_search_query,
                                web_search_notice_version=body.web_search_notice_version,
                            )
                    raise_if_cancelled()
                    flush_delta(session)
                    flush_reasoning(session)
                    if deferred_answer_completed is not None:
                        emit(
                            "answer.completed",
                            deferred_answer_completed,
                            event_session=session,
                        )
                    turn = session.scalar(
                        select(ChatTurnRow)
                        .where(ChatTurnRow.id == turn_row_id)
                        .with_for_update()
                        .execution_options(populate_existing=True)
                    )
                    assert turn is not None
                    if turn.status != "running":
                        raise LLMCancelledError("chat turn lease is no longer active")
                    if not turn.settlement_charged:
                        charge_credits(
                            session,
                            org,
                            action="agent_tools",
                            credits=agent_tool_cost(
                                answer.tools_used, chat_model.multiplier, plan=plan
                            )
                            + question_settlement_cost(
                                chat_model.multiplier,
                                plan=plan,
                                input_chars=len(body.question),
                                requested_context_size=body.context_size,
                                sources_considered=answer.sources_considered,
                                output_chars=len(answer.answer),
                            ),
                            run_id=run.id,
                            model=chat_model.id,
                        )
                        turn.settlement_charged = True
                    answer_payload = answer.model_dump()
                    turn.answer = answer_payload
                    turn.status = "completed"
                    turn.active_slot = None
                    turn.finished_at = datetime.now(UTC)
                    append_chat_turn_event_for_row(
                        session,
                        turn,
                        event="turn.completed",
                        payload={"answer": answer_payload},
                        trusted_payload=True,
                    )
                    session.commit()
            except LLMCancelledError:
                flush_delta()
                flush_reasoning()
                persist_cancelled_partial()
                status = _finish_chat_turn(turn_row_id, status="cancelled")
                if status == "cancelled":
                    _ensure_chat_turn_terminal_receipt(turn_row_id)
            except EntitlementError as exc:
                message = str(exc)
                flush_delta()
                flush_reasoning()
                status = _finish_chat_turn(turn_row_id, status="failed", error_message=message)
                if status == "cancelled":
                    persist_cancelled_partial()
                    _ensure_chat_turn_terminal_receipt(turn_row_id)
                else:
                    _ensure_chat_turn_terminal_receipt(turn_row_id)
            except (LLMConfigError, ChatError) as exc:
                logging.getLogger(__name__).warning(
                    "streamed chat turn failed reason=chat_or_configuration_error run_id=%s turn_id=%s error_class=%s cause_class=%s",
                    resolved_run_id,
                    body.turn_id,
                    type(exc).__name__,
                    type(exc.__cause__).__name__ if exc.__cause__ is not None else "none",
                )
                message = "The AI assistant could not complete this turn. Please try again shortly."
                flush_delta()
                flush_reasoning()
                status = _finish_chat_turn(turn_row_id, status="failed", error_message=message)
                if status == "cancelled":
                    persist_cancelled_partial()
                    _ensure_chat_turn_terminal_receipt(turn_row_id)
                else:
                    _ensure_chat_turn_terminal_receipt(turn_row_id)
            except Exception:
                logging.exception("streamed chat turn failed", extra={"run_id": resolved_run_id})
                message = "Something interrupted this answer. Your completed research steps are still saved; please try again."
                flush_delta()
                flush_reasoning()
                status = _finish_chat_turn(turn_row_id, status="failed", error_message=message)
                if status == "cancelled":
                    persist_cancelled_partial()
                    _ensure_chat_turn_terminal_receipt(turn_row_id)
                else:
                    _ensure_chat_turn_terminal_receipt(turn_row_id)
            finally:
                heartbeat_stop.set()
                heartbeat_thread.join(timeout=0.25)
                _release_chat_turn_cancel_event(ctx.org_id, resolved_run_id, body.turn_id)

        worker = threading.Thread(
            target=produce,
            daemon=True,
            name=f"chat-{resolved_run_id}-{body.turn_id[:8]}",
        )
        worker.start()
        return _chat_turn_follow_response(row_id=turn_row_id, turn_id=body.turn_id, last_event_id=0)

    @app.get("/runs/{run_id}/chat")
    def get_chat(run_id: str, ctx: AuthContext = Depends(require_auth)) -> list[dict[str, Any]]:
        with db_session() as session:
            run = _owned_run(session, run_id, ctx)
            return [
                {
                    "id": m.id,
                    "role": m.role,
                    "content": m.content,
                    "citations": m.citations,
                    "payload": web_citation_payload(m.payload),
                    "created_at": m.created_at.isoformat(),
                }
                for m in chat_history(session, run.id, org_id=ctx.org_id)
            ]

    def _paper_chat_receipt_statement(
        ctx: AuthContext, client_request_id: str, *, for_update: bool = False
    ) -> Any:
        statement = select(CompanionPaperChatReceiptRow).where(
            CompanionPaperChatReceiptRow.org_id == ctx.org_id,
            CompanionPaperChatReceiptRow.user_id == ctx.user_id,
            CompanionPaperChatReceiptRow.client_request_id == client_request_id,
        )
        return statement.with_for_update() if for_update else statement

    def _owned_companion_paper_chat(
        session: Session, chat_id: str, ctx: AuthContext
    ) -> tuple[Run, CompanionPaperChatReceiptRow, DocumentRow]:
        run = session.scalar(select(Run).where(Run.public_id == chat_id, Run.org_id == ctx.org_id))
        if run is None or not _run_visible_to_user(run, ctx.user_id):
            raise HTTPException(404, "paper chat not found")
        config = dict(run.config or {})
        if config.get("surface") != "companion_paper":
            raise HTTPException(404, "paper chat not found")
        receipt = session.scalar(
            select(CompanionPaperChatReceiptRow).where(
                CompanionPaperChatReceiptRow.org_id == ctx.org_id,
                CompanionPaperChatReceiptRow.user_id == ctx.user_id,
                CompanionPaperChatReceiptRow.run_id == run.id,
                CompanionPaperChatReceiptRow.status == "ready",
            )
        )
        if receipt is None or receipt.chat_document_id is None:
            raise HTTPException(404, "paper chat not found")
        document = session.get(DocumentRow, receipt.chat_document_id)
        if (
            document is None
            or document.org_id != ctx.org_id
            or document.run_id != run.id
            or (not document.checksum)
            or (not document.storage_path)
        ):
            raise HTTPException(404, "paper chat PDF is unavailable")
        return (run, receipt, document)

    def _paper_chat_result(run: Run, receipt: CompanionPaperChatReceiptRow) -> dict[str, Any]:
        result = copy.deepcopy(dict(receipt.result or {}))
        if not result:
            raise HTTPException(409, "paper chat is still being prepared; retry")
        chat = dict(result.get("chat") or {})
        chat.update(
            {
                "id": run.public_id,
                "title": run.title or run.question,
                "web_url": f"{get_settings().app_url}/r/{run.public_id}",
            }
        )
        result["chat"] = chat
        return result

    @app.post("/companion/paper-chats", status_code=201)
    def create_companion_paper_chat(
        body: CompanionPaperChatCreate,
        response: Response,
        ctx: AuthContext = Depends(require_auth),
        _upload_slot: None = Depends(_companion_paper_upload_slot),
    ) -> dict[str, Any]:
        del _upload_slot
        if not _rate_limit_allowed(
            _companion_paper_upload_limiter, _companion_paper_upload_rate_key(ctx)
        ):
            raise HTTPException(
                429,
                {
                    "code": "companion_upload_rate_limited",
                    "message": "Too many paper uploads. Please retry in one minute.",
                },
                headers={"Retry-After": "60"},
            )
        try:
            content = base64.b64decode(body.content_base64, validate=True)
        except (binascii.Error, ValueError) as exc:
            raise HTTPException(422, "content_base64 is not valid base64") from exc
        if len(content) > MAX_COMPANION_PAPER_BYTES:
            raise HTTPException(413, "Companion PDFs are limited to 25 MiB")
        body.content_base64 = ""
        if content[:5] != b"%PDF-":
            raise HTTPException(422, "Companion paper chats accept PDF bytes only")
        checksum = hashlib.sha256(content).hexdigest()
        if not secrets.compare_digest(checksum, body.sha256.lower()):
            raise HTTPException(422, "PDF checksum does not match the confirmed bytes")
        payload_sha256 = hashlib.sha256(
            json.dumps(
                {
                    "filename": body.filename,
                    "project_id": body.project_id,
                    "sha256": checksum,
                },
                sort_keys=True,
                separators=(",", ":"),
            ).encode()
        ).hexdigest()
        now = datetime.now(UTC)
        claim_token = secrets.token_urlsafe(24)
        claimed = False
        with db_session() as session:
            if session.get_bind().dialect.name == "sqlite":
                session.connection().exec_driver_sql("BEGIN IMMEDIATE")
            _require_capability(session, ctx, Capability.RESEARCH_STUDIO)
            if body.project_id is not None:
                _owned_project(session, body.project_id, ctx)
            receipt = session.scalar(
                _paper_chat_receipt_statement(
                    ctx,
                    body.client_request_id,
                    for_update=session.get_bind().dialect.name != "sqlite",
                )
            )
            if receipt is not None:
                if not secrets.compare_digest(receipt.payload_sha256, payload_sha256):
                    raise HTTPException(
                        409, "client_request_id was already used for different content"
                    )
                if receipt.status == "ready" and receipt.run_id is not None:
                    run = session.get(Run, receipt.run_id)
                    if run is None or not _run_visible_to_user(run, ctx.user_id):
                        raise HTTPException(404, "paper chat not found")
                    response.status_code = 200
                    return _paper_chat_result(run, receipt)
                updated_at = receipt.updated_at
                if updated_at.tzinfo is None:
                    updated_at = updated_at.replace(tzinfo=UTC)
                if now - updated_at < timedelta(minutes=5):
                    raise HTTPException(
                        409,
                        {
                            "code": "paper_chat_processing",
                            "message": "This paper chat is still being prepared; retry shortly.",
                        },
                    )
                receipt.updated_at = now
                receipt.claim_token = claim_token
                receipt.status = "processing"
                receipt.result = {}
                claimed = True
            else:
                receipt = CompanionPaperChatReceiptRow(
                    org_id=ctx.org_id,
                    user_id=ctx.user_id,
                    client_request_id=body.client_request_id,
                    payload_sha256=payload_sha256,
                    claim_token=claim_token,
                    status="processing",
                    result={},
                )
                session.add(receipt)
                try:
                    session.flush()
                except IntegrityError as exc:
                    session.rollback()
                    raced = session.scalar(
                        _paper_chat_receipt_statement(ctx, body.client_request_id)
                    )
                    if raced is None:
                        raise HTTPException(409, "paper chat reservation raced; retry") from exc
                    if not secrets.compare_digest(raced.payload_sha256, payload_sha256):
                        raise HTTPException(
                            409,
                            "client_request_id was already used for different content",
                        ) from exc
                    raise HTTPException(
                        409,
                        {
                            "code": "paper_chat_processing",
                            "message": "This paper chat is still being prepared; retry shortly.",
                        },
                    ) from exc
                claimed = True
        if not claimed:
            raise HTTPException(409, "paper chat reservation was not acquired")
        try:
            upload = _ingest_request(
                DocumentCreate(filename=body.filename, project_id=body.project_id),
                ctx,
                None,
                predecoded_content=content,
            )
            with db_session() as session:
                if session.get_bind().dialect.name == "sqlite":
                    session.connection().exec_driver_sql("BEGIN IMMEDIATE")
                receipt = session.scalar(
                    _paper_chat_receipt_statement(
                        ctx,
                        body.client_request_id,
                        for_update=session.get_bind().dialect.name != "sqlite",
                    )
                )
                if (
                    receipt is None
                    or not secrets.compare_digest(receipt.payload_sha256, payload_sha256)
                    or (not secrets.compare_digest(receipt.claim_token, claim_token))
                ):
                    raise HTTPException(409, "paper chat reservation was lost")
                library_document = session.get(DocumentRow, int(upload["id"]))
                if (
                    library_document is None
                    or library_document.org_id != ctx.org_id
                    or library_document.run_id is not None
                    or (not library_document.checksum)
                ):
                    raise HTTPException(409, "Library PDF could not be prepared")
                title = str(upload.get("title") or body.filename).strip() or body.filename
                run = Run(
                    org_id=ctx.org_id,
                    project_id=body.project_id,
                    question=f"Discuss this paper: {title}",
                    title=title[:300],
                    status=RunStatus.COMPLETED.value,
                    config={
                        "mode": "ask",
                        "model": "auto",
                        "language": ctx.language,
                        "git_revision": current_git_revision(),
                        "surface": "companion_paper",
                        "owner_user_id": ctx.user_id,
                        "library_document_id": library_document.id,
                        "upload_client_request_id": body.client_request_id,
                        "upload_payload_sha256": payload_sha256,
                    },
                    finished_at=now,
                )
                session.add(run)
                session.flush()
                _attach_documents(session, ctx, run.id, [library_document.id])
                chat_document = session.scalar(
                    select(DocumentRow)
                    .where(
                        DocumentRow.org_id == ctx.org_id,
                        DocumentRow.run_id == run.id,
                        DocumentRow.checksum == library_document.checksum,
                    )
                    .order_by(DocumentRow.id.desc())
                )
                if chat_document is None:
                    raise HTTPException(409, "paper chat document could not be attached")
                run.config = {
                    **dict(run.config or {}),
                    "chat_document_id": chat_document.id,
                }
                metadata_fields_added = sorted(
                    {str(field) for field in upload.get("metadata_fields_added") or []}
                )
                warnings = sorted({str(code) for code in upload.get("warnings") or []})
                status = (
                    "metadata_enriched"
                    if upload.get("deduplicated") and metadata_fields_added
                    else "already_saved"
                    if upload.get("deduplicated")
                    else "created"
                )
                result = {
                    "client_request_id": body.client_request_id,
                    "status": status,
                    "paper": {
                        "library_document_id": library_document.id,
                        "chat_document_id": chat_document.id,
                        "title": title,
                        "work_id": library_document.work_id,
                        "verified": bool(upload.get("verified")),
                        "text_status": library_document.text_status,
                        "byte_size": library_document.byte_size,
                        "metadata_fields_added": metadata_fields_added,
                        "warnings": warnings,
                    },
                    "chat": {
                        "id": run.public_id,
                        "title": run.title or run.question,
                        "web_url": f"{get_settings().app_url}/r/{run.public_id}",
                    },
                }
                receipt.status = "ready"
                receipt.run_id = run.id
                receipt.library_document_id = library_document.id
                receipt.chat_document_id = chat_document.id
                receipt.result = result
                receipt.updated_at = datetime.now(UTC)
                session.flush()
                response.status_code = 201 if status == "created" else 200
                return result
        except Exception:
            _abandon_companion_paper_reservation(
                ctx, body.client_request_id, payload_sha256, claim_token
            )
            raise

