    def _companion_paper_selection(
        document: DocumentRow, selection: CompanionPaperSelection
    ) -> ChatSelection:
        content = LocalDocumentStore(get_settings().documents_dir).get(document.checksum or "")
        page_text = (
            extract_page_text(content, selection.page)
            if content is not None and content[:5] == b"%PDF-"
            else None
        )
        if page_text is None:
            raise HTTPException(422, "the selected PDF page is unavailable")

        def normalized(value: str) -> str:
            translation: dict[int, str] = {
                ord("“"): '"',
                ord("”"): '"',
                ord("–"): "-",
                ord("—"): "-",
                ord("\xad"): "",
            }
            folded = unicodedata.normalize("NFKC", value).translate(translation)
            folded = re.sub("-\\s+", "", folded).replace("-", "")
            return re.sub("\\s+", " ", folded).strip().casefold()

        quote = normalized(selection.quote)
        if not quote or quote not in normalized(page_text):
            raise HTTPException(
                422,
                {
                    "code": "selection_not_on_page",
                    "message": "The selected passage was not found on the claimed PDF page.",
                },
            )
        return ChatSelection(document_id=document.id, page=selection.page, quote=selection.quote)

